import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"lng-007","version":2,"slug":"erswo-and-ante-amharic-s-polite-you-that-borrows-the-plural","contentType":"note","category":"communication","title":{"ar":"كيف يخاطب الأمهريون من يكبرهم","de":"Das höfliche Du, das den Plural leiht","en":"Amharic's polite you that borrows the plural"},"deck":{"ar":"في الأمهرية تفرّق صيغة المخاطبة بين ante وerswo، فيتغيّر الفعل وتتغيّر المسافة بين الناس في اللحظة نفسها.","de":"Im Amharischen trennt eine kleine Pronomenwahl zwischen ante und erswo die Menschen, und das Verb zeigt sofort, wie nah man sich steht.","en":"A small pronoun choice between ante and erswo decides how people address each other in the highlands, and the verb follows at once."},"teaser":{"ar":"موظفة شابة في أديس تنتقل في دقيقة واحدة بين مخاطبة زبون مسنّ وزميل في عمرها، دون أن ينتبه أحد.","de":"Eine junge Angestellte in Addis wechselt binnen einer Minute zwischen einer älteren Kundin und einem gleichaltrigen Kollegen, ohne dass es jemand bemerkt.","en":"A young clerk in Addis switches between an older customer and a colleague her own age within a minute, and nobody notices the grammar move."},"readingMinutes":1,"sections":{"ar":[{"heading":"ضمير يجرّ معه الجمع","paragraphs":["تميّز الأمهرية بين ante للمفرد المذكّر وerswo للمخاطبة المهذّبة، وهذه الأخيرة تأخذ تصريف فعل جمع.","يُستخدم هذا الضمير صعودًا في السنّ والرتبة، ويخاطب به العاملون في الخدمات زبائنهم، بينما قد يبقى الوالدان يتلقّيان ante من أبنائهما.","الاتفاق يتبع الضمير: erswo endet naweot? تأتي بفعل جمع لا يأخذه فاعل مفرد."]},{"heading":"ما بين الدفء والوقاحة","paragraphs":["قد يبدو استعمال ante مبكرًا دافئًا أو فظًّا بحسب الموقف، ويلجأ سكان المدن كثيرًا إلى الألقاب لتدبير هذه المسافة."]},{"heading":"اختلاف بين الأجيال والمناطق","paragraphs":["تختلف هذه الاستعمالات بين الأمهرية والتغرينية والأورومو وبين الأجيال، فبعض مغتربي الأمهرية يبسّطون كل شيء إلى ضمير واحد، والجنس أيضًا يحدّد أي صيغة تُعدّ مهذّبة."]}],"de":[{"heading":"Ein Pronomen zieht das Verb mit","paragraphs":["Das Amharische unterscheidet ante (du, männliche Einzahl) von erswo (höfliches du), das eine Pluralform des Verbs verlangt.","Die höfliche Form geht nach oben in Alter und Rang und wird von Dienstleistenden gegenüber Kundschaft benutzt, während Eltern von ihren Kindern weiterhin ante hören können.","Die Kongruenz folgt dem Pronomen: erswo endet naweot? (wie geht es Ihnen) nimmt eine Pluralform, die ein einzelnes Subjekt nicht trägt."]},{"heading":"Zwischen Wärme und Unhöflichkeit","paragraphs":["Ein zu frühes ante kann je nach Situation warm oder unhöflich klingen, und Stadtbewohner regeln das oft lieber über Titel."]},{"heading":"Je nach Region und Generation","paragraphs":["Der Gebrauch unterscheidet sich zwischen Amharisch, Tigrinya und Oromo sowie zwischen Generationen; Diaspora-Sprecher vereinfachen häufig auf ein einziges du, und auch das Geschlecht beeinflusst, welche Form als höflich gilt."]}],"en":[{"heading":"A pronoun that drags the verb along","paragraphs":["Amharic separates ante (you, masculine singular) from erswo, the polite you, which takes plural verb agreement.","The polite form is used upward in age and rank and by service staff to customers, while parents may still receive ante from their own children.","Agreement follows the pronoun: erswo endet naweot? (how are you) uses a plural verb form that a singular subject would not take."]},{"heading":"Warm or rude, depending on timing","paragraphs":["Using ante too early can sound either warm or rude depending on the setting, and urban speakers often manage it with titles instead."]},{"heading":"Region and generation shift the line","paragraphs":["Usage differs between Amharic, Tigrinya and Oromo and between generations; diaspora Amharic speakers often simplify to one you, and gender also affects which form counts as polite."]}]},"context":{"countries":["ET"],"region":"Central and northern highlands (Addis Ababa, Gondar, Mekelle)","continent":"africa","languages":["am","ti","om"],"period":"contemporary"},"tags":["communication","Central and northern highlands (Addis Ababa, Gondar, Mekelle)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Amharic","de":"Amharic","en":"Amharic"},"url":"https://en.wikipedia.org/wiki/Amharic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تنتقل موظفة شابة في أديس أبابا إلى erswo مع زبون يكبرها بالضعف، وتعود إلى ante مع زميل في عمرها في الدقيقة نفسها، ولا يلاحظ أي منهما هذا التحوّل النحوي.","de":"Eine junge Angestellte in Addis wechselt zu erswo bei einer Kundin, die doppelt so alt ist wie sie, und im selben Moment zurück zu ante bei einem gleichaltrigen Kollegen – keiner der beiden bemerkt den grammatischen Wechsel.","en":"A young Addis Ababa clerk switches to erswo with a customer twice her age and back to ante with a colleague her own age in the same minute, and neither party notices the grammar shift."},"misunderstanding":{"ar":"يعتقد بعض المتعلّمين أن erswo مجرد صيغة جمع عادية، فيخطئون في تقدير ما تحمله من احترام.","de":"Manche Lernenden halten erswo für einen gewöhnlichen Plural und unterschätzen den Respekt, der darin liegt.","en":"Learners sometimes treat erswo as an ordinary plural and miss the respect it carries."},"comparison":{"ar":"حيث يبدّل الأمهريون الضمير والفعل معًا، قد يكتفي متحدثون آخرون بلقب أو نبرة لتأدية الغرض نفسه.","de":"Wo Amharisch Pronomen und Verb zugleich wechselt, begnügen sich andere Sprachen oft mit einem Titel oder einem Tonfall.","en":"Where Amharic changes pronoun and verb together, other languages often rely on a title or a tone of voice."},"expression":{"original":"እርስዎ እንዴት ነዎት?","language":"አማርኛ (Amharic)","gloss":{"ar":"كيف حالك؟ (مهذّبة)","de":"Wie geht es Ihnen? (höflich)","en":"How are you? (polite)"},"usage":{"ar":"تُقال لمن يكبرك سنًّا أو رتبة، أو لزبون، وتأخذ فعل جمع.","de":"An ältere oder ranghöhere Personen und an Kundschaft gerichtet, mit Pluralverb.","en":"Addressed upward in age or rank and to customers, with plural verb agreement."},"transliteration":"erswo endet naweot?"}},{"id":"lng-008","version":2,"slug":"the-kgotla-where-a-motswana-speaks-only-after-the-circle-is-opened","contentType":"note","category":"communication","title":{"ar":"الكغوتلا: حيث لا يتحدث المواطن إلا بعد فتح الدائرة","de":"Die Kgotla: Wo ein Motswana erst nach Öffnung des Kreises spricht","en":"The kgotla: where a Motswana speaks only after the circle is opened"},"deck":{"ar":"في بوتسوانا، تُدار الكلمة بترتيب دقيق: صلاة، ثم دعوة المتحدثين، ثم استماع للكبار قبل الصغار، وتُختم المداخلات بـ«بولا».","de":"In Botswana wird das Wort genau geordnet: Gebet, dann die Einladung der Redner, Ältere vor Jüngeren, und jeder Beitrag endet mit „Pula“.","en":"In Botswana the floor is carefully ordered: prayer, then invited speakers, elders before juniors, and every speech closes with Pula."},"teaser":{"ar":"الكغوتلا ساحة مفتوحة ومحكمة عرفية في آن واحد، حيث تُفتح الدائرة قبل أن يُسمح بالكلام، ويُختَم الكلام بـ«بولا» إشارة إلى الإغلاق الرسمي.","de":"Die Kgotla ist offener Versammlungsort und Gewohnheitsgericht zugleich. Der Kreis wird geöffnet, bevor gesprochen wird, und mit „Pula“ förmlich geschlossen.","en":"A kgotla is both open meeting place and customary court. The circle is opened before anyone speaks, and Pula formally closes the point."},"readingMinutes":1,"sections":{"ar":[{"heading":"دائرة تُفتح بالصلاة وتُغلق بالمطر","paragraphs":["الكغوتلا هو مكان الاجتماع المفتوح والمحكمة العرفية في قرية بوتسوانية، يُعقد في نصف دائرة يتوسطها الرئيس أو زعيم القرية. يبدأ اللقاء بالصلاة، ثم يدعو الرئيس المتحدثين بالترتيب، ويُستمع إلى الكبار قبل الصغار.","تنتهي المداخلات بكلمة «بولا» (المطر)، وهي بركة وشعار وطني وإشارة إلى أن النقطة أُغلقت رسميًا. وتُعلن القرارات من الدائرة نفسها، ولا يزال أعضاء المجالس المنتخبون يستخدمون اجتماعات الكغوتلا للعودة إلى الناخبين."]},{"heading":"مقاطعة المتحدث خطأ إجرائي جسيم","paragraphs":["مقاطعة المتحدث أو مخاطبة الرئيس كندٍّ له بدلًا من المرور عبر الاجتماع يُعدّ خرقًا خطيرًا للإجراء. يختلف البروتوكول حسب الجماعة العرقية وبين الأحياء الريفية والحضرية؛ ففي غابورون تُحال نزاعات كثيرة إلى المحاكم الرسمية، وتغيّر دور المرأة في الكلام تغيّرًا غير متساوٍ."]}],"de":[{"heading":"Ein Kreis, der mit Gebet öffnet und mit Regen schließt","paragraphs":["Die Kgotla ist der offene Versammlungsplatz und das Gewohnheitsgericht eines botswanischen Dorfes, im Halbkreis gehalten, mit dem Häuptling oder Vorsteher im Zentrum. Die Versammlung beginnt mit einem Gebet, der Vorsitzende lädt Redner der Reihe nach ein, und Ältere werden vor Jüngeren gehört.","Reden enden mit „Pula“ (Regen), einem Segen, dem nationalen Wahlspruch und dem Signal, dass der Punkt formell geschlossen ist. Entscheidungen werden aus demselben Kreis verkündet, und gewählte Bezirksräte nutzen Kgotla-Versammlungen weiterhin, um ihren Wählern Bericht zu erstatten."]},{"heading":"Einen Redner zu unterbrechen ist ein schwerer Verfahrensfehler","paragraphs":["Einen Redner zu unterbrechen oder den Vorsitzenden als Gleichrangigen statt über die Versammlung anzusprechen, gilt als schwerer Verstoß gegen das Verfahren. Das Protokoll variiert je nach Ethnie und zwischen ländlichen und städtischen Vierteln; in Gaborone gehen viele Streitigkeiten an formale Gerichte, und die Sprechrollen von Frauen haben sich ungleich verändert."]}],"en":[{"heading":"A circle opened by prayer, closed by rain","paragraphs":["A kgotla is the open meeting place and customary court of a Botswana village, held in a semicircle with the chief or headman at the centre. The meeting opens with prayer, the chair invites speakers in order, and elders are heard before juniors.","Speeches end with Pula (rain), a blessing that is also the national motto and the signal that the point is formally closed. Decisions are announced from the same circle, and elected ward councillors still use kgotla meetings to report back to voters."]},{"heading":"Interrupting a speaker is a serious breach of procedure","paragraphs":["Interrupting a speaker or addressing the chair as an equal rather than through the meeting is a serious breach of procedure. Kgotla protocol varies by ethnic group and between rural and urban wards; in Gaborone many disputes go to formal courts, and women's speaking roles have changed unevenly."]}]},"context":{"countries":["BW"],"region":"Nationwide, especially Kgatleng, Kweneng and Serowe","continent":"africa","languages":["tn","en"],"period":"contemporary"},"tags":["communication","Nationwide, especially Kgatleng, Kweneng and Serowe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tswana language","de":"Tswana language","en":"Tswana language"},"url":"https://en.wikipedia.org/wiki/Tswana_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kgotla","de":"Kgotla","en":"Kgotla"},"url":"https://en.wikipedia.org/wiki/Kgotla","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في كغوتلا بمنطقة كوينينغ ينتظر شاب عبر متحدثين أكبر منه قبل أن يشير إليه الرئيس؛ فيقف ويحيي الدائرة بـ«دوميلانغ» وينهي بـ«بولا».","de":"In einer Kgotla in Kweneng wartet ein junger Mann zwei ältere Redner ab, bis der Vorsitzende ihm zunickt; er steht auf, grüßt den Kreis mit Dumelang und schließt mit Pula.","en":"In a Kweneng kgotla a young man waits through two older speakers before the chair nods at him; he stands, greets the circle with Dumelang, and finishes with Pula."},"misunderstanding":{"ar":"الاعتقاد بأن الكغوتلا مجرد لقاء عابر أو أن الكلمة متاحة لمن يرفع صوته أولًا؛ بل هي إجراء منظم يحدد من يتكلم ومتى.","de":"Die Annahme, die Kgotla sei nur ein zwangloses Treffen oder das Wort stehe dem zu, der zuerst die Stimme erhebt; tatsächlich regelt ein Verfahren, wer wann spricht.","en":"Thinking the kgotla is a casual gathering where whoever raises a voice first may speak; in fact a procedure governs who speaks and when."},"comparison":{"ar":"في كثير من الاجتماعات الحديثة يُفتح النقاش مباشرة؛ أما في الكغوتلا فالكلام يُفتح ويُغلق بطقوس واضحة: صلاة في البداية و«بولا» في النهاية.","de":"In vielen modernen Sitzungen beginnt die Debatte sofort; in der Kgotla wird das Sprechen mit klaren Ritualen geöffnet und geschlossen – Gebet am Anfang, Pula am Ende.","en":"Many modern meetings open debate immediately; in the kgotla speech is opened and closed by clear rituals—prayer at the start, Pula at the end."},"expression":{"original":"Dumelang","language":"Setswana (Tswana)","gloss":{"ar":"مرحبًا (لمجموعة)","de":"Hallo (an eine Gruppe)","en":"hello (to a group)"},"usage":{"ar":"تحية تُقال عند دخول الدائرة أو مخاطبة الحاضرين قبل البدء بالمداخلة.","de":"Gruß beim Betreten des Kreises oder zur Begrüßung der Anwesenden vor dem eigenen Beitrag.","en":"A greeting used on entering the circle or addressing those present before making a contribution."},"transliteration":"dumelang"}},{"id":"lng-009","version":2,"slug":"wetin-dey-happen-how-nigerian-pidgin-compresses-a-whole-conversation","contentType":"language","category":"languages","title":{"ar":"البيدجن النيجيري: محادثة كاملة في كلمتين","de":"Nigerianisches Pidgin: ein Gespräch in zwei Wörtern","en":"Nigerian Pidgin packs a chat into two words"},"deck":{"ar":"لغة كريولية يتحدثها أكثر من مئة مليون شخص، تختصر السؤال والزمن والحال في بضع كلمات، وتبقى بلا معيار كتابي موحّد.","de":"Eine Kreolsprache von über hundert Millionen Sprechenden, die Zeit, Verlauf und Frage in wenige Partikeln packt – ohne offiziellen Status und ohne einheitliche Rechtschreibung.","en":"A creole spoken by well over a hundred million people, it builds tense, progress and questions from a handful of particles — with no official status and no fixed spelling."},"teaser":{"ar":"كيف يحوّل النيجيريون البيدجن إلى أداة تواصل وطنية رغم غياب المكانة الرسمية؟","de":"Wie wird Pidgin trotz fehlender Amtssprache zur gemeinsamen Sprache auf nigerianischen Märkten und in den Medien?","en":"How does Pidgin work as a national lingua franca on markets and radio despite never being taught as a school subject?"},"readingMinutes":1,"sections":{"ar":[{"heading":"جُسور في السوق","paragraphs":["في سوق أونيتشا الرئيسي يلتقي تاجران من مجموعتين لغويتين مختلفتين، فيتفقان على السعر بالبيدجن وحده، ولا يلجآن إلى الإيبو إلا حين ينضم تاجر ثالث؛ كلاهما يعتبر البيدجن أرضاً محايدة.","هذه الحياد اللغوي هو ما جعل البيدجن لغة مشتركة بين مئات الملايين، رغم أنه ليس لغة رسمية ونادراً ما يُدرَّس في المدارس.","يختلف المشهد بين المدن والأرياف، وبين جيل الشباب المتمرّس في وسائل التواصل وجيل كبار السنّ الأكثر تمسكاً بلغاتهم المحلية."]},{"heading":"قواعد مختصرة وأذنٌ منصتة","paragraphs":["يبني البيدجن أزمنته بجزيئات صغيرة: dey للفعل المستمر، وdon للإتمام، وgo للمستقبل، كما في I dey go وI don go.","السؤال غالباً بالنبرة وحدها، فجملة You dey come؟ لا تحتاج إلى فعل مساعد لتسأل إن كان أحدهم قادماً.","انتشر البيدجن عبر الراديو ونوليوود ووسائل التواصل، حتى صار السياسيون يستخدمونه ليبدوا عفويين غير مقيدين بنصّ مكتوب.","لكن الإملاء غير موحّد، فقد تُكتب الجملة نفسها wetin dey happen أو wetyn de happen أو wetin de hapun، ويختلف ذلك بين لاغوس وبورت هاركورت وواري."]}],"de":[{"heading":"Brücken auf dem Markt","paragraphs":["Auf dem Hauptmarkt von Onitsha treffen zwei Händler aus verschiedenen Sprachgruppen zusammen und handeln den Preis vollständig auf Pidgin aus; erst als ein dritter Händler dazukommt, wechseln sie ins Igbo. Beide verstehen Pidgin als neutralen Boden.","Diese Neutralität macht die Sprache für weit über hundert Millionen Menschen nutzbar, obwohl sie nicht offiziell ist und in der Schule kaum behandelt wird.","Zwischen Stadt und Land zeigt sich ein Unterschied, und jüngere Sprecher, die in sozialen Medien aufwachsen, verwenden andere Wendungen als ältere, die stärker an ihren Herkunftssprachen festhalten."]},{"heading":"Kurze Grammatik, feines Gehör","paragraphs":["Die Zeit wird mit Partikeln gebildet: dey für laufende Handlungen, don für Abgeschlossenes und go für die Zukunft, wie in I dey go und I don go.","Fragen entstehen oft allein durch die Intonation, sodass You dey come? kein Hilfsverb braucht, um zu fragen, ob jemand kommt.","Radio, Nollywood und soziale Medien machten Pidgin zur nationalen Verkehrssprache, und Politiker nutzen es, um ungeskriptet zu wirken.","Die Rechtschreibung ist jedoch uneinheitlich: Derselbe Satz erscheint als wetin dey happen, wetyn de happen oder wetin de hapun, und die Varianten von Lagos, Port Harcourt und Warri mischen unterschiedlich viel Englisch bei."]}],"en":[{"heading":"Neutral ground at the market","paragraphs":["At Onitsha main market, two traders from different language groups settle a price entirely in Pidgin, switching to Igbo only when a third trader joins; both treat Pidgin as neutral ground.","That neutrality is why the creole serves well over a hundred million people even though it is not an official language and is rarely examined in school.","Usage shifts between city and countryside, and younger speakers raised on social media phrase things differently from older people who stay closer to their home languages."]},{"heading":"Small particles, sharp ears","paragraphs":["Tense runs on particles: dey marks ongoing action, don marks completion and go marks the future, as in I dey go and I don go.","Questions often come from intonation alone, so You dey come? needs no auxiliary to ask whether someone is coming.","Radio, Nollywood and social media made Pidgin a national lingua franca, and politicians now use it to sound unscripted.","The orthography is unstandardised, so one sentence may appear as wetin dey happen, wetyn de happen or wetin de hapun, and Lagos, Port Harcourt and Warri varieties differ in vocabulary and in how much English they mix."]}]},"context":{"countries":["NG"],"region":"Nationwide, heaviest in the south and in cities","continent":"africa","languages":["pcm","en","yo","ig","ha"],"period":"contemporary"},"tags":["languages","Nationwide, heaviest in the south and in cities"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nigerian Pidgin","de":"Nigerian Pidgin","en":"Nigerian Pidgin"},"url":"https://en.wikipedia.org/wiki/Nigerian_Pidgin","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pidgin","de":"Pidgin","en":"Pidgin"},"url":"https://en.wikipedia.org/wiki/Pidgin","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تاجران من خلفيتين لغويتين يتبادلان البيع والشراء في السوق بالبيدجن وحده، ثم يتحولان إلى الإيبو عند وصول طرف ثالث؛ اللغة هنا أداة حياد لا هوية.","de":"Zwei Händler verschiedener Sprachgruppen einigen sich auf dem Markt ausschließlich auf Pidgin und wechseln erst zum Igbo, als ein Dritter dazukommt – die Sprache ist Werkzeug, nicht Bekenntnis.","en":"Two traders from different language groups settle a price entirely in Pidgin, switching to Igbo only when a third trader joins; both treat Pidgin as neutral ground."},"misunderstanding":{"ar":"يظن بعض الأجانب أن البيدجن إنجليزية مكسورة أو كلام غير متقن، والحقيقة أنه نظام كريولي كامل بقواعده الخاصة.","de":"Viele Auswärtige halten Pidgin für gebrochenes Englisch; tatsächlich ist es ein vollständiges Kreol mit eigenen Regeln.","en":"Outsiders often call Pidgin broken English; it is a full creole with its own grammar, not a failed version of another language."},"comparison":{"ar":"حيث تطلب الإنجليزية فعلين مساعدين للسؤال والزمن، يكفي في البيدجن جزيء واحد ونبرة واحدة.","de":"Wo das Englische mehrere Hilfsverben für Zeit und Frage braucht, genügen im Pidgin eine Partikel und eine Tonhöhe.","en":"Where English needs auxiliary verbs for tense and questions, Pidgin often needs one particle and a rise in tone."},"expression":{"original":"Wetin dey happen?","language":"Naija (Nigerian Pidgin)","gloss":{"ar":"ماذا يحدث؟ / ما الأخبار؟","de":"Was passiert? / Was gibt's?","en":"What is happening? / What's up?"},"usage":{"ar":"تحية أو سؤال مفتوح بين الأصدقاء والزملاء في الشارع والسوق","de":"Begrüßung oder offene Frage unter Freunden und Kollegen auf der Straße und im Handel","en":"A greeting or open question among friends and colleagues in the street and at the market"},"transliteration":"wetin dey happen"}},{"id":"lng-010","version":2,"slug":"sawubona-the-zulu-greeting-that-says-i-see-you","contentType":"note","category":"communication","title":{"ar":"ساووبونا: تحية الزولو التي تعني أرى بك","de":"Sawubona: Der Zulu-Gruß, der sagt: Ich sehe dich","en":"Sawubona: The Zulu Greeting That Says I See You"},"deck":{"ar":"في كوازولو ناتال وخاوتينغ، تحية الزولو تتجاوز الكلمات لتعترف بحضور الشخص وهويته.","de":"In KwaZulu-Natal und Gauteng geht der Zulu-Gruß über Worte hinaus und erkennt die Anwesenheit und Identität einer Person an.","en":"In KwaZulu-Natal and Gauteng, the Zulu greeting goes beyond words to acknowledge a person's presence and identity."},"teaser":{"ar":"ساووبونا ليست مجرد مرحباً، بل اعتراف بالآخر. تعرف على كيفية استخدامها وتأثيرها في جنوب أفريقيا.","de":"Sawubona ist mehr als ein Hallo – es ist eine Anerkennung des anderen. Erfahren Sie, wie er in Südafrika verwendet wird.","en":"Sawubona is more than a hello—it's an acknowledgment of the other. Learn how it's used in South Africa."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى التحية واستخدامها","paragraphs":["ساووبونا تُترجم عادة إلى 'أراك' أو 'نراك' وتُوجه لشخص واحد، بينما تُستخدم سانيبوناني لمجموعة. الرد ييبو، ساووبونا (نعم، أراك) يكمل التبادل الذي يعترف بالحضور بدلاً من تبادل المعلومات.","غالباً ما تستمر التحية باسم الثناء العشائري (إيسيثاكازيلو) وسؤال مثل 'أوهلالا كوفي؟' (أين تقيم).","تختلف طول التحية حسب العمر والسياق والمنطقة؛ في خاوتينغ، تختلط لغة الزولو بالإنجليزية ولغات سوثو، وليس كل متحدث بالزولو يعرف أسماء العشائر المتوقعة منه."]},{"heading":"طريقة التوصيل وأهميتها","paragraphs":["طريقة التوصيل مهمة: ساووبونا مقتضبة لكبير في السن تبدو ازدراءً، لذا يضيف المتحدثون اسم العشيرة أو لقباً.","دخلت الكلمة الإنجليزية الجنوب أفريقية عبر الإعلام وغالباً ما ترتبط بفكرة أوبونتو أن الشخص شخص من خلال الآخرين.","تختلف ممارسة التحية بين الأجيال، حيث قد يستخدم الشباب في المناطق الحضرية تحيات مختصرة لكنهم يظلون يدركون أهمية الاعتراف بالآخر."]}],"de":[{"heading":"Bedeutung und Verwendung des Grußes","paragraphs":["Sawubona wird normalerweise mit 'Ich sehe dich' oder 'Wir sehen dich' übersetzt und an eine Person gerichtet; Sanibonani wird für eine Gruppe verwendet. Die Antwort Yebo, sawubona (Ja, ich sehe dich) vervollständigt den Austausch, der Anwesenheit anerkennt, anstatt Informationen auszutauschen.","Der Gruß wird oft mit einem Clan-Lobnamen (isithakazelo) und einer Frage wie Uhlala kuphi? (Wo wohnst du?) fortgesetzt.","Die Länge des Grußes variiert je nach Alter, Umgebung und Region; in Gauteng vermischt sich isiZulu mit Englisch und Sotho-Sprachen, und nicht jeder Zulu-Sprecher kennt die von ihm erwarteten Clan-Namen."]},{"heading":"Die Art der Übermittlung und ihre Bedeutung","paragraphs":["Die Art der Übermittlung ist wichtig: Ein knappes Sawubona zu einem Älteren klingt abweisend, daher fügen Sprecher den Clan-Namen oder einen Titel hinzu.","Das Wort gelangte über Medien in das südafrikanische Englisch und wird oft mit der Ubuntu-Idee verbunden, dass ein Mensch ein Mensch durch andere Menschen ist.","Die Grußpraxis variiert zwischen den Generationen; junge Stadtbewohner verwenden manchmal verkürzte Grüße, bleiben sich aber der Bedeutung der Anerkennung des anderen bewusst."]}],"en":[{"heading":"Meaning and Use of the Greeting","paragraphs":["Sawubona is usually translated as 'I see you' or 'we see you' and is addressed to one person; Sanibonani addresses a group. The reply Yebo, sawubona (yes, I see you) completes the exchange, which acknowledges presence rather than exchanging information.","The greeting often continues with a clan praise name (isithakazelo) and a question such as Uhlala kuphi? (where do you stay).","Greeting length varies by age, setting and region; isiZulu in Gauteng mixes with English and Sotho languages, and not every Zulu speaker knows the clan names expected of them."]},{"heading":"Delivery and Significance","paragraphs":["Delivery matters: a clipped sawubona to an elder sounds dismissive, so speakers add the clan name or a title.","The word entered South African English through media and is often linked to the ubuntu idea that a person is a person through other people.","Greeting practices vary between generations; young urbanites may use shortened greetings but remain aware of the importance of acknowledging the other."]}]},"context":{"countries":["ZA"],"region":"KwaZulu-Natal and Gauteng","continent":"africa","languages":["zu","en","af"],"period":"contemporary"},"tags":["communication","KwaZulu-Natal and Gauteng"],"sources":[{"organization":"Wikipedia","title":{"ar":"Zulu language","de":"Zulu language","en":"Zulu language"},"url":"https://en.wikipedia.org/wiki/Zulu_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ubuntu philosophy","de":"Ubuntu philosophy","en":"Ubuntu philosophy"},"url":"https://en.wikipedia.org/wiki/Ubuntu_philosophy","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ديربان، تستقبل ممرضة مريضاً بـ 'ساووبونا' ثم باسم عشيرته المقروء من الملف؛ يرتاح المريض بشكل ملحوظ، لأن تسميته بالعشيرة شكل من أشكال الاعتراف وليس حديثاً جانبياً.","de":"Eine Krankenschwester in Durban begrüßt einen Patienten mit Sawubona und dann mit einem Clan-Namen, den sie aus der Akte liest; der Patient entspannt sich sichtbar, denn mit dem Clan-Namen angesprochen zu werden, ist eine Form der Anerkennung und kein Small Talk.","en":"A Durban nurse greets a patient with sawubona and then a clan name read from the file; the patient relaxes visibly, because being named by clan is a form of recognition rather than small talk."},"misunderstanding":{"ar":"قد يعتقد غير المتحدثين أن 'ساووبونا' مجرد مرحباً عابرة، لكنها في الواقع اعتراف عميق بالوجود يتطلب رداً مناسباً.","de":"Nicht-Muttersprachler könnten denken, Sawubona sei nur ein flüchtiges Hallo, aber es ist eine tiefe Anerkennung der Existenz, die eine angemessene Antwort erfordert.","en":"Non-speakers might think sawubona is just a quick hello, but it's a deep acknowledgment of existence that requires an appropriate response."},"comparison":{"ar":"بالمقارنة مع التحيات الغربية السريعة، تتطلب ساووبونا وقتاً أطول وتفاعلاً شخصياً يعكس قيم المجتمع.","de":"Im Vergleich zu schnellen westlichen Grüßen erfordert Sawubona mehr Zeit und persönliche Interaktion, was die Werte der Gesellschaft widerspiegelt.","en":"Compared to quick Western greetings, sawubona takes more time and personal interaction, reflecting the community's values."},"expression":{"original":"Sawubona","language":"isiZulu (Zulu)","gloss":{"ar":"أراك/نراك (لشخص واحد)","de":"Ich/wir sehe(n) dich (zu einer Person)","en":"I/we see you (to one person)"},"usage":{"ar":"تحية شائعة في جنوب أفريقيا، خاصة بين متحدثي الزولو، تُستخدم للاعتراف بحضور الشخص.","de":"Ein in Südafrika üblicher Gruß, besonders unter Zulu-Sprechern, der die Anwesenheit einer Person anerkennt.","en":"A common greeting in South Africa, especially among Zulu speakers, used to acknowledge a person's presence."},"transliteration":"sawubona"}},{"id":"lng-011","version":2,"slug":"three-clicks-in-one-word-xhosa-s-borrowed-consonants","contentType":"detail","category":"languages","title":{"ar":"ثلاث نقرات في كلمة واحدة: الحروف الساكنة المستعارة في لغة الخوسا","de":"Drei Klicks in einem Wort: Xhosas geliehene Konsonanten","en":"Three clicks in one word: Xhosa's borrowed consonants"},"deck":{"ar":"كيف أصبحت النقرات جزءًا أصيلًا من لغة isiXhosa اليومية، وكيف يتعلمها الأطفال ويستخدمها المتحدثون.","de":"Wie Klicks zu einem selbstverständlichen Teil der Alltagssprache isiXhosa wurden und wie Kinder sie lernen.","en":"How clicks became an ordinary part of everyday isiXhosa, and how children learn them."},"teaser":{"ar":"لغة الخوسا تحتوي على ثلاث نقرات أساسية، دخلت من لغات الخويسان وأصبحت حروفًا عادية في كلمات مثل cela (أن يسأل).","de":"isiXhosa hat drei grundlegende Klicktypen, die aus Khoisan-Sprachen kamen und heute in Wörtern wie cela (fragen) ganz normal sind.","en":"isiXhosa has three basic click types, which entered from Khoisan languages and are now ordinary in words like cela (to ask)."},"readingMinutes":1,"sections":{"ar":[{"heading":"النقرات كأصوات عادية","paragraphs":["تحتوي لغة isiXhosa على ثلاثة أنواع أساسية من النقرات تُكتب c و x و q، بالإضافة إلى مجموعات مثل gc و nc و ngc. دخلت هذه النقرات من لغات الخويسان وأصبحت الآن حروفًا ساكنة عادية في كلمات الحياة اليومية مثل cela (أن يسأل).","اسم اللغة نفسه يبدأ بنقرة: isiXhosa تستخدم النقرة الجانبية x التي نادرًا ما يحاول متحدثو الإنجليزية نطقها. يكتسب الأطفال النقرات في نفس العمر الذي يكتسبون فيه الحروف الساكنة الأخرى، لذا فهي ليست صعبة بشكل خاص للناطقين الأصليين."]},{"heading":"الكتابة والنطق في الممارسة","paragraphs":["تطلب كتابة النقرات استخدام الحروف اللاتينية بالإضافة إلى digraphs، ولا يزال مذيعو الراديو يتهجّون الأسماء غير المألوفة بنوع النقرة. في عيادة في كيب تاون، تتهجى موظفة الاستقبال لقبًا ما بأسماء النقرات، النقرة السنية c والجانبية x، لأن الحروف وحدها لا تخبر المتحدث بغير الخوسا أين يضع لسانه.","تختلف مخزونات النقرات وطريقة كتابتها بين الخوسا والزولو والسوتو الجنوبية؛ قد يستخدم المتحدثون في المدن أسماء أماكن إنجليزية بدلًا من ذلك، ويستخدم الكلام العادي نقرات أقل مما توحي به القواميس. يختلف استخدام النقرات أيضًا بين الأجيال والمناطق، حيث قد يفضل الشباب في المناطق الحضرية أشكالًا مبسطة."]}],"de":[{"heading":"Klicks als gewöhnliche Laute","paragraphs":["isiXhosa hat drei grundlegende Klicktypen, geschrieben c, x und q, sowie Cluster wie gc, nc und ngc. Die Klicks kamen aus Khoisan-Sprachen und sind heute ganz normale Konsonanten in Alltagswörtern wie cela (fragen).","Der Name der Sprache beginnt selbst mit einem Klick: isiXhosa verwendet den lateralen x-Klick, den Englischsprecher selten versuchen. Kinder erwerben Klicks im selben Alter wie andere Konsonanten, daher sind sie für Erstsprachler nicht besonders schwer."]},{"heading":"Schreiben und Sprechen in der Praxis","paragraphs":["Für die Verschriftlichung brauchte man lateinische Buchstaben plus Digraphen, und Radiomoderatoren buchstabieren unbekannte Namen noch immer nach Klicktyp. In einer Klinik in Kapstadt buchstabiert eine Empfangsmitarbeiterin einen Nachnamen mit Klicknamen, dem dentalen c und dem lateralen x, weil die Buchstaben allein einem Nicht-Xhosa-Sprecher nicht sagen, wo die Zunge hin soll.","Die Klick-Inventare und Schreibweisen unterscheiden sich zwischen Xhosa, Zulu und Süd-Sotho; städtische Sprecher verwenden manchmal englische Ortsnamen, und die Umgangssprache nutzt weniger Klicks als Wörterbücher vermuten lassen. Auch zwischen Generationen und Regionen variiert der Gebrauch, wobei junge Stadtbewohner oft vereinfachte Formen bevorzugen."]}],"en":[{"heading":"Clicks as ordinary sounds","paragraphs":["isiXhosa has three basic click types written c, x and q, plus clusters such as gc, nc and ngc. The clicks entered Xhosa from Khoisan languages and are now ordinary consonants in everyday words such as cela (to ask).","The name of the language begins with one: isiXhosa uses the lateral x click that English speakers rarely attempt. Children acquire clicks at the same age as other consonants, so they are not especially hard for first-language speakers."]},{"heading":"Writing and speaking in practice","paragraphs":["Writing them required Latin letters plus digraphs, and radio presenters still spell unfamiliar names by click type. At a Cape Town clinic a receptionist spells a surname by click names, the dental c and the lateral x, because the letters alone do not tell a non-Xhosa speaker where to put the tongue.","Click inventories and spellings differ among Xhosa, Zulu and Southern Sotho; urban speakers may use English place names instead, and casual speech uses fewer clicks than dictionaries suggest. Usage also varies by region and generation, with younger city speakers often favoring simplified forms."]}]},"context":{"countries":["ZA"],"region":"Eastern Cape and Western Cape","continent":"africa","languages":["xh","en","af"],"period":"contemporary"},"tags":["languages","Eastern Cape and Western Cape"],"sources":[{"organization":"Wikipedia","title":{"ar":"Xhosa language","de":"Xhosa language","en":"Xhosa language"},"url":"https://en.wikipedia.org/wiki/Xhosa_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Click consonant","de":"Click consonant","en":"Click consonant"},"url":"https://en.wikipedia.org/wiki/Click_consonant","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عيادة في كيب تاون، تتهجى موظفة الاستقبال لقبًا ما بأسماء النقرات، النقرة السنية c والجانبية x، لأن الحروف وحدها لا تخبر المتحدث بغير الخوسا أين يضع لسانه.","de":"In einer Klinik in Kapstadt buchstabiert eine Empfangsmitarbeiterin einen Nachnamen mit Klicknamen, dem dentalen c und dem lateralen x, weil die Buchstaben allein einem Nicht-Xhosa-Sprecher nicht sagen, wo die Zunge hin soll.","en":"At a Cape Town clinic a receptionist spells a surname by click names, the dental c and the lateral x, because the letters alone do not tell a non-Xhosa speaker where to put the tongue."},"misunderstanding":{"ar":"يعتقد بعض المتحدثين بغير الخوسا أن النقرات صعبة للغاية، لكنها بالنسبة للناطقين الأصليين حروف ساكنة عادية يكتسبونها في نفس عمر غيرها.","de":"Manche Nicht-Xhosa-Sprecher halten Klicks für sehr schwierig, aber für Muttersprachler sind sie gewöhnliche Konsonanten, die sie im selben Alter wie andere erlernen.","en":"Some non-Xhosa speakers assume clicks are extremely difficult, but for first-language speakers they are ordinary consonants acquired at the same age as any other."},"comparison":{"ar":"بينما تحتوي الخوسا على ثلاث نقرات أساسية، تختلف مخزونات النقرات بين الخوسا والزولو والسوتو الجنوبية، وقد يستخدم المتحدثون في المدن أسماء أماكن إنجليزية بدلًا من النقرات.","de":"Während Xhosa drei grundlegende Klicks hat, unterscheiden sich die Klick-Inventare zwischen Xhosa, Zulu und Süd-Sotho, und städtische Sprecher verwenden manchmal englische Ortsnamen anstelle von Klicks.","en":"While Xhosa has three basic clicks, click inventories differ among Xhosa, Zulu and Southern Sotho, and urban speakers may use English place names instead of clicks."},"expression":{"original":"isiXhosa","language":"isiXhosa (Xhosa)","gloss":{"ar":"لغة الخوسا","de":"die Xhosa-Sprache","en":"the Xhosa language"},"usage":{"ar":"اسم اللغة نفسها، ويبدأ بنقرة جانبية x.","de":"Der Name der Sprache selbst, der mit einem lateralen x-Klick beginnt.","en":"The name of the language itself, beginning with a lateral x click."},"transliteration":"isiXhosa"}},{"id":"lng-012","version":2,"slug":"sheng-the-nairobi-street-code-that-changes-faster-than-the-dictionary","contentType":"language","category":"languages","title":{"ar":"شينغ: لغة الشارع في نيروبي","de":"Sheng: Nairobis Straßencode","en":"Sheng: Nairobi's fast-changing street code"},"deck":{"ar":"مفردات تتبدّل أسرع من القاموس، وكل حي في نيروبي يضيف بصمته الخاصة إلى هذه اللغة المختلطة.","de":"Ein Wortschatz, der sich schneller dreht als jedes Wörterbuch, und jeder Stadtteil von Nairobi fügt seine eigene Note hinzu.","en":"A vocabulary that turns over faster than any dictionary, with every Nairobi estate adding its own twist."},"teaser":{"ar":"بدأت في أحياء شرق نيروبي في السبعينيات، واليوم تنتشر عبر الحافلات والإذاعة والموسيقى، لكن كلماتها تتبدّل بسرعة مدهشة.","de":"In den 1970er Jahren in Nairobis Eastlands entstanden, verbreitet sich Sheng heute über Matatus, Radio und Musik – doch seine Wörter wechseln erstaunlich schnell.","en":"Born in Nairobi's Eastlands in the 1970s, Sheng now travels through matatus, radio and music, yet its words for money, police and friend keep changing."},"readingMinutes":1,"sections":{"ar":[{"heading":"من أزقة إيستلاندز إلى كل كينيا","paragraphs":["بدأت الشينغ في أحياء شرق نيروبي في السبعينيات، بأساس من السواحيلية تعزّزه كلمات إنجليزية وكيكويو ولوو. ومع الوقت حملها سائقو الحافلات والمذيعون والموسيقيون إلى مدن كينيا الأخرى، حتى ظهرت في إعلانات تستهدف من هم دون الثلاثين.","تتبدّل مفرداتها بسرعة لافتة: كلمات المال والشرطة والصديق تُستبدل بمجرد أن يتعلّمها الغرباء. وهنا يظهر اختلاف إقليمي واضح، إذ لكل حي مفرداته الخاصة، وقد لا يعرف الكينيون في الريف سوى حفنة من كلماتها."]},{"heading":"لغة كاملة أم خطر على السواحيلية؟","paragraphs":["يعاملها كثير من المعلمين والآباء كتهديد للسواحيلية السليمة، بينما يصفها اللغويون بأنها سجل لغوي قائم بذاته لا لغة مكسورة. ولا توجد لها كتابة ثابتة، فقد تُكتب الكلمة الواحدة بثلاث طرق في سلسلة رسائل واحدة. ويختلف الجيل الأصغر عن الأكبر في تبنّيها، فالشباب يستخدمونها بطلاقة أكبر."]}],"de":[{"heading":"Von den Gassen der Eastlands durch ganz Kenia","paragraphs":["Sheng entstand in den 1970er Jahren in Nairobis Eastlands auf einer Swahili-Basis, angereichert mit englischen, Kikuyu- und Luo-Wörtern. Matatu-Besatzungen, Radiomoderatoren und Musiker trugen es in andere kenianische Städte, heute erscheint es in Werbung für Unter-Dreißigjährige.","Der Wortschatz wechselt rasant: Wörter für Geld, Polizei und Freund werden ersetzt, sobald Außenstehende sie gelernt haben. Dabei gibt es deutliche regionale Unterschiede – jeder Stadtteil hat eigene Wörter, und Kenianer auf dem Land kennen oft nur eine Handvoll davon."]},{"heading":"Eigener Code oder Gefahr fürs Swahili?","paragraphs":["Viele Lehrer und Eltern sehen in Sheng eine Bedrohung für korrektes Swahili, während Linguisten es als eigenes Register beschreiben, nicht als kaputte Sprache. Eine feste Rechtschreibung fehlt, dasselbe Wort kann in einem Nachrichtenverlauf dreifach anders geschrieben werden. Auch zwischen den Generationen unterscheidet sich der Gebrauch: Jüngere greifen selbstverständlicher darauf zurück."]}],"en":[{"heading":"From Eastlands alleys across Kenya","paragraphs":["Sheng began in Nairobi's Eastlands in the 1970s on a Swahili base thickened with English, Kikuyu and Luo words. Matatu crews, radio hosts and musicians spread it to other Kenyan cities, and it now appears in advertising aimed at under-thirties.","Its vocabulary turns over quickly: words for money, police and friend are replaced once outsiders learn them. Regional variation is real, since each estate has its own vocabulary, and rural Kenyans may know only a handful of its words."]},{"heading":"A register, not a broken language","paragraphs":["Teachers and parents often treat Sheng as a threat to proper Swahili, while linguists describe it as a register rather than a broken language. It has no fixed orthography, so the same word may be spelled three ways in one thread of messages. Generational variation matters too: younger speakers reach for it more naturally than their elders."]}]},"context":{"countries":["KE"],"region":"Nairobi estates and other Kenyan cities","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["languages","Nairobi estates and other Kenyan cities"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sheng slang","de":"Sheng slang","en":"Sheng slang"},"url":"https://en.wikipedia.org/wiki/Sheng_slang","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Swahili","de":"Swahili","en":"Swahili"},"url":"https://en.wikipedia.org/wiki/Swahili","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتفاوض عاملان في حافلة صغيرة في كasarani على الأجرة بالشينغ، ثم يتحولان إلى السواحيلية لأجل راكب، وإلى الإنجليزية عند اقتراب شرطي مرور، فيجريان الحوار نفسه بثلاثة أساليب في دقيقة واحدة.","de":"Zwei Matatu-Schaffner in Kasarani feilschen auf Sheng um den Fahrpreis, wechseln für einen Fahrgast ins Swahili und für einen Verkehrspolizisten ins Englische – dasselbe Gespräch in drei Registern binnen einer Minute.","en":"Two matatu touts in Kasarani negotiate a fare in Sheng, switch to Swahili for a passenger and to English when a traffic officer approaches, running the same exchange in three registers within a minute."},"misunderstanding":{"ar":"يظن كثيرون أن الشينغ لغة واحدة موحّدة، لكنها في الحقيقة مجموعة لهجات محلية، وأنباء تراجعها تصف غالباً تحوّلاً لا انهياراً.","de":"Viele halten Sheng für einen einheitlichen Code, doch es ist eine Sammlung lokaler Varianten; Meldungen über seinen Niedergang beschreiben meist Wandel, nicht Zusammenbruch.","en":"Many assume Sheng is one uniform code, but it is a bundle of local varieties; reports of its decline usually describe change, not collapse."},"comparison":{"ar":"حيث تثبّت القواميس مفردات اللغات الرسمية، تعيش الشينغ في حركة دائمة، فكلمتها لا تُحفظ بل تُستبدل حين يعرفها الجميع.","de":"Wo Wörterbücher die Wörter offizieller Sprachen festschreiben, lebt Sheng in ständiger Bewegung: Ein Wort wird nicht bewahrt, sondern ersetzt, sobald alle es kennen.","en":"Where dictionaries fix the words of official languages, Sheng lives in motion: a word is not preserved but replaced once everyone knows it."},"expression":{"original":"Niaje?","language":"Sheng","gloss":{"ar":"كيف حالك؟ / ما الأخبار؟","de":"Wie geht's? / Was läuft?","en":"How are you? / What's up?"},"usage":{"ar":"تحية غير رسمية بين الشباب في أحياء نيروبي","de":"Informelle Begrüßung unter jungen Leuten in Nairobis Stadtteilen","en":"An informal greeting among young people in Nairobi estates"},"transliteration":"niaje"}},{"id":"lng-013","version":2,"slug":"azul-how-tamazight-speakers-greet-in-a-language-long-kept-out-of-school","contentType":"note","category":"languages","title":{"ar":"أزول: تحية الأمازيغ في جبال الأطلس","de":"Azul: Wie Tamazight-Sprecher im Atlas grüßen","en":"Azul: How Tamazight Speakers Greet Across the Atlas"},"deck":{"ar":"كيف يحيّي الناطقون بالأمازيغية بعضهم، وكيف تكشف التحية عن الانتماء لا عن القدرة اللغوية.","de":"Eine alltägliche Grußformel zwischen Markt und Wohnzimmer, die Zugehörigkeit zeigt und nicht mangelnde Sprachkenntnis.","en":"A greeting that moves between shop and home, shifts by region and generation, and signals belonging rather than language ability."},"teaser":{"ar":"تحية واحدة تتنقل بين السوق والبيت، وتختلف من الأطلس إلى القبائل والريف وسوس، وتحمل دلالة هوية أكثر منها دلالة لغة.","de":"Azul wandert durch den Alltag von Tiznit bis Kabylien, variiert je nach Region und Generation und sagt mehr über Herkunft als über Sprachvermögen.","en":"From Tiznit to Kabylie, one everyday word carries identity, varies across mountain communities, and survives a long absence from classrooms."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تُفتح بها الأبواب","paragraphs":["أزول هي التحية الأمازيغية اليومية في المغرب والجزائر، ويُجاب عليها بـ«أزول فلاون»، أي مرحبًا بكم جميعًا.","الأمازيغية عائلة من لغات متقاربة لا لغة واحدة، منها التاشلحيت والتاريفيت والقبائلية والطوارق، لذا تتباين التحيات بين جبال الأطلس.","يختلف الاستعمال أيضًا بين الأجيال والمناطق: كثير من المتحدثين في المدن يحيّون بالعربية أو الفرنسية ويحفظون الأمازيغية للبيت."]},{"heading":"لغة عادت إلى المدرسة ببطء","paragraphs":["تبنّى المغرب حرف تيفيناغ للاستعمال الرسمي سنة 2003، بينما يكتب أمازيغ الجزائر غالبًا بحرف لاتيني.","جعل دستور 2011 الأمازيغية لغة رسمية في المغرب، بعد اثني عشر عامًا من إدخالها الأول إلى الصفوف، لكن التنفيذ ما زال متفاوتًا.","اختيار «أزول» بدل «سلام» في مجلس مختلط إشارة إلى الانتماء الأمازيغي، لا إلى ضعف في العربية."]}],"de":[{"heading":"Ein Gruß, der Türen öffnet","paragraphs":["Azul ist der alltägliche amazighische Gruß in Marokko und Algerien, beantwortet mit Azul fellawen, also hallo an euch alle.","Tamazight ist eine Familie verwandter Sprachen, darunter Taschelhit, Tarifit, Kabylisch und Tuareg, deshalb unterscheiden sich die Grüße im Atlas.","Auch zwischen Generationen und Regionen variiert der Gebrauch: Viele Stadtbewohner grüßen auf Arabisch oder Französisch und sprechen Tamazight zu Hause."]},{"heading":"Eine Sprache kehrt langsam in die Schule zurück","paragraphs":["Marokko führte 2003 Tifinagh für den amtlichen Gebrauch ein, während algerische Amazigh meist eine lateinische Schrift verwenden.","Die Verfassung von 2011 machte Tamazight in Marokko zur Amtssprache, zwölf Jahre nach dem ersten Einzug in die Klassenzimmer; die Umsetzung bleibt ungleich.","Wer in gemischter Runde azul statt salam wählt, signalisiert amazighische Zugehörigkeit, nicht fehlendes Arabisch."]}],"en":[{"heading":"A greeting that opens doors","paragraphs":["Azul is the everyday Amazigh greeting in Morocco and Algeria, answered with Azul fellawen, hello to you all.","Tamazight is a family of related languages, including Tashelhit, Tarifit, Kabyle and Tuareg, so greetings differ across the Atlas.","Usage also varies by generation and region: many urban speakers greet in Arabic or French and keep Tamazight for home."]},{"heading":"A language returning slowly to school","paragraphs":["Morocco adopted Tifinagh for official use in 2003, while Algerian Amazigh mostly writes in a Latin orthography.","Morocco made Tamazight official in the 2011 constitution, twelve years after it was first allowed into classrooms, and implementation remains uneven.","Choosing azul instead of salam in a mixed setting signals Amazigh belonging rather than a lack of Arabic."]}]},"context":{"countries":["MA","DZ"],"region":"Atlas Mountains, Kabylie, Rif and Souss","community":"Amazigh (Berber) communities","continent":"africa","languages":["zgh","ar","fr"],"period":"contemporary"},"tags":["languages","Atlas Mountains, Kabylie, Rif and Souss"],"sources":[{"organization":"Wikipedia","title":{"ar":"Berber languages","de":"Berber languages","en":"Berber languages"},"url":"https://en.wikipedia.org/wiki/Berber_languages","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tifinagh","de":"Tifinagh","en":"Tifinagh"},"url":"https://en.wikipedia.org/wiki/Tifinagh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بائع في تيزنيت يفتتح بـ«أزول» مع زبون يحمل شعارًا أمازيغيًا، ثم ينتقل إلى العربية مع الزبون التالي؛ لا تتعلق أي من الحالتين بالقدرة اللغوية.","de":"Ein Ladenbesitzer in Tiznit begrüßt einen Kunden mit Amazigh-Emblem mit azul und wechselt beim nächsten Kunden ins Arabische; keiner der beiden Wechsel sagt etwas über Sprachfähigkeit.","en":"A shopkeeper in Tiznit opens with azul to a customer wearing an Amazigh emblem, then switches to Arabic with the next customer; neither exchange is about language ability."},"misunderstanding":{"ar":"يُفهم أحيانًا أن من يحيّي بـ«أزول» يرفض العربية، والحال أن التحية اختيار انتماء في سياق مختلط.","de":"Manchmal wird azul als Absage an das Arabische gedeutet, obwohl der Gruß in gemischten Situationen vor allem Zugehörigkeit markiert.","en":"Azul is sometimes read as a rejection of Arabic, when in mixed settings it mainly marks where someone belongs."},"comparison":{"ar":"في المغرب تُكتب الأمازيغية بتيفيناغ رسميًا، وفي الجزائر يغلب الحرف اللاتيني، وهذا الاختلاف يظهر حتى في لافتات التحية.","de":"In Marokko ist Tifinagh offiziell üblich, in Algerien überwiegt die lateinische Schrift – ein Unterschied, der bis auf Grußschilder wirkt.","en":"Morocco officially uses Tifinagh while Algerian Amazigh favours Latin script, a difference visible even on greetings signs."},"expression":{"original":"ⴰⵣⵓⵍ","language":"ⵜⴰⵎⴰⵣⵉⵖⵜ (Tamazight)","gloss":{"ar":"مرحبًا","de":"hallo","en":"hello"},"usage":{"ar":"تحية يومية تُقال عند الدخول إلى دكان أو مجلس، ويُجاب عليها بـ«أزول فلاون».","de":"Alltagsgruß beim Betreten eines Ladens oder einer Versammlung, erwidert mit Azul fellawen.","en":"An everyday greeting on entering a shop or gathering, answered with Azul fellawen."},"transliteration":"azul"}},{"id":"lng-014","version":2,"slug":"ya-ni-the-egyptian-word-that-means-i-mean-and-buys-time","contentType":"detail","category":"communication","title":{"ar":"«يعني»: كلمة مصرية تشتري الوقت","de":"Ya ni: das ägyptische Wort, das Zeit kauft","en":"Ya ni: the Egyptian word that buys time"},"deck":{"ar":"كيف تعمل «يعني» كأداة حوارية في القاهرة والدلتا، بين التردد والتوضيح.","de":"Wie „ya ni“ in Kairo und im Nildelta als Gesprächspartikel wirkt – zwischen Zögern und Erklären.","en":"How “ya ni” works as a conversational tool in Cairo and the Nile Delta, between hesitation and clarification."},"teaser":{"ar":"في حديث القاهرة، «يعني» ليست مجرد حشو، بل وسيلة لإمساك الكلمة وإدارة المعنى.","de":"Im Kairoer Gespräch ist „ya ni“ kein bloßes Füllwort, sondern ein Mittel, das Wort zu behalten und Bedeutung zu steuern.","en":"In Cairo speech, “ya ni” is not just filler; it is a way to hold the floor and manage meaning."},"readingMinutes":1,"sections":{"ar":[{"heading":"وظائف «يعني» في الكلام اليومي","paragraphs":["كلمة «يعني» حرفياً تعني «it means»، لكنها في الكلام المصري تعمل كحشو، وتحوط، وعلامة إصلاح، وربما هزّة كتف ساخرة. في حديث القاهرة، غالباً ما تحل محل التوقف، فتحافظ على الدور دون الالتزام بمحتوى.","عندما تُقال مرتين، «يعني يعني»، فإنها تشير إلى نفاد الصبر أو إلى أن المتحدث قال للتو شيئاً بديهياً. والعامية المصرية سجل منطوق يختلف عن العربية الفصحى، و«يعني» نادراً ما تظهر في الكتابة الرسمية."]},{"heading":"من الجذر إلى الاستخدام الإقليمي","paragraphs":["الجذر نفسه يعطي في العربية الفصحى «يعني» (it means)، لذا تُفهم الكلمة في العالم العربي حتى حيث يُستخدم الحشو بشكل مختلف. يختلف تكرارها ووظيفتها حسب الطبقة والمنطقة والجيل؛ فمتحدثو الخليج والشام يستخدمون حشواً مختلفاً، والكتابة العربية تكاد تحذف «يعني» تماماً."]}],"de":[{"heading":"Funktionen von „ya ni“ im Alltag","paragraphs":["Das Wort „ya ni“ bedeutet wörtlich „es bedeutet“, funktioniert im Ägyptischen aber als Füllwort, Absicherung, Reparaturmarker und manchmal als ironisches Schulterzucken. In der Kairoer Rede ersetzt es oft eine Pause und hält so das Rederecht, ohne sich inhaltlich festzulegen.","Zweimal gesagt, „ya ni ya ni“, signalisiert es Ungeduld oder dass der Sprecher gerade etwas Offensichtliches gesagt hat. Ägyptisches Arabisch ist eine gesprochene Varietät, die sich vom Modernen Standardarabisch unterscheidet, und „ya ni“ erscheint selten in formeller Schrift."]},{"heading":"Vom Wortstamm zur regionalen Verwendung","paragraphs":["Derselbe Wortstamm ergibt im Standardarabischen „yani“ (es bedeutet), daher wird das Wort in der arabischen Welt verstanden, auch wo das Füllwort anders verwendet wird. Häufigkeit und Funktion variieren nach Klasse, Region und Generation; Golf- und Levante-Sprecher verwenden andere Füllwörter, und die Schriftsprache entfernt „ya ni“ fast vollständig."]}],"en":[{"heading":"Functions of “ya ni” in everyday talk","paragraphs":["The word “ya ni” literally means “it means,” but in Egyptian speech it works as a filler, a hedge, a repair marker, and sometimes an ironic shrug. In Cairo talk it often replaces a pause, keeping the floor without committing to content.","Said twice, “ya ni ya ni” signals impatience or that the speaker has just stated something obvious. Egyptian Arabic is a spoken variety distinct from Modern Standard Arabic, and “ya ni” rarely appears in formal writing."]},{"heading":"From root to regional use","paragraphs":["The same root gives standard Arabic “yani” (it means), so the word is understood across the Arab world even where the filler is used differently. Frequency and function vary by class, region, and generation; Gulf and Levantine speakers use different fillers, and written Arabic removes “ya ni” almost entirely."]}]},"context":{"countries":["EG"],"region":"Cairo and the Nile Delta","continent":"africa","languages":["ar","en"],"period":"contemporary"},"tags":["communication","Cairo and the Nile Delta"],"sources":[{"organization":"Wikipedia","title":{"ar":"Egyptian Arabic","de":"Egyptian Arabic","en":"Egyptian Arabic"},"url":"https://en.wikipedia.org/wiki/Egyptian_Arabic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Discourse marker","de":"Discourse marker","en":"Discourse marker"},"url":"https://en.wikipedia.org/wiki/Discourse_marker","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق تاكسي في القاهرة يشرح طريقاً يستخدم «يعني» أربع مرات في جملة واحدة؛ يسمع الراكب ليس غموضاً بل ادعاءً بأن الشرح بديهي والزحام ليس خطأ السائق.","de":"Ein Kairoer Taxifahrer, der eine Route erklärt, verwendet „ya ni“ viermal in einem Satz; der Fahrgast hört keine Unklarheit, sondern die Behauptung, die Erklärung sei offensichtlich und der Verkehr nicht die Schuld des Fahrers.","en":"A Cairo taxi driver explaining a route uses “ya ni” four times in one sentence; the passenger hears not vagueness but a claim that the explanation is obvious and the traffic is not the driver’s fault."},"misunderstanding":{"ar":"قد يظن السامع غير المصري أن تكرار «يعني» يدل على التردد أو عدم المعرفة، بينما هو في الغالب وسيلة لإمساك الكلمة أو التأكيد على وضوح القول.","de":"Ein nicht-ägyptischer Hörer könnte denken, die Wiederholung von „ya ni“ zeige Zögern oder Unwissen, während sie meist dazu dient, das Rederecht zu behalten oder die Klarheit der Aussage zu betonen.","en":"A non-Egyptian listener might think repeated “ya ni” signals hesitation or ignorance, when it usually serves to hold the floor or stress that the point is clear."},"comparison":{"ar":"بينما تُستخدم «يعني» في الفصحى كفعل بمعنى «it means»، فإنها في العامية المصرية أداة حوارية متعددة الوظائف، تختلف عن حشو الخليج والشام.","de":"Während „yani“ im Standardarabischen als Verb „es bedeutet“ fungiert, ist „ya ni“ im ägyptischen Dialekt ein vielseitiges Gesprächspartikel, das sich von Füllwörtern im Golf und in der Levante unterscheidet.","en":"While “yani” functions as the verb “it means” in Standard Arabic, “ya ni” in Egyptian dialect is a multi-purpose conversational tool, differing from fillers in Gulf and Levantine speech."},"expression":{"original":"يعني إيه؟","language":"العربية المصرية (Egyptian Arabic)","gloss":{"ar":"ماذا يعني؟","de":"Was bedeutet das?","en":"What does it mean?"},"usage":{"ar":"تُقال لطلب توضيح أو للتعبير عن عدم الفهم، وتُستخدم في المواقف اليومية غير الرسمية.","de":"Wird verwendet, um eine Erklärung zu erbitten oder Unverständnis auszudrücken, in informellen Alltagssituationen.","en":"Used to ask for clarification or express non-comprehension, in informal everyday situations."},"transliteration":"ya ni eh?"}},{"id":"lng-015","version":2,"slug":"kwame-kofi-akosua-ghanaian-names-that-record-the-day-you-were-born","contentType":"note","category":"languages","title":{"ar":"أسماء الأكان: يوم ميلادك هو اسمك","de":"Kwame, Kofi, Akosua: Namen, die den Geburtstag verraten","en":"Kwame, Kofi, Akosua: Ghanaian names that record your birthday"},"deck":{"ar":"في غانا، يكشف اسم الشخص الأول عن يوم ولادته، ويحمل توقعات عن شخصيته.","de":"In Ghana verrät der Vorname den Wochentag der Geburt und trägt Erwartungen an den Charakter.","en":"In Ghana, a first name reveals the day you were born and carries expectations about character."},"teaser":{"ar":"في غانا، اسمك الأول ليس مجرد علامة؛ إنه يخبر الناس باليوم الذي ولدت فيه ويحمل توقعات عن شخصيتك.","de":"In Ghana ist der erste Name kein bloßes Etikett; er sagt, an welchem Tag du geboren wurdest, und trägt Erwartungen an deinen Charakter.","en":"In Ghana, your first name is not just a label; it tells people the day you were born and carries expectations about your character."},"readingMinutes":1,"sections":{"ar":[{"heading":"الاسم الذي يروي اليوم","paragraphs":["بين متحدثي الأكان في مناطق أشانتي والشرقية والوسطى وبرونغ-أهافو، يُمنح الطفل اسم كرادين، أي اسم الروح، يتحدد بيوم الأسبوع الذي وُلد فيه: كوامي للذكر المولود يوم السبت، كوفي للجمعة، أكوسوا للأنثى المولودة يوم الأحد.","هذا الاسم ليس للزينة؛ إنه يحمل توقعات عن الطبع ويُستخدم في المخاطبة الرسمية كما في المداعبة. ويأخذ الطفل أيضًا أسماء من خط والده ومن المعمودية المسيحية، فقد يجيب الشخص الواحد على ثلاثة أسماء في ثلاثة مواقف."]},{"heading":"ما وراء الحدود والوثائق","paragraphs":["انتقل هذا النظام مع تجارة الرقيق عبر الأطلسي، ولا تزال أسماء الأيام حية بين عائلات الكاريبي الأفريقي والأمريكيين الأفارقة. وتظهر أسماء الأيام على الوثائق الرسمية، وقد يربك ترتيب الأسماء على جواز السفر الغاني المسؤولين الأجانب.","يختلف الأمر حسب المنطقة والجيل: فالنظام أكاني وفانتي بالأساس، وليس معممًا في غانا كلها؛ فمجتمعات الإيوي والغا والداغومبا تسمي بطريقة مختلفة، وغالبًا ما تتفوق الأسماء المسيحية في الاستخدام اليومي."]}],"de":[{"heading":"Der Name, der den Tag erzählt","paragraphs":["Bei Akan-Sprechern in den Regionen Ashanti, Eastern, Central und Brong-Ahafo erhält ein Kind einen Kradin, einen Seelennamen, der durch den Wochentag der Geburt festgelegt ist: Kwame für einen am Samstag geborenen Mann, Kofi für Freitag, Akosua für Sonntag.","Der Name ist nicht dekorativ; er trägt Erwartungen an den Charakter und wird sowohl für formelle Anrede als auch für Neckereien verwendet. Ein Kind erhält zudem Namen aus der väterlichen Linie und aus der christlichen Taufe, sodass eine Person in drei Situationen auf drei Namen hören kann."]},{"heading":"Über Grenzen und Dokumente hinaus","paragraphs":["Das System reiste mit dem transatlantischen Sklavenhandel, und Tagesnamen überleben bei afrokaribischen und afroamerikanischen Familien. Tagesnamen erscheinen auf offiziellen Dokumenten, und die Reihenfolge der Namen im ghanaischen Pass kann ausländische Beamte verwirren.","Regionale und generationelle Unterschiede gibt es: Das System ist Akan- und eng verwandte Fante-Praxis, nicht in ganz Ghana verbreitet; Ewe-, Ga- und Dagomba-Gemeinschaften benennen anders, und christliche Namen haben oft Vorrang."]}],"en":[{"heading":"The name that tells the day","paragraphs":["Among Akan speakers in the Ashanti, Eastern, Central and Brong-Ahafo regions, a child receives a kradin, a soul name, fixed by the day of the week of birth: Kwame for a Saturday-born man, Kofi for Friday, Akosua for Sunday.","The name is not decorative; it carries expectations about character and is used for formal address as well as teasing. A child also takes names from the father's line and from Christian baptism, so one person can answer to three names in three settings."]},{"heading":"Beyond borders and documents","paragraphs":["The system travelled with the transatlantic slave trade, and day names survive among Afro-Caribbean and African American families. Day names appear on official documents, and the order of names on a Ghanaian passport can confuse foreign officials.","There is regional and generational variation: the system is Akan and closely related Fante practice, not universal in Ghana; Ewe, Ga and Dagomba communities name differently, and Christian names often take precedence."]}]},"context":{"countries":["GH"],"region":"Ashanti, Eastern, Central and Brong-Ahafo regions","continent":"africa","languages":["ak","en","tw"],"period":"contemporary"},"tags":["languages","Ashanti, Eastern, Central and Brong-Ahafo regions"],"sources":[{"organization":"Wikipedia","title":{"ar":"Akan name","de":"Akan name","en":"Akan name"},"url":"https://en.wikipedia.org/wiki/Akan_name","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Twi-Fante language","de":"Twi-Fante language","en":"Twi-Fante language"},"url":"https://en.wikipedia.org/wiki/Twi-Fante_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتقابل زميلان غانيان لأول مرة في أكرا ويسأل كل منهما عن اسم يوم الآخر قبل مسماه الوظيفي؛ وعندما يكتشفان أن كليهما «يا»، يتحول اللقاء إلى مداعبة كأنهما أشقاء.","de":"Zwei ghanaische Kollegen treffen sich zum ersten Mal in Accra und fragen nach dem Tagesnamen, bevor sie ihre Berufsbezeichnungen nennen; als beide Yaa sind, wird das Treffen zu geschwisterlichem Neckereien.","en":"Two Ghanaian colleagues meeting for the first time in Accra ask each other's day names before their job titles; discovering both are Yaa turns the meeting into sibling-like teasing."},"misunderstanding":{"ar":"قد يظن الزائر أن اسم اليوم مجرد لقب عائلي أو تقليد شعبي، بينما هو هوية روحية ومقياس للطبع، ويُستخدم في المخاطبة الرسمية.","de":"Besucher könnten denken, der Tagesname sei nur ein Familienname oder ein folkloristischer Brauch, doch er ist spirituelle Identität und Charakterskala und wird in der formellen Anrede verwendet.","en":"A visitor might think the day name is just a family name or a folk custom, but it is spiritual identity and a character measure, used in formal address."},"comparison":{"ar":"في حين أن كثيرًا من الثقافات تختار الأسماء حسب الصوت أو المعنى أو القديس، فإن الأكان يربطون الاسم بيوم الميلاد، مما يجعل التقويم جزءًا من الهوية الشخصية.","de":"Während viele Kulturen Namen nach Klang, Bedeutung oder Heiligen wählen, verbinden die Akan den Namen mit dem Geburtstag, wodurch der Kalender Teil der persönlichen Identität wird.","en":"While many cultures choose names by sound, meaning or saints, Akan people link the name to the birthday, making the calendar part of personal identity."},"expression":{"original":"Akosua","language":"Akan (Twi)","gloss":{"ar":"اسم أنثوي للطفلة المولودة يوم الأحد","de":"weiblicher Name für ein am Sonntag geborenes Kind","en":"female name for a Sunday-born child"},"usage":{"ar":"يُستخدم للنداء الرسمي والمداعبة، ويحمل توقعات عن الطبع.","de":"Wird für formelle Anrede und Neckereien verwendet und trägt Charaktererwartungen.","en":"Used for formal address and teasing, and carries character expectations."},"transliteration":"Akosua"}},{"id":"lng-016","version":2,"slug":"alliteration-instead-of-rhyme-how-somali-poetry-is-built-to-be-remembered","contentType":"note","category":"languages","title":{"ar":"الشعر الصومالي: تكرار الحرف بدل القافية","de":"Somalische Dichtung: Alliteration statt Reim","en":"Somali Poetry: Alliteration Instead of Rhyme"},"deck":{"ar":"في الصومال، يُبنى الشعر على تكرار حرف واحد ليُحفظ ويُنقل، ويُستخدم في حل النزاعات.","de":"In Somalia basiert Poesie auf der Wiederholung eines Konsonanten, um erinnert und weitergegeben zu werden – und sie schlichtet Konflikte.","en":"In Somalia, poetry is built on repeating one consonant to be remembered and passed on—and it has settled disputes."},"teaser":{"ar":"الشعر الصومالي يعتمد على تكرار حرف واحد بدل القافية، مما يجعله سهل الحفظ والاستشهاد به في الحياة اليومية.","de":"Somalische Poesie nutzt die Alliteration eines Konsonanten statt Endreim, was sie leicht merkbar und im Alltag zitierbar macht.","en":"Somali poetry uses alliteration of a single consonant instead of end rhyme, making it easy to memorize and quote in everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"بنية تعتمد على التكرار","paragraphs":["يعتمد الشعر الصومالي على تكرار حرف واحد من بداية القصيدة إلى نهايتها كأداة بنيوية رئيسية، بدلاً من القافية في نهاية البيت. هذا التكرار يمنح القصيدة إيقاعًا مميزًا ويسهل حفظها. وتُصنف الأنواع الشعرية: الگباي هو الشكل الكلاسيكي الطويل، بينما البورانبور هو نوع نسائي بإيقاع وسياق أداء مختلفين.","تنتقل القصائد عبر الراديو والكاسيت، وقد ساهمت في حل النزاعات، لأن القصيدة المعروفة يمكنها أن تسمي تكلفة استمرار القتال. والشعراء ليسوا متخصصين، بل الشعر جزء من الكفاءة العادية، ويقتبس المتحدثون أبياتًا في المحادثات لدعم حججهم."]},{"heading":"شعر للحياة اليومية","paragraphs":["في مقديشو، يستشهد شيخ بأربعة أبيات من گباي لحل نزاع على الأرض، حيث يحمل الحرف المكرر الحجة؛ يتعرف الطرفان على القصيدة قبل أن يوافقا على استنتاجها. هذا يظهر كيف أن الشعر أداة عملية في الحياة الاجتماعية.","تبنى اللغة الصومالية الكتابة اللاتينية فقط في عام 1972، وكان الشعر قد حافظ على أوزانه التي كان على اللغة المكتوبة أن تلحق بها. هذا التداخل بين الشعر واللغة يبرز أهمية الشعر في الحفاظ على التراث. ولا يشترك جميع المتحدثين بالصومالية في قانون شعري واحد، وغالبًا ما يتعرف شباب المهجر على الگباي عبر الإنترنت بدلاً من الإنشاد؛ كما تختلف الأنواع واللهجات بين الصومال وجيبوتي وأوغادين."]}],"de":[{"heading":"Struktur durch Wiederholung","paragraphs":["Somalische Poesie verwendet die Alliteration eines Konsonanten durch das gesamte Gedicht als Hauptstrukturmittel statt Endreim. Diese Wiederholung verleiht dem Gedicht einen besonderen Rhythmus und erleichtert das Auswendiglernen. Die Genres sind hierarchisch: Der Gabay ist die lange klassische Form, während Buraanbur ein Frauengenre mit anderem Rhythmus und Aufführungskontext ist.","Gedichte verbreiten sich über Radio und Kassette und haben Streitigkeiten geschlichtet, denn ein bekanntes Gedicht kann die Kosten fortgesetzter Kämpfe benennen. Dichtung ist alltägliche Kompetenz, keine Spezialistenkunst; Sprecher zitieren Verse im Gespräch, um ein Argument zu stützen."]},{"heading":"Dichtung für den Alltag","paragraphs":["In Mogadischu zitiert ein Ältester vier Zeilen eines Gabay, um einen Landstreit zu schlichten; der wiederholte Konsonant trägt das Argument. Die Parteien erkennen das Gedicht an, bevor sie seiner Schlussfolgerung zustimmen. Das zeigt, wie Poesie als praktisches Werkzeug im sozialen Leben dient.","Somali übernahm die lateinische Schrift erst 1972, und die Dichtung bewahrte Metren, die die Schriftsprache erst einholen musste. Diese Verbindung von Poesie und Sprache unterstreicht die Bedeutung der Dichtung für das kulturelle Erbe. Nicht alle Somali-Sprecher teilen einen poetischen Kanon, und Diaspora-Jugendliche begegnen dem Gabay oft online statt durch Rezitation; Genres und Dialekte variieren zwischen Somalia, Dschibuti und Ogaden."]}],"en":[{"heading":"Structure Through Repetition","paragraphs":["Somali poetry uses alliteration of one consonant through an entire poem as its main structural device rather than end rhyme. This repetition gives the poem a distinctive rhythm and makes it easier to memorize. Genres are ranked: the gabay is the long classical form, while buraanbur is a women's genre with a different rhythm and performance setting.","Poems travel by radio and cassette and have settled disputes, because a well-known poem can name the cost of continued fighting. Poetry is ordinary competence rather than a specialist art, and speakers quote lines in conversation to make an argument."]},{"heading":"Poetry for Everyday Life","paragraphs":["In Mogadishu, an elder settling a land dispute quotes four lines of a gabay whose repeated consonant carries the argument; the parties recognise the poem before they agree with its conclusion. This shows how poetry serves as a practical tool in social life.","Somali adopted a Latin orthography only in 1972, and poetry preserved metres that the written language had to catch up with. This interplay between poetry and language highlights poetry's role in preserving heritage. Not all Somali speakers share one poetic canon, and diaspora youth often meet the gabay online rather than by recitation; genres and dialect vary between Somalia, Djibouti and the Ogaden."]}]},"context":{"countries":["SO","ET","KE"],"region":"Somali-speaking Horn of Africa","continent":"africa","languages":["so","ar"],"period":"contemporary"},"tags":["languages","Somali-speaking Horn of Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Somali language","de":"Somali language","en":"Somali language"},"url":"https://en.wikipedia.org/wiki/Somali_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Somali literature","de":"Somali literature","en":"Somali literature"},"url":"https://en.wikipedia.org/wiki/Somali_literature","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مقديشو، يستشهد شيخ بأربعة أبيات من گباي لحل نزاع على الأرض، حيث يحمل الحرف المكرر الحجة؛ يتعرف الطرفان على القصيدة قبل أن يوافقا على استنتاجها.","de":"In Mogadischu zitiert ein Ältester vier Zeilen eines Gabay, um einen Landstreit zu schlichten; der wiederholte Konsonant trägt das Argument. Die Parteien erkennen das Gedicht an, bevor sie seiner Schlussfolgerung zustimmen.","en":"A Mogadishu elder settling a land dispute quotes four lines of a gabay whose repeated consonant carries the argument; the parties recognise the poem before they agree with its conclusion."},"misunderstanding":{"ar":"يُفهم أحيانًا أن الشعر الصومالي مجرد فن ترفيهي، لكنه في الواقع أداة اجتماعية وقانونية تستخدم في حل النزاعات والتعبير عن المواقف.","de":"Manchmal wird somalische Dichtung als reine Unterhaltungskunst missverstanden, doch sie ist ein soziales und rechtliches Werkzeug zur Konfliktlösung und Meinungsäußerung.","en":"Somali poetry is sometimes mistaken for mere entertainment, but it is a social and legal tool used to resolve disputes and express positions."},"comparison":{"ar":"على عكس الشعر العربي الذي يعتمد على القافية، يعتمد الشعر الصومالي على تكرار حرف واحد، مما يجعله أكثر سهولة في الحفظ والاستشهاد.","de":"Anders als arabische Dichtung, die auf Reim setzt, basiert somalische Dichtung auf der Wiederholung eines Konsonanten, was sie leichter merkbar und zitierbar macht.","en":"Unlike Arabic poetry, which relies on rhyme, Somali poetry builds on the repetition of a single consonant, making it easier to memorize and quote."},"expression":{"original":"Gabay","language":"Soomaali (Somali)","gloss":{"ar":"قصيدة كلاسيكية طويلة","de":"klassisches langes Gedicht","en":"classical long poem"},"usage":{"ar":"يُستخدم للإشارة إلى الشكل الشعري الكلاسيكي الطويل في الشعر الصومالي.","de":"Bezeichnet die klassische lange Gedichtform in der somalischen Dichtung.","en":"Refers to the classical long poetic form in Somali poetry."},"transliteration":"gabay"}},{"id":"lng-017","version":2,"slug":"otsukaresama-desu-the-japanese-office-phrase-that-thanks-you-for-existing-at-wor","contentType":"note","category":"communication","title":{"ar":"عبارة تُشكرك على وجودك في العمل","de":"Der japanische Bürogruß, der bloße Anwesenheit dankt","en":"Otsukaresama desu: the Japanese office phrase that thanks you for existing at work"},"deck":{"ar":"في اليابان، تحية واحدة تعترف بجهد الزميل لا بنتيجة عمله، وتُقال عند المرور، وفي نهاية الاجتماع، وعند مغادرة المكتب.","de":"Otsukaresama desu ist mehr als ein Gruß: Es würdigt die Anstrengung, nicht das Ergebnis, und begleitet den Büroalltag vom Flur bis zur E-Mail.","en":"More than a greeting, otsukaresama desu acknowledges effort rather than results, and it accompanies the office day from corridor to email."},"teaser":{"ar":"عبارة «أوتسوكاريساما ديسو» ليست مجرد تحية، بل اعتراف بجهد الزميل اليومي، تُقال عند المرور والاجتماعات والمغادرة.","de":"Otsukaresama desu begleitet japanische Bürotage vom Flur bis zur E-Mail. Der Gruß dankt für Anstrengung, nicht für Ergebnisse.","en":"Otsukaresama desu isn't just a greeting; it thanks colleagues for their effort, not results, and follows the office day from corridor to email."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تعترف بالجهد لا بالنتيجة","paragraphs":["عندما يمر زميلان في ممر بطوكيو عند السادسة وخمس وخمسين دقيقة مساءً، يقول كل منهما «أوتسوكاريساما ديسو»، رغم أن أحدهما قادم لوردية ليلية والآخر لم ينجز شيئًا بعد. العبارة تشكر الجهد المبذول، لا النتيجة.","تقع العبارة ضمن «الكييغو»، السجل التكريمي الياباني بثلاث طبقات: سونكييغو (احترامي)، كينجوغو (متواضع)، وتينييغو (مهذب). وقد يقول الرئيس لمرؤوسه «غوكوروساما» من أعلى إلى أسفل، لكن لا ينبغي للمرؤوس أن يستخدمها صعودًا؛ فاتجاه العبارة محدد نحويًا."]},{"heading":"من الممر إلى البريد الإلكتروني","paragraphs":["تفتتح رسائل البريد الإلكتروني غالبًا بعبارة «أوسيوا ني ناتي أوري ماسو»، الصيغة المتواضعة لشكر الدعم، لتحقيق الغرض نفسه. ولا يوجد للعبارة مقابل إنجليزي بكلمة واحدة، لذا تتركها الترجمة المرئية تحية أو تحذفها."]}],"de":[{"heading":"Dank für Mühe, nicht für Resultate","paragraphs":["Zwei Kollegen begegnen sich um 18.55 Uhr in einem Tokioter Flur; beide sagen otsukaresama desu, obwohl einer zur Nachtschicht kommt und der andere an diesem Tag noch nichts geleistet hat. Der Gruß dankt für die Anstrengung, nicht für ein Ergebnis.","Die Wendung gehört zum keigo, der japanischen Höflichkeitssprache mit drei Ebenen: sonkeigo (respektvoll), kenjōgo (bescheiden) und teineigo (höflich). Vorgesetzte sagen gokurosama nach unten, doch Untergebene sollten es nicht nach oben verwenden; die Richtung ist grammatikalisch festgelegt."]},{"heading":"Vom Flur bis zur E-Mail","paragraphs":["E-Mails beginnen oft mit osewa ni natte orimasu, der bescheidenen Form des Dankes für Unterstützung, um dasselbe zu erreichen. Einen englischen Ein-Wort-Entsprechung gibt es nicht, daher lassen Untertitel den Gruß oft als Begrüßung stehen oder weglassen."]}],"en":[{"heading":"Thanks for effort, not results","paragraphs":["Two colleagues pass in a Tokyo corridor at 6.55 p.m.; both say otsukaresama desu, though one is arriving for the night shift and the other has not yet done anything that day. The phrase thanks the effort, not a result.","It belongs to keigo, the honorific register with three layers: sonkeigo (respectful), kenjōgo (humble) and teineigo (polite). A superior may say gokurosama downward to a subordinate, but a junior should not use it upward; the direction of the phrase is grammaticalised."]},{"heading":"From corridor to email","paragraphs":["Email openings often use osewa ni natte orimasu, the humble form of thank you for your support, to the same end. The phrase has no one-word English equivalent, which is why subtitles usually leave it as a greeting or drop it."]}]},"context":{"countries":["JP"],"region":"Nationwide, strongest in offices and service work","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in offices and service work"],"sources":[{"organization":"Wikipedia","title":{"ar":"Japanese honorifics","de":"Japanese honorifics","en":"Japanese honorifics"},"url":"https://en.wikipedia.org/wiki/Japanese_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific speech in Japanese","de":"Honorific speech in Japanese","en":"Honorific speech in Japanese"},"url":"https://en.wikipedia.org/wiki/Honorific_speech_in_Japanese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يمر زميلان في ممر بطوكيو عند السادسة وخمس وخمسين دقيقة مساءً؛ يقول كل منهما «أوتسوكاريساما ديسو»، رغم أن أحدهما قادم لوردية ليلية والآخر لم ينجز شيئًا بعد.","de":"Zwei Kollegen begegnen sich um 18.55 Uhr in einem Tokioter Flur; beide sagen otsukaresama desu, obwohl einer zur Nachtschicht kommt und der andere an diesem Tag noch nichts geleistet hat.","en":"Two colleagues pass in a Tokyo corridor at 6.55 p.m.; both say otsukaresama desu, though one is arriving for the night shift and the other has not yet done anything that day."},"misunderstanding":{"ar":"يعتقد البعض أن العبارة تعني «عمل جيد» أو «أحسنت»، لكنها في الحقيقة شكر على الجهد المبذول، لا على نتيجة محددة.","de":"Manche halten den Gruß für ein „gut gemacht“ oder „Danke für das Ergebnis“, doch er würdigt die Anstrengung, nicht einen konkreten Erfolg.","en":"Some think the phrase means “good job” or “well done,” but it thanks the effort, not a specific result."},"comparison":{"ar":"في الإنجليزية، قد نقول «أحسنت» أو «شكرًا لعملك»، لكن أياً منهما لا يحمل الاعتراف اليومي بوجود الزميل في العمل الذي تحمله «أوتسوكاريساما ديسو».","de":"Im Deutschen sagen wir vielleicht „Gute Arbeit“ oder „Danke für deinen Einsatz“, aber keine dieser Wendungen trägt die alltägliche Anerkennung der bloßen Anwesenheit, die otsukaresama desu ausdrückt.","en":"In English we might say “good job” or “thanks for your work,” but neither carries the everyday acknowledgment of a colleague's presence that otsukaresama desu does."},"expression":{"original":"お疲れ様です","language":"日本語 (Japanese)","gloss":{"ar":"شكرًا لعملك الشاق / أحسنت","de":"Danke für deine Mühe / gut gemacht","en":"thank you for your hard work / well done"},"usage":{"ar":"تُقال عند المرور بزميل، وفي نهاية اجتماع، وعند مغادرة المكتب، للتعبير عن التقدير للجهد المبذول.","de":"Wird beim Vorbeigehen an Kollegen, am Ende von Besprechungen und beim Verlassen des Büros gesagt, um Anerkennung für die Anstrengung auszudrücken.","en":"Said when passing a colleague, at the end of a meeting and when leaving the office, to express appreciation for effort."},"transliteration":"otsukaresama desu"}},{"id":"lng-018","version":2,"slug":"aizuchi-the-japanese-nods-and-hai-that-mean-i-am-listening-not-i-agree","contentType":"note","category":"communication","title":{"ar":"أيزوتشي: الإيماءات و«هاي» التي تعني أنني أستمع","de":"Aizuchi: Die japanischen Nicken und „hai“, die Zuhören bedeuten","en":"Aizuchi: The Japanese Nods and 'Hai' That Mean I'm Listening"},"deck":{"ar":"في اليابان، الردود الخلفية مثل «هاي» و«إي» و«سو ديس ني» تُظهر الانتباه، لا الموافقة.","de":"In Japan zeigen Backchannel-Signale wie „hai“, „e“ und „so desu ne“ Aufmerksamkeit, nicht Zustimmung.","en":"In Japan, backchannel responses like 'hai', 'e', and 'so desu ne' signal attention, not agreement."},"teaser":{"ar":"الإيماءات المتكررة أثناء الاستماع ليست علامة على الاتفاق، بل على المشاركة. تعرف على أيزوتشي، فن الاستماع التعاوني في اليابان.","de":"Häufige Nicken beim Zuhören sind kein Zeichen von Einverständnis, sondern von Beteiligung. Entdecken Sie Aizuchi, die Kunst des kooperativen Zuhörens in Japan.","en":"Frequent nods while listening are not a sign of consent but of engagement. Discover aizuchi, the art of cooperative listening in Japan."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو الأيزوتشي؟","paragraphs":["الأيزوتشي هي الردود الخلفية، مثل «هاي» و«إي» و«سو ديس ني»، التي يُدخلها المستمع كل بضع ثوانٍ. إنها تشير إلى الانتباه والفهم وليس الموافقة، وقد يقول المتحدث الياباني «هاي» وهو يستعد للاعتراض.","الأيزوتشي المتكرر متوقع؛ المستمع الصامت قد يبدو باردًا، بينما صمت المستمع غير الياباني قد يُفسر على أنه عدم اهتمام. في المكالمات الهاتفية التجارية، يجب أن تكون الردود الخلفية مسموعة لأن الطرف الآخر لا يرى المستمع على الإطلاق."]},{"heading":"الاستماع التعاوني","paragraphs":["تصف الأبحاث الأيزوتشي بأنه استماع تعاوني، حيث تُوقَّت الردود لتتوافق مع عبارات المتحدث وليس مع نهاية دوره. يختلف تكرار الأيزوتشي حسب اللهجة والفرد؛ فمتحدثو كانساي غالبًا ما يردون بكثافة أكبر، والإقامة الطويلة في الخارج تعيد تشكيل هذه العادة. إنه عرف اجتماعي، وليس اختبارًا للشخصية."]}],"de":[{"heading":"Was ist Aizuchi?","paragraphs":["Aizuchi sind die Backchannel-Antworten wie „hai“, „e“ und „so desu ne“, die ein Zuhörer alle paar Sekunden einwirft. Sie signalisieren Aufmerksamkeit und Verständnis, nicht Zustimmung, und japanische Sprecher sagen möglicherweise „hai“, während sie sich auf Widerspruch vorbereiten.","Häufiges Aizuchi wird erwartet; ein schweigender Zuhörer kann kalt wirken, während die Stille eines nicht-japanischen Zuhörers als Unaufmerksamkeit gelesen werden kann. Bei geschäftlichen Telefonaten sind hörbare Backchannels erforderlich, weil die andere Partei den Zuhörer überhaupt nicht sehen kann."]},{"heading":"Kooperatives Zuhören","paragraphs":["Die Forschung beschreibt Aizuchi als kooperatives Zuhören, bei dem die Antworten auf die Phrasen des Sprechers abgestimmt sind und nicht auf das Ende seines Redebeitrags. Die Häufigkeit von Aizuchi variiert je nach Dialekt und Individuum; Kansai-Sprecher geben oft dichtere Backchannels, und ein langer Auslandsaufenthalt verändert die Gewohnheit. Es ist eine Konvention, kein Persönlichkeitstest."]}],"en":[{"heading":"What Is Aizuchi?","paragraphs":["Aizuchi are the backchannel responses, such as hai, e, and so desu ne, that a listener inserts every few seconds. They signal attention and comprehension rather than agreement, and Japanese speakers may say hai while preparing to disagree.","Frequent aizuchi are expected; a silent listener can seem cold, while a non-Japanese listener's silence may read as inattention. Business phone calls require audible backchannels because the other party cannot see the listener at all."]},{"heading":"Cooperative Listenership","paragraphs":["Research on aizuchi describes it as cooperative listenership, with responses timed to the speaker's phrases rather than to the end of a turn. Aizuchi frequency differs by dialect and individual; Kansai speakers often backchannel more densely, and long residence abroad reshapes the habit. It is a convention, not a personality test."]}]},"context":{"countries":["JP"],"region":"Nationwide","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Aizuchi","de":"Aizuchi","en":"Aizuchi"},"url":"https://en.wikipedia.org/wiki/Aizuchi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Japanese language","de":"Japanese language","en":"Japanese language"},"url":"https://en.wikipedia.org/wiki/Japanese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مكالمة جماعية في طوكيو، يقول العميل من أوساكا «هاي، هاي» كل بضع جمل؛ يسمع المورد الأجنبي موافقة، لكن العميل يعترض لاحقًا على الشروط، لأن «هاي» كانت صوت الاستماع.","de":"In einer Telefonkonferenz in Tokio sagt der Kunde aus Osaka alle paar Sätze „hai, hai“; der ausländische Lieferant hört Zustimmung, aber der Kunde bestreitet später die Bedingungen, denn „hai“ war das Geräusch des Zuhörens.","en":"On a Tokyo conference call the Osaka client says hai, hai every few sentences; the foreign supplier hears consent, but the client later disputes the terms, because hai was the sound of listening."},"misunderstanding":{"ar":"كثيرًا ما يُفهم «هاي» على أنه موافقة، لكنه في سياق الأيزوتشي يعني ببساطة «أنا أستمع». قد يستخدمه المتحدث الياباني حتى وهو يخطط للاعتراض.","de":"„Hai“ wird oft als Zustimmung missverstanden, bedeutet im Aizuchi-Kontext aber einfach „Ich höre zu“. Ein japanischer Sprecher verwendet es sogar, wenn er Einspruch plant.","en":"Hai is often mistaken for agreement, but in aizuchi it simply means 'I'm listening.' A Japanese speaker may use it even when planning to disagree."},"comparison":{"ar":"في الثقافات الأخرى، قد يُنظر إلى الصمت على أنه تركيز، بينما في اليابان قد يُفسر على أنه عدم اهتمام. الأيزوتشي يملأ الفراغ بإشارات لفظية وغير لفظية.","de":"In anderen Kulturen kann Schweigen als Konzentration gelten, in Japan wird es oft als Desinteresse interpretiert. Aizuchi füllt die Lücke mit verbalen und nonverbalen Signalen.","en":"In other cultures, silence may be seen as focus, while in Japan it can be interpreted as disinterest. Aizuchi fills the gap with verbal and non-verbal cues."},"expression":{"original":"そうですね","language":"日本語 (Japanese)","gloss":{"ar":"هذا صحيح، أليس كذلك؟ (رد استماع)","de":"Das ist so, nicht wahr? (Hörsignal)","en":"that is so, isn't it (listening response)"},"usage":{"ar":"تُستخدم لتأكيد أنك تتابع الحديث، وغالبًا مع إيماءة بالرأس.","de":"Wird verwendet, um zu bestätigen, dass man dem Gespräch folgt, oft mit einem Nicken.","en":"Used to affirm that you are following the conversation, often with a nod."},"transliteration":"so desu ne"}},{"id":"lng-019","version":2,"slug":"banmal-and-jondaenmal-korean-s-two-speech-worlds","contentType":"note","category":"languages","title":{"ar":"اللغة الكورية: عالمان في الحديث","de":"Banmal und Jondaenmal: Koreas zwei Sprechwelten","en":"Banmal and Jondaenmal: Korea's two speech worlds"},"deck":{"ar":"بين البانمال والجوندينمال، يحدد العمر والأدب طريقة مخاطبة الكوريين لبعضهم البعض.","de":"Zwischen formeller und informeller Anrede entscheidet in Korea oft das Alter – und ein höfliches Angebot.","en":"Between casual and polite styles, age and etiquette shape how Koreans address each other."},"teaser":{"ar":"في كوريا، مجرد تغيير صيغة الفعل قد يعني اقترابًا أو احترامًا، وقرار الانتقال إلى الأسلوب غير الرسمي ليس بالأمر الهين.","de":"In Korea kann ein Wechsel der Verbform Nähe oder Respekt ausdrücken. Der Übergang zum lockeren Ton ist ein soziales Ereignis.","en":"In Korea, a verb ending can signal closeness or respect. Switching to casual speech is a social event, not a simple choice."},"readingMinutes":1,"sections":{"ar":[{"heading":"صيغتان لعلاقة واحدة","paragraphs":["في اللغة الكورية، تصرف الأفعال حسب الأدب والعلاقة بين المتحدث والمستمع. البانمال هو الأسلوب غير الرسمي، بينما الجوندينمال هو الأسلوب المهذب. كما أن أسلوب هايو مهذب لكنه غير رسمي، بينما هامنيدا هو الأسلوب الرسمي المستخدم في الأخبار والجيش والعروض التقديمية.","يعد الانتقال إلى البانمال حدثًا اجتماعيًا؛ إذ يجب أن يعرض أحدهم الأمر بعبارة «أوري مال نوولكايو؟» (هل ننتقل إلى الحديث غير الرسمي؟)، ورفض العرض يعني الحفاظ على مسافة. العمر يحدد الافتراضي، حتى فارق سنة واحدة عادة ما يقرر من يتحدث بشكل غير رسمي أولاً."]},{"heading":"العمر والتغيير","paragraphs":["لقد تقلصت مستويات الخطاب التاريخية، ويستخدم الكورية الحديثة نحو أربعة مستويات بشكل منتج رغم أن كتب القواعد تذكر أكثر. تختلف الأعراف الإقليمية والأجيال؛ فبعض أماكن العمل تفرض الأسلوب الرسمي بغض النظر عن العمر، بينما طبعت فرق الكيبوب والمجتمعات الإلكترونية البانمال بين الغرباء من نفس العمر تقريبًا."]}],"de":[{"heading":"Zwei Stile, eine Beziehung","paragraphs":["Koreanische Verben werden nach Höflichkeit und nach der Beziehung zwischen Sprecher und Hörer konjugiert. Banmal ist der lockere Stil, Jondaenmal der höfliche. Der Haeyo-Stil ist höflich, aber nicht formell, während Hamnida der formelle Stil ist, der in Nachrichten, beim Militär und in Präsentationen verwendet wird.","Der Wechsel zu Banmal ist ein soziales Ereignis: Jemand muss ihn mit „uri mal noeulkkayo?“ (Sollen wir zum lockeren Ton übergehen?) anbieten, und eine Ablehnung wahrt Distanz. Das Alter bestimmt den Standard, und selbst ein Jahr Unterschied entscheidet meist, wer zuerst locker spricht."]},{"heading":"Alter und Wandel","paragraphs":["Historische Sprachstufen haben sich verengt, und modernes Koreanisch verwendet etwa vier produktiv, obwohl Grammatikbücher mehr auflisten. Regionale und generationelle Normen unterscheiden sich: Manche Arbeitsplätze bestehen auf formeller Anrede unabhängig vom Alter, während K-Pop und Online-Communities Banmal zwischen Gleichaltrigen normalisiert haben."]}],"en":[{"heading":"Two styles, one relationship","paragraphs":["Korean verbs conjugate for politeness and for the relationship between speaker and listener; banmal is the casual style and jondaenmal the polite one. The haeyo style is polite but not formal, while hamnida is the formal style used in news, the army and presentations.","Switching to banmal is a social event: someone must offer it with uri mal noeulkkayo? (shall we drop the formal speech), and refusing keeps distance. Age sets the default, and even a one-year gap usually decides who speaks casually first."]},{"heading":"Age and change","paragraphs":["Historical speech levels have contracted, and modern Korean uses about four productively although grammar books list more. Regional and generational norms differ: some workplaces insist on formal style regardless of age, and K-pop and online communities have normalised banmal between strangers of similar age."]}]},"context":{"countries":["KR"],"region":"Nationwide","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Korean language","de":"Korean language","en":"Korean language"},"url":"https://en.wikipedia.org/wiki/Korean_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Korean honorifics","de":"Korean honorifics","en":"Korean honorifics"},"url":"https://en.wikipedia.org/wiki/Korean_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبان جامعيان وُلدا في نفس السنة لكن في شهرين مختلفين يتفاوضان على البانمال خلال فنجان قهوة؛ يعرض الأكبر سنًا، ويتردد الأصغر، وبعد أسبوع لا يزال القرار قيد الاختبار.","de":"Zwei Erstsemester, im selben Jahr, aber in verschiedenen Monaten geboren, verhandeln Banmal bei Kaffee; der Ältere bietet es an, der Jüngere zögert, und eine Woche später wird die Entscheidung noch getestet.","en":"Two university freshmen born in the same year but different months negotiate banmal over coffee; the older offers, the younger hesitates, and the decision is still being tested a week later."},"misunderstanding":{"ar":"قد يعتقد البعض أن استخدام البانمال مع شخص أكبر سنًا هو مجرد وقاحة، لكنه في الواقع كسر لبروتوكول اجتماعي دقيق؛ فالعرض نفسه يعبر عن الثقة، ورفضه ليس رفضًا شخصيًا بل حفاظًا على الأدب.","de":"Viele halten Banmal gegenüber Älteren für bloße Unhöflichkeit, doch es ist ein sorgfältig ausgehandelter sozialer Schritt. Das Angebot selbst zeigt Vertrauen, und eine Ablehnung ist kein persönlicher Affront, sondern wahrt den Respekt.","en":"Outsiders often mistake banmal for rudeness toward elders, but it is a carefully negotiated social step. The offer itself signals trust, and refusing it is not a personal rejection but a way to maintain respect."},"comparison":{"ar":"في كثير من اللغات الأوروبية، يختفي التمييز بين المخاطب الرسمي وغير الرسمي تدريجيًا، بينما في الكورية يظل نظامًا حيًا يعيد ترتيب العلاقات اليومية.","de":"In vielen europäischen Sprachen verschwindet die Unterscheidung zwischen formeller und informeller Anrede allmählich, während sie in Korea ein lebendiges System bleibt, das Alltagsbeziehungen ordnet.","en":"In many European languages, the distinction between formal and informal address is fading, while in Korean it remains a living system that orders everyday relationships."},"expression":{"original":"우리 말 놓을까요?","language":"한국어 (Korean)","gloss":{"ar":"هل ننتقل إلى الحديث غير الرسمي؟","de":"Sollen wir zum lockeren Ton übergehen?","en":"Shall we switch to casual speech?"},"usage":{"ar":"تستخدم عند عرض الانتقال من الأسلوب المهذب إلى البانمال، غالبًا بين الأصدقاء أو الزملاء بعد معرفة أعمارهم.","de":"Wird verwendet, um den Wechsel vom höflichen Stil zum Banmal anzubieten, oft unter Freunden oder Kollegen, nachdem die Alter geklärt sind.","en":"Used to offer a shift from polite to casual style, often among friends or colleagues after ages are known."},"transliteration":"uri mal noeulkkayo?"}},{"id":"lng-020","version":2,"slug":"mafan-ni-le-the-chinese-phrase-that-turns-a-request-into-a-debt","contentType":"note","category":"communication","title":{"ar":"عبارة صينية تحوّل الطلب إلى دين","de":"Mafan ni le: die Bitte als Schuld","en":"Mafan ni le: the request that becomes a debt"},"deck":{"ar":"في بيئات العمل الصينية، تُقال «مَفان ني له» قبل الطلب وبعده، فتسجّل جميلاً يُردّ لاحقاً عبر شبكة العلاقات.","de":"Im chinesischen Geschäftsleben wird vor und nach einer Bitte gesagt, dass man dem anderen Mühe macht – und damit eine Gegenleistung fällig.","en":"In Chinese business life, a phrase said before and after asking a favour turns a simple request into a recorded obligation owed back later."},"teaser":{"ar":"كيف تتحوّل كلمة شكر صغيرة إلى التزام متبادل يُحفظ في ذاكرة العلاقات، ويُسدَّد أحياناً بوجبة أو وسيط أو عرض عمل؟","de":"Ein kleiner Satz verwandelt einen Gefallen in eine offene Rechnung: Bezahlt wird später, oft mit einem Kontakt, einem Essen oder einem Job-Tipp.","en":"One small phrase acknowledges the other person's effort, opening a ledger of favours repaid with contacts, dinners or job leads rather than money."},"readingMinutes":1,"sections":{"ar":[{"heading":"الاعتراف بالجميل قبل الطلب","paragraphs":["عبارة «مَفان ني له» تعني حرفياً «أتعبتك»، وتُقال قبل طلب الخدمة وبعدها، اعترافاً بجهد الطرف الآخر.","هذا الاعتراف يسبق الطلب نفسه، فيمنحه صفة الجميل لا صفة الإجراء العابر، ويضع الطالب في موقع المدين منذ اللحظة الأولى.","تختلف حرارة العبارة بين الشمال والجنوب، وبين جيل وآخر، إذ يستخدمها الشباب في المدن بنبرة أخفّ وأكثر عملية."]},{"heading":"شبكة العلاقات وسداد الدين","paragraphs":["«غوانشي» تسمّي شبكة الالتزامات المتبادلة: الجميل يخلق ديناً يُسدَّد لاحقاً، غالباً بعملة مختلفة كوسيط أو وجبة أو فرصة عمل.","الرفض يُصاغ عادة بذكر الصعوبة لا بكلمة «لا»، وعبارة «وو جين ليانغ» (سأبذل قصارى جهدي) قد تكون رفضاً لطيفاً.","على «وي تشات» صار الحفاظ على العلاقات عملاً منظّماً: حزم حمراء ومجموعات وإعجابات تؤدي وظيفة التبادل منخفض الكلفة."]}],"de":[{"heading":"Dank vor der Bitte","paragraphs":["Mafan ni le bedeutet wörtlich „ich habe dir Mühe gemacht“ und wird vor und nach einer Bitte gesagt, um den Aufwand des anderen anzuerkennen.","Diese Anerkennung kommt vor der Bitte selbst und macht aus ihr kein beiläufiges Vorgehen, sondern einen Gefallen, der den Fragenden zum Schuldner macht.","Wie warm der Satz klingt, unterscheidet sich regional und zwischen Generationen; jüngere Städter verwenden ihn knapper und sachlicher."]},{"heading":"Guanxi und die Rückzahlung","paragraphs":["Guanxi bezeichnet das Netz wechselseitiger Verpflichtungen: Ein Gefallen schafft eine Schuld, die später oft in anderer Währung beglichen wird – ein Kontakt, ein Essen, eine Job-Empfehlung.","Abgelehnt wird meist durch den Hinweis auf Schwierigkeiten statt mit einem Nein; „wo jinliang“ (ich gebe mein Bestes) kann eine sanfte Absage sein.","Auf WeChat wird die Pflege von Guanxi formalisiert: rote Umschläge, Gruppenchats und Likes dienen als billige Gegengabe."]}],"en":[{"heading":"Thanks before the ask","paragraphs":["Mafan ni le means roughly “I have put you to trouble” and is said both before and after asking a favour, acknowledging the other person's effort.","Because the thanks comes first, the request lands as a favour rather than a routine transaction, and the person asking is positioned as a debtor from the start.","How warm the phrase sounds varies by region and generation; younger urban speakers use it more briefly and matter-of-factly."]},{"heading":"Guanxi and paying it back","paragraphs":["Guanxi names the network of reciprocal obligations: a favour creates a debt repaid later, often in a different currency such as a contact, a meal or a job lead.","Refusing is usually done by citing difficulty rather than saying no, and wo jinliang (I will try my best) can be a soft refusal.","On WeChat, guanxi maintenance has become formalised, with red packets, group chats and likes acting as low-cost reciprocity."]}]},"context":{"countries":["CN"],"region":"Nationwide, urban business contexts","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["communication","Nationwide, urban business contexts"],"sources":[{"organization":"Wikipedia","title":{"ar":"Guanxi","de":"Guanxi","en":"Guanxi"},"url":"https://en.wikipedia.org/wiki/Guanxi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Chinese language","de":"Chinese language","en":"Chinese language"},"url":"https://en.wikipedia.org/wiki/Chinese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","expression":{"original":"麻烦你了","language":"中文 (Mandarin Chinese)","gloss":{"ar":"كيف تتحوّل كلمة شكر صغيرة إلى التزام متبادل يُحفظ في ذاكرة العلاقات، ويُسدَّد أحياناً بوجبة أو وسيط أو عرض عمل؟","de":"Ein kleiner Satz verwandelt einen Gefallen in eine offene Rechnung: Bezahlt wird später, oft mit einem Kontakt, einem Essen oder einem Job-Tipp.","en":"One small phrase acknowledges the other person's effort, opening a ledger of favours repaid with contacts, dinners or job leads rather than money."},"usage":{"ar":"كيف تتحوّل كلمة شكر صغيرة إلى التزام متبادل يُحفظ في ذاكرة العلاقات، ويُسدَّد أحياناً بوجبة أو وسيط أو عرض عمل؟","de":"Ein kleiner Satz verwandelt einen Gefallen in eine offene Rechnung: Bezahlt wird später, oft mit einem Kontakt, einem Essen oder einem Job-Tipp.","en":"One small phrase acknowledges the other person's effort, opening a ledger of favours repaid with contacts, dinners or job leads rather than money."},"transliteration":"mafan ni le"}},{"id":"lng-021","version":2,"slug":"add-oil-the-cantonese-cheer-that-went-global","contentType":"detail","category":"languages","title":{"ar":"«أضف زيتاً»: هتاف كانتوني عالمي","de":"„Add Oil“: Der kantonesische Anfeuerungsruf","en":"Add Oil: The Cantonese Cheer That Went Global"},"deck":{"ar":"عبارة تشجيع من هونغ كونغ تحمل طاقة وإصراراً، وتنتقل من الملاعب إلى الشوارع ومن اللغة إلى لغة أخرى.","de":"Zwei Wörter, die „weiter so“ bedeuten, erobern die Welt – vom Stadion über die Schule bis in den Oxford-Duden.","en":"A two-word phrase meaning 'keep going' travels from Hong Kong stadiums to English dictionaries, carrying energy and resilience."},"teaser":{"ar":"كيف تحولت كلمتان بسيطتان تعنيان «استمر» إلى شعار عالمي يهتف به الرياضيون ويطبع على اللافتات؟","de":"Wie wurde aus einem kantonesischen Zuruf an Sportler ein globaler Ausdruck der Ermutigung, der sogar Englisch spricht?","en":"How did a Cantonese shout for athletes become a worldwide expression of encouragement, even entering the Oxford English Dictionary?"},"readingMinutes":1,"sections":{"ar":[{"heading":"من الملاعب إلى الشوارع","paragraphs":["في هونغ كونغ، يهتف الناس بعبارة «غا ياو» (加油) في الملاعب، ويكتبونها للطلاب قبل الامتحانات، ويطبعونها على اللافتات. العبارة تعني «استمر» أو «أنت تستطيع»، وهي مألوفة في الحياة اليومية.","تختلف طريقة نطق العبارة بين الكانتونية والماندرين، لكن الكتابة واحدة. في الكانتونية تُقرأ «غا ياو»، وفي الماندرين «جيايو». هذا الاختلاف يعكس تنوع اللهجات الصينية رغم وحدة الحرف.","في السنوات الأخيرة، انتقلت العبارة إلى الإنجليزية باسم «add oil»، ودخلت قاموس أوكسفورد الإنجليزي عام 2018 كتعبير من هونغ كونغ. هذا الانتقال يظهر كيف تتجاوز الكلمات حدودها المحلية."]},{"heading":"لغة تتجاوز الحروف","paragraphs":["تتميز الكانتونية بنظام نغمي كامل ومفردات قديمة، وكثير من الكلمات المنطوقة تختلف عن الماندرين حتى عندما يكون الحرف المكتوب واحداً. هذا يجعل اللغة حية ومتجددة.","في هونغ كونغ، يُكتب بالصينية الفصحى، لذا قد تُكتب الجملة الكانتونية بقواعد الماندرين ثم تُقرأ بصوت كانتوني. هذا التداخل بين الكتابة والنطق سمة مميزة للمدينة.","يختلف استخدام العبارة بين الأجيال؛ فالشباب يستخدمونها في وسائل التواصل الاجتماعي، بينما يفضل كبار السن استخدامها في السياقات التقليدية. كما تتباين دلالاتها حسب السياق السياسي."]}],"de":[{"heading":"Vom Spielfeld in den Alltag","paragraphs":["In Hongkong rufen die Menschen „ga yau“ (加油), wenn sie Athleten anfeuern, sie schreiben es Schülern vor Prüfungen und drucken es auf Banner. Die Bedeutung: „Weiter so“ oder „Du schaffst das“.","Die Schriftzeichen sind im Kantonesischen und Mandarin gleich, doch die Aussprache unterscheidet sich: „ga yau“ auf Kantonesisch, „jiayou“ auf Mandarin. Das zeigt die Vielfalt der chinesischen Sprachen trotz gemeinsamer Schrift.","In den 2010er Jahren wanderte der Ausdruck als „add oil“ ins Englische und wurde 2018 in das Oxford English Dictionary als Hongkong-Englisch aufgenommen. Ein Beispiel für sprachliche Globalisierung."]},{"heading":"Sprache jenseits der Zeichen","paragraphs":["Das Kantonesische bewahrt älteren Wortschatz und ein volles Tonsystem; viele gesprochene Wörter unterscheiden sich vom Mandarin, selbst wenn das Schriftzeichen identisch ist. So bleibt die Sprache lebendig.","In Hongkong schreibt man Standardchinesisch, daher wird ein kantonesischer Satz oft in Mandarin-Grammatik verfasst und dann kantonesisch vorgelesen. Diese Mischung prägt den Alltag.","Die Verwendung variiert regional und generationell: Jüngere nutzen den Ausdruck in sozialen Medien, Ältere in traditionellen Kontexten. Auch politische Bedeutungen können je nach Situation schwanken."]}],"en":[{"heading":"From Stadiums to Streets","paragraphs":["In Hong Kong, people shout 'ga yau' (加油) at athletes, type it to students before exams, and print it on banners. The phrase means 'keep going' or 'you can do it' and is part of everyday life.","The characters are the same in Cantonese and Mandarin, but the pronunciation differs: 'ga yau' in Cantonese, 'jiayou' in Mandarin. This reflects the diversity of Chinese languages despite a shared script.","During the 2010s, the phrase traveled into English as 'add oil' and was added to the Oxford English Dictionary in 2018 as a Hong Kong English expression. It shows how local words can go global."]},{"heading":"Language Beyond Characters","paragraphs":["Cantonese keeps older vocabulary and a full tone system; many spoken words differ from Mandarin even when the written character is identical. This makes the language vibrant and distinct.","Hong Kong writes Standard Written Chinese, so a Cantonese sentence is often written in Mandarin grammar and then read aloud in Cantonese. This interplay between writing and speech is typical of the city.","Usage varies by region and generation: younger people use the phrase on social media, while older generations use it in traditional settings. Political associations can also shift with context."]}]},"context":{"countries":["HK"],"region":"Hong Kong","continent":"asia","languages":["yue","zh","en"],"period":"contemporary"},"tags":["languages","Hong Kong"],"sources":[{"organization":"Wikipedia","title":{"ar":"Add oil","de":"Add oil","en":"Add oil"},"url":"https://en.wikipedia.org/wiki/Add_oil","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cantonese","de":"Cantonese","en":"Cantonese"},"url":"https://en.wikipedia.org/wiki/Cantonese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبة في هونغ كونغ تستعد لامتحان نهائي، فتجد ملصقاً على شكل مضخة بنزين من والدتها؛ الحروف لا تظهر، لكن الرسالة واضحة.","de":"Eine Hongkonger Studentin erhält vor der Abschlussprüfung von ihrer Mutter einen Aufkleber mit einer Zapfsäule; die Schriftzeichen fehlen, aber die Botschaft ist klar.","en":"A Hong Kong student writing a final exam receives a sticker of a petrol pump from her mother; the characters never appear, but the message is unambiguous."},"misunderstanding":{"ar":"يعتقد البعض أن العبارة مفهومة في كل الصين بنفس الطريقة، لكن النطق يختلف بين الكانتونية والماندرين، كما أن الدلالات السياسية تتغير حسب السياق.","de":"Manche glauben, der Ausdruck werde überall in China gleich verstanden, doch die Aussprache unterscheidet sich, und politische Assoziationen wandeln sich je nach Kontext.","en":"Some assume the phrase is understood the same way across China, but pronunciation differs between Cantonese and Mandarin, and political meanings change with context."},"comparison":{"ar":"بينما تُستخدم العبارة في هونغ كونغ بالكانتونية، فإن استخدامها في البر الرئيسي بالماندرين، والاقتراض الإنجليزي «add oil» يخص هونغ كونغ تحديداً.","de":"Während der Ausdruck in Hongkong kantonesisch verwendet wird, ist er auf dem Festland Mandarin; die englische Entlehnung „add oil“ ist spezifisch für Hongkong.","en":"While the phrase is used in Cantonese in Hong Kong, mainland usage is Mandarin; the English loan 'add oil' is specifically Hong Kong."},"expression":{"original":"加油","language":"廣東話 (Cantonese)","gloss":{"ar":"أضف زيتاً / استمر","de":"Öl nachfüllen / weiter so","en":"add oil / keep going"},"usage":{"ar":"تُستخدم للتشجيع في الملاعب والامتحانات، وتُهتف أو تُكتب على اللافتات.","de":"Wird zur Ermutigung bei Sport und Prüfungen gerufen oder auf Banner gedruckt.","en":"Used to encourage athletes, students, or anyone facing a challenge; often shouted or printed on banners."},"transliteration":"ga yau"}},{"id":"lng-022","version":2,"slug":"aap-tum-tu-hindi-s-three-ways-to-say-you","contentType":"note","category":"communication","title":{"ar":"آپ، تم، تو: ثلاث طرق لقول «أنت»","de":"Aap, tum, tu: Drei Arten, du zu sagen","en":"Aap, tum, tu: Hindi's Three Ways to Say You"},"deck":{"ar":"في الهند الشمالية، يحدد اختيار الضمير ما بين المتحدثين من احترام أو صداقة أو حميمية.","de":"Im Hindi-Nordindien zeigt die Wahl des Pronomens, wie nah oder wie respektvoll Menschen miteinander sprechen.","en":"In the Hindi belt, choosing a pronoun is a small daily decision about respect, friendship and closeness."},"teaser":{"ar":"ضمائر المخاطبة في الهندية ليست مجرد كلمات، بل إشارات اجتماعية دقيقة تحدد مكانة المتحدث والمستمع.","de":"Wer aap, tum oder tu sagt, entscheidet in jeder Begegnung neu über Respekt, Freundschaft und Nähe.","en":"Every conversation in Hindi asks who you are to the person you address, and the answer shapes the verb."},"readingMinutes":1,"sections":{"ar":[{"heading":"لبس الاحترام","paragraphs":["يُستخدم «آپ» للمخاطبة المهذبة ويأخذ صيغة الجمع، و«تم» للمألوف، و«تو» للحميمية أو الإهانة حسب السياق والنبرة.","تلحق أداة الاحترام «جي» بالأسماء والأجوبة، فيُقال «غاندي جي» و«هان جي» أي نعم يا سيدي أو يا سيدتي.","قد يستخدم الوالد «تم» مع طفله بينما يلزم الطفل باستخدام «آپ» مع والده، فالضمير يدل على اتجاه الاحترام لا على المسافة."]},{"heading":"الضمير في العمل","paragraphs":["تتبع الأفعال الصيغة المختارة: «آپ كايسي هين؟» و«تم كايسي هو؟» سؤال واحد في مستويين اجتماعيين مختلفين.","في مكاتب شمال الهند، قد يخلق «آپ» بين المتساويين مسافة، فيتحول الزملاء عمداً إلى «تم» للتعبير عن الصداقة.","يتغير الاستخدام بحسب المنطقة والجنس والجيل؛ فمتحدثو البهوجبورية والأوادية يستخدمون ضمائر مختلفة، والهندية في مومباي ممزوجة بالماراثية والإنجليزية."]}],"de":[{"heading":"Respekt als Richtung","paragraphs":["Aap ist das höfliche Du und nimmt Pluralformen an, tum ist vertraut, tu ist intim oder je nach Ton und Situation beleidigend.","Die Respektpartikel ji hängt an Namen und Antworten: Gandhi ji, haan ji, also ja, Sir oder Madam, Namaste ji.","Eltern können zum Kind tum sagen, während das Kind den Eltern aap schuldet; das Pronomen zeigt die Richtung des Respekts, nicht die Distanz."]},{"heading":"Wechsel im Büro","paragraphs":["Die Verben richten sich nach der gewählten Form: aap kaise hain? und tum kaise ho? sind dieselbe Frage in zwei sozialen Registern.","In nordindischen Büros kann aap unter Gleichgestellten Distanz schaffen, und Kollegen wechseln bewusst zu tum, um Freundschaft zu signalisieren.","Der Gebrauch variiert nach Region, Geschlecht und Generation; Bhojpuri- und Awadhi-Sprecher nutzen andere Pronomen, und Hindi in Mumbai ist stark mit Marathi und Englisch gemischt."]}],"en":[{"heading":"Respect Has a Direction","paragraphs":["Aap is the respectful you and takes plural agreement, tum is familiar, and tu is intimate or insulting depending on context and tone.","The respect particle ji attaches to names and answers: Gandhi ji, haan ji (yes, sir or madam), Namaste ji.","A parent may use tum with a child while the child must use aap with the parent, so the pronoun indexes direction of respect rather than distance."]},{"heading":"Switching in the Office","paragraphs":["Verbs agree with the chosen form: aap kaise hain? versus tum kaise ho? are the same question in two social registers.","In north Indian offices, aap between equals can create distance, and colleagues deliberately switch to tum to signal friendship.","Usage varies by region, gender and generation; Bhojpuri and Awadhi speakers use different pronouns, and Hindi as spoken in Mumbai is heavily mixed with Marathi and English."]}]},"context":{"countries":["IN"],"region":"Hindi belt: Delhi, Uttar Pradesh, Bihar, Madhya Pradesh","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["communication","Hindi belt: Delhi, Uttar Pradesh, Bihar, Madhya Pradesh"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hindi","de":"Hindi","en":"Hindi"},"url":"https://en.wikipedia.org/wiki/Hindi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظفة متدربة في دلهي تخاطب مديرها بـ«آپ» شهرين، ثم تقول «تم» عن غير قصد؛ يضحك الاثنان، ويفهم المدير ذلك كتحول في العلاقة لا كزلة.","de":"Eine Praktikantin in Delhi spricht ihre Vorgesetzte zwei Monate mit aap an, sagt dann versehentlich tum; beide lachen, und die Vorgesetzte liest es als Bewegung in der Beziehung, nicht als Fehler.","en":"A Delhi intern addresses her manager with aap for two months, then says tum by accident; both laugh, and the manager reads it as the relationship moving rather than as a slip."},"misunderstanding":{"ar":"قد يظن الغريب أن «تو» إهانة دائماً، لكنها بين الأصدقاء المقربين أو الأهل تعبير عن حميمية، والنبرة هي الفيصل.","de":"Auswärtige halten tu oft für eine Beleidigung, doch unter engen Freunden oder Verwandten drückt es Nähe aus; der Ton entscheidet.","en":"Outsiders often hear tu as an insult, but among close friends or relatives it signals intimacy; tone decides, not the word alone."},"comparison":{"ar":"يشبه الأمر اختيار «أنت» و«حضرتك» في العربية، لكن الهندية تجعل الفعل نفسه يتغير مع الضمير، فيصبح الاختيار مرئياً في كل جملة.","de":"Ähnlich wie du und Sie im Deutschen, doch im Hindi verändert sich mit dem Pronomen auch das Verb, sodass die Wahl in jedem Satz sichtbar wird.","en":"English has one you, so Hindi speakers must decide each time; the choice is visible in the verb, which changes with the pronoun."},"expression":{"original":"आप कैसे हैं?","language":"हिन्दी (Hindi)","gloss":{"ar":"كيف حالك؟ (بصيغة الاحترام)","de":"Wie geht es Ihnen? (höflich)","en":"How are you? (respectful)"},"usage":{"ar":"تُقال للغرباء وكبار السن والرؤساء في العمل، وتأخذ الفعل صيغة الجمع.","de":"An Fremde, Ältere und Vorgesetzte gerichtet, mit Verb in der Pluralform.","en":"Said to strangers, elders and managers, with the verb in its plural form."},"transliteration":"aap kaise hain?"}},{"id":"lng-023","version":2,"slug":"jugaad-the-hindi-word-for-the-workaround-that-becomes-a-business-model","contentType":"detail","category":"languages","title":{"ar":"جوگاد: كلمة هندية للحلول المؤقتة","de":"Jugaad: Hindi-Wort für die Notlösung","en":"Jugaad: The Hindi Word for Workarounds"},"deck":{"ar":"من محرك دراجة نارية على عربة إلى نظرية في الابتكار، تحمل الكلمة وجهين: ذكاءً وإبداعًا، وتجاوزًا للجودة.","de":"Vom Motorradmotor auf einem Karren zur Managementtheorie: Das Wort lobt Einfallsreichtum und kritisiert Pfusch zugleich.","en":"From a motorbike engine on a cart to a management theory, the term praises resourcefulness and criticizes cutting corners."},"teaser":{"ar":"كلمة واحدة تصف محركًا على عربة، وتصبح نظرية إدارة، وقد تكون إهانة. رحلة جوگاد في شمال الهند.","de":"Ein Wort beschreibt einen Motor auf einem Karren, wird zur Managementtheorie und kann eine Beleidigung sein. Jugaad in Nordindien.","en":"One word describes a motorbike engine strapped to a cart, becomes a business theory, and can be an insult. Jugaad in North India."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه جوگاد","paragraphs":["تشير كلمة جوگاد إلى حل مؤقت منخفض التكلفة: محرك دراجة نارية يُربط بعربة، أو مبرد سطح يُعاد بناؤه من ثلاجة. إنه حل يعمل مرة واحدة، وغالبًا لا يُصمم ليدوم. تظهر الكلمة في البنجابية والهندية، وأصلها محل جدل بين المتحدثين وعلماء اللغة."]},{"heading":"بين المديح والانتقاد","paragraphs":["بعد وصف سيارات رخيصة وآلات غسيل كلى بهذه الكلمة، حوّلها كتاب الإدارة إلى نظرية للابتكار المقتصد. لكن للكلمة حدّان: مدح للبراعة وانتقاد لتجاوز الجودة، فوصف منتج بأنه جوگاد قد يكون إهانة.","العربة الآلية المؤقتة، وتسمى أيضًا جوگاد، محظورة على многих الطرق الهندية لأسباب تتعلق بالسلامة، وهذا يجسد التوتر بدقة. يختلف استخدام المصطلح حسب المنطقة والجيل؛ فالشباب في المدن الكبرى يستخدمونه بازدراء ساخر أحيانًا."]}],"de":[{"heading":"Was Jugaad bedeutet","paragraphs":["Jugaad bezeichnet eine kostengünstige Improvisation: ein Motorradmotor auf einem Karren, ein Dachkühler aus einem Kühlschrank, eine Lösung, die einmal funktioniert. Das Wort kommt im Punjabi und Hindi vor, sein Ursprung ist unter Sprechern und Lexikografen umstritten."]},{"heading":"Zwischen Lob und Kritik","paragraphs":["Nachdem billige Autos und Dialysegeräte damit beschrieben wurden, machten Managementautoren Jugaad zu einer Theorie frugaler Innovation. Es hat eine Doppelschneide: Lob für Findigkeit und Kritik am Pfusch, sodass ein Produkt als Jugaad zu bezeichnen ein Beleidigung sein kann.","Der behelfsmäßige Motorwagen, ebenfalls Jugaad genannt, ist auf vielen indischen Straßen aus Sicherheitsgründen verboten – das fängt die Spannung genau ein. Der Gebrauch variiert regional und generationell; Stadtjugendliche verwenden das Wort oft ironisch für Korruption oder schlampige Arbeit."]}],"en":[{"heading":"What Jugaad Means","paragraphs":["Jugaad names a low-cost improvisation: a motorbike engine strapped to a cart, a rooftop cooler rebuilt from a fridge, a workaround that works once. The word appears in Punjabi and Hindi, and its origin is debated among speakers and lexicographers."]},{"heading":"Praise and Criticism","paragraphs":["Management writers turned jugaad into a theory of frugal innovation after cheap cars and dialysis machines were described with it. It carries a double edge: praise for resourcefulness and criticism for cutting corners, so calling a product jugaad can be an insult.","The makeshift motorised cart also called a jugaad is banned on many Indian roads for safety reasons, which captures the tension exactly. Usage varies by region and generation; middle-class Indians often use jugaad ironically about corruption or shoddy work."]}]},"context":{"countries":["IN"],"region":"North India, especially Punjab, Haryana and Delhi","continent":"asia","languages":["hi","en","pa"],"period":"contemporary"},"tags":["languages","North India, especially Punjab, Haryana and Delhi"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jugaad","de":"Jugaad","en":"Jugaad"},"url":"https://en.wikipedia.org/wiki/Jugaad","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hindi","de":"Hindi","en":"Hindi"},"url":"https://en.wikipedia.org/wiki/Hindi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مزارع من راجستان يبني مضخة ري من محرك ديزل وإطار دراجة ومبرد سيارة؛ تسقي حقلين لموسم واحد ولا تُصلح أبدًا، لأنها لم تُصمم لتدوم.","de":"Ein Bauer aus Rajasthan baut eine Bewässerungspumpe aus einem Dieselmotor, einem Fahrradrahmen und einem Autokühler; sie bewässert zwei Felder für eine Saison und wird nie repariert, weil sie nie dafür gedacht war.","en":"A Rajasthan farmer builds an irrigation pump from a diesel engine, a bicycle frame and a car radiator; it waters two fields for a season and is never repaired, because it was never designed to be."},"misunderstanding":{"ar":"يظن البعض أن جوگاد تعني الغش أو الخداع، لكنها في الأصل تشير إلى البراعة في استخدام الموارد المحدودة. ومع ذلك، يمكن أن تحمل دلالة سلبية عندما تُستخدم لوصف منتج رديء.","de":"Manche halten Jugaad für Betrug, doch ursprünglich meint es Einfallsreichtum mit begrenzten Mitteln. Allerdings kann es negativ klingen, wenn es ein minderwertiges Produkt beschreibt.","en":"Some think jugaad means cheating or deception, but it originally refers to resourcefulness with limited means. However, it can carry a negative connotation when describing a shoddy product."},"comparison":{"ar":"في التاميلية والبنغالية والماراثية كلمات مختلفة للتعبير عن الارتجال، لكن جوگاد اكتسبت شهرة عالمية بفضل كتابات الإدارة.","de":"Im Tamil, Bengalischen und Marathi gibt es andere Wörter für Improvisation, aber Jugaad wurde durch Managementliteratur weltweit bekannt.","en":"Tamil, Bengali and Marathi have different words for improvisation, but jugaad gained global fame through management writing."},"expression":{"original":"जुगाड़","language":"हिन्दी (Hindi)","gloss":{"ar":"حل مؤقت / اختراع مبتكر","de":"improvisierte Notlösung / Hack","en":"improvised workaround / hack"},"usage":{"ar":"تستخدم لوصف حلول مبتكرة منخفضة التكلفة، وقد تكون مدحًا أو ذمًا حسب السياق.","de":"Wird für kostengünstige, kreative Lösungen verwendet und kann je nach Kontext lobend oder abwertend sein.","en":"Used for low-cost, creative solutions; can be praise or criticism depending on context."},"transliteration":"jugaad"}},{"id":"lng-024","version":2,"slug":"hinglish-switching-languages-mid-sentence-as-the-normal-way-to-speak","contentType":"language","category":"languages","title":{"ar":"هينغليش: التبديل بين اللغات في منتصف الجملة","de":"Hinglish: Sprachwechsel mitten im Satz","en":"Hinglish: Switching Languages Mid-Sentence"},"deck":{"ar":"في المدن الهندية، يمزج المتحدثون بين الهندية والإنجليزية كأمر طبيعي، خاصة في دلهي ومومباي وبنغالورو.","de":"In indischen Städten wechseln Menschen zwischen Hindi und Englisch, als wäre es die normalste Sache der Welt.","en":"In urban India, speakers blend Hindi and English as the normal way to talk, especially in Delhi, Mumbai and Bengaluru."},"teaser":{"ar":"هينغليش ليس مجرد مزج عشوائي، بل طريقة حياة لغوية تعكس الطبقة والتعليم والانتماء المحلي.","de":"Hinglish ist kein willkürliches Gemisch, sondern ein fester Sprachmodus, der Klasse, Bildung und lokale Zugehörigkeit zeigt.","en":"Hinglish is not random mixing but a structured register that signals class, education and local belonging."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يعمل الهينغليش في الحياة اليومية","paragraphs":["يمزج الهينغليش بين قواعد الهندية والمفردات الإنجليزية، كما في جملة 'ميرا فون خراب هو غيا هاي' (هاتفي تعطل). وهو السجل الافتراضي في الإعلانات الحضرية.","يحدث التبديل عند حدود الجمل، حيث ينتقل المتحدثون بين السرد والمحتوى التقني بتغيير اللغة. هذا التبديل ليس عشوائياً بل منظم."]},{"heading":"الطبقة والانتماء في لغة مختلطة","paragraphs":["الهينغليش مرتبط بالطبقة: فالهينغليش المثقل بالإنجليزية يشير إلى التعليم، بينما يشير الخطاب المثقل بالهندية إلى الانتماء المحلي. منذ التسعينيات، استخدمت أفلام بوليوود هذا المزيج، وتقدم منصات البث ترجمة له كتنوع لغوي قائم بذاته. ومع ذلك، يراقب الآباء والمعلمون الهندية أو الإنجليزية الخالصة رغم أن السجل المختلط هو ما يستخدمه معظم سكان المدن. يتغير هذا المزيج إقليمياً وجيلياً، إذ يضم خلط بنغالورو عناصر من الكانادية، وتختلف أنماط الماراثية-الإنجليزية والتاميلية-الإنجليزية."]}],"de":[{"heading":"Wie Hinglish im Alltag funktioniert","paragraphs":["Hinglish kombiniert Hindi-Grammatik mit englischem Wortschatz, wie in 'mera phone kharab ho gaya hai' (mein Handy ist kaputt). In der städtischen Werbung ist es der Standard.","Der Wechsel erfolgt an Satzgrenzen: Sprecher wechseln zwischen erzählenden und technischen Inhalten, indem sie die Sprache ändern. Das ist nicht zufällig, sondern systematisch."]},{"heading":"Klasse und Zugehörigkeit in einer gemischten Sprache","paragraphs":["Hinglish ist klassenmarkiert: Englischlastiges Hinglish signalisiert Bildung, Hindi-lastige Rede lokale Zugehörigkeit. Seit den 1990er Jahren nutzen Bollywood-Drehbücher Hinglish, und Streaming-Plattformen untertiteln es als eigenständige Varietät. Eltern und Lehrer bestehen dennoch auf reinem Hindi oder Englisch, obwohl die meisten Stadtbewohner den gemischten Register verwenden. Regional und generationell variiert das Mischen: In Bengaluru kommen Kannada-Elemente hinzu, und Marathi-Englisch sowie Tamil-Englisch folgen eigenen Mustern."]}],"en":[{"heading":"How Hinglish Works in Daily Life","paragraphs":["Hinglish mixes Hindi grammar with English vocabulary, as in 'mera phone kharab ho gaya hai' (my phone has stopped working). It is the default register in urban advertising.","Switching happens at clause boundaries: speakers move between narrative and technical content by changing language. This is not random but systematic."]},{"heading":"Class and Belonging in a Mixed Language","paragraphs":["Hinglish is class-marked: English-heavy Hinglish signals education, while Hindi-heavy speech signals local belonging. Since the 1990s, Bollywood scripts have used Hinglish, and streaming platforms now subtitle it as a variety in its own right. Yet parents and teachers police pure Hindi or pure English even though the mixed register is what most urban speakers actually use. The mixing varies regionally and generationally: Bengaluru's version includes Kannada, and Marathi-English and Tamil-English patterns differ."]}]},"context":{"countries":["IN"],"region":"Urban India, especially Delhi, Mumbai and Bengaluru","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["languages","Urban India, especially Delhi, Mumbai and Bengaluru"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hinglish","de":"Hinglish","en":"Hinglish"},"url":"https://en.wikipedia.org/wiki/Hinglish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Code-switching","de":"Code-switching","en":"Code-switching"},"url":"https://en.wikipedia.org/wiki/Code-switching","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عامل في مركز اتصالات في مومباي يحيي عميلاً بالإنجليزية، ويشرح الفاتورة بالهندية، ثم يعود إلى الإنجليزية لرقم الشكوى؛ لا يلاحظ العميل ذلك لأن الهينغليش هو السجل المتوقع.","de":"Ein Callcenter-Mitarbeiter in Mumbai begrüßt einen Kunden auf Englisch, erklärt die Rechnung auf Hindi und wechselt für die Beschwerdenummer zurück ins Englische; der Kunde merkt nichts, weil Hinglish der erwartete Register ist.","en":"A Mumbai call-centre worker greets a customer in English, explains the bill in Hindi and switches back to English for the complaint number; the customer never notices, because Hinglish is the expected register."},"misunderstanding":{"ar":"يُفهم الهينغليش أحياناً كعلامة على ضعف إتقان إحدى اللغتين، لكنه في الواقع سجل كامل ومنظم.","de":"Hinglish wird oft als Zeichen mangelnder Sprachbeherrschung missverstanden, ist aber ein vollwertiger, regelhafter Register.","en":"Hinglish is often mistaken for poor command of either language, but it is a full, rule-governed register."},"comparison":{"ar":"على عكس اللغات الهجينة الأخرى، فإن الهينغليش ليس مجرد مفردات مستعارة، بل نظام تبديل كامل عند حدود الجمل.","de":"Anders als andere Mischsprachen ist Hinglish nicht nur Entlehnung von Wörtern, sondern ein systematischer Wechsel an Satzgrenzen.","en":"Unlike other hybrid languages, Hinglish is not just loanwords but a systematic switch at clause boundaries."},"expression":{"original":"मेरा फ़ोन ख़राब हो गया है","language":"Hinglish","gloss":{"ar":"هاتفي تعطل","de":"mein Handy ist kaputt","en":"my phone has stopped working"},"usage":{"ar":"تعبير يومي شائع في المدن الهندية عند الحديث عن عطل تقني.","de":"Alltäglicher Ausdruck in indischen Städten, wenn ein Gerät nicht funktioniert.","en":"Everyday expression in urban India when a device fails."},"transliteration":"mera phone kharab ho gaya hai"}},{"id":"lng-026","version":2,"slug":"apni-tumi-tui-bengali-s-three-doors-into-you","contentType":"note","category":"languages","title":{"ar":"ثلاثة أبواب بنغالية إلى \"أنت\"","de":"Drei Türen zum Du im Bengalischen","en":"Bengali's three doors into you"},"deck":{"ar":"في البنغالية يختار المتحدث مستوى الخطاب حسب الشخص، فالفعل نفسه يحمل توقيع العلاقة.","de":"Im Bengalischen wählt man die Anrede nach Beziehung, und das Verb trägt die Unterschrift der Beziehung.","en":"Bengali marks the addressee on the verb at three social levels, so the same question can sound formal, familiar or intimate."},"teaser":{"ar":"من apni الرسمية إلى tui الحميمة، تفتح البنغالية ثلاثة أبواب للضمير نفسه، ولكل باب نبرته الاجتماعية.","de":"Von formellem apni bis vertrautem tui öffnet das Bengalische drei Türen zum selben Du, jede mit eigenem sozialen Ton.","en":"From formal apni to intimate tui, Bengali opens three doors into the same \"you\", and each door carries its own social weight."},"readingMinutes":1,"sections":{"ar":[{"heading":"فعل واحد بثلاث نبرات","paragraphs":["تضع البنغالية المخاطَب على الفعل في ثلاثة مستويات: apni الرسمية، وtumi المألوفة، وtui الحميمة أو المحتقرة. يتغيّر الفعل مع كل مستوى، فالسؤال نفسه يُطرح بثلاث نبرات اجتماعية مختلفة.","استخدام tui مع غريب استفزاز، ومع صديق قريب دفء؛ الكلمة نفسها تفعل فعلين متعاكسين."]},{"heading":"من يحصل على أي باب","paragraphs":["ينال الكبار apni حتى من أقاربهم البالغين، والأزواج يستخدمون عادة tumi، وقد يتحول الآباء إلى tui حين يغضبون. هذا النمط الثلاثي مشترك مع الهندية وغيرها من اللغات الهندوآرية، لكن البنغالية تجعل المستويات الثلاثة نحويّة بصيغ فعل متمايزة. ويختلف الاستخدام بين دكا وكلكتا وبين الأجيال، فالمهاجرون يفقدون tui غالباً إلا في المزاح."]}],"de":[{"heading":"Ein Verb, drei soziale Tonlagen","paragraphs":["Das Bengalische markiert den Angesprochenen am Verb auf drei Stufen: apni (formell), tumi (vertraut) und tui (innig oder verächtlich). Das Verb ändert sich mit jeder Stufe, dieselbe Frage erklingt in drei sozialen Tonarten.","Tui zu einem Fremden ist eine Provokation, tui zu einem engen Freund Wärme; dasselbe Wort wirkt entgegengesetzt."]},{"heading":"Wer welche Tür bekommt","paragraphs":["Ältere erhalten apni selbst von erwachsenen Verwandten, Ehepartner verwenden meist tumi, Eltern wechseln im Zorn zuweilen zu tui. Das dreistufige Muster teilt das Bengalische mit dem Hindi und anderen indoarischen Sprachen, doch nur hier sind alle drei Stufen durch eigene Verbendungen grammatisch. Der Gebrauch unterscheidet sich zwischen Dhaka und Kolkata sowie zwischen Generationen; in der Diaspora geht tui oft verloren, außer im Scherz."]}],"en":[{"heading":"One verb, three social keys","paragraphs":["Bengali marks the addressee on the verb at three levels: apni (formal), tumi (familiar) and tui (intimate or contemptuous). The verb changes with each, so apni kemon achen?, tumi kemon acho? and tui kemon achis? ask the same question in three social keys.","Using tui with a stranger is a provocation, while using it with a close friend is warmth; the same word does opposite work."]},{"heading":"Who gets which door","paragraphs":["Elders receive apni even from adult relatives, spouses usually use tumi, and parents may switch to tui when angry. The three-way pattern is shared with Hindi and other Indo-Aryan languages, but Bengali makes all three levels grammatical through distinct verb endings. Usage differs between Dhaka and Kolkata and across generations: Bangladeshi Bengali uses apni more broadly, and diaspora families often lose tui except in jokes."]}]},"context":{"countries":["BD","IN"],"region":"Bengal (Dhaka and Kolkata)","continent":"asia","languages":["bn","en"],"period":"contemporary"},"tags":["languages","Bengal (Dhaka and Kolkata)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bengali language","de":"Bengali language","en":"Bengali language"},"url":"https://en.wikipedia.org/wiki/Bengali_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bengalis","de":"Bengalis","en":"Bengalis"},"url":"https://en.wikipedia.org/wiki/Bengalis","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","expression":{"original":"আপনি কেমন আছেন?","language":"বাংলা (Bengali)","gloss":{"ar":"من apni الرسمية إلى tui الحميمة، تفتح البنغالية ثلاثة أبواب للضمير نفسه، ولكل باب نبرته الاجتماعية.","de":"Von formellem apni bis vertrautem tui öffnet das Bengalische drei Türen zum selben Du, jede mit eigenem sozialen Ton.","en":"From formal apni to intimate tui, Bengali opens three doors into the same \"you\", and each door carries its own social weight."},"usage":{"ar":"من apni الرسمية إلى tui الحميمة، تفتح البنغالية ثلاثة أبواب للضمير نفسه، ولكل باب نبرته الاجتماعية.","de":"Von formellem apni bis vertrautem tui öffnet das Bengalische drei Türen zum selben Du, jede mit eigenem sozialen Ton.","en":"From formal apni to intimate tui, Bengali opens three doors into the same \"you\", and each door carries its own social weight."},"transliteration":"apni kemon achen?"}},{"id":"lng-027","version":2,"slug":"tamil-s-two-registers-the-written-sentence-nobody-says-aloud","contentType":"note","category":"languages","title":{"ar":"التاميلية: لغتان في لسان واحد","de":"Tamilisch: zwei Register, ein Alltag","en":"Tamil's two registers nobody says aloud"},"deck":{"ar":"في تاميل نادو وبودوتشيري وشمال سريلانكا، يكتب الناس جملة لا ينطقونها أبداً بصوت عالٍ.","de":"In Tamil Nadu, Puducherry und Nord-Sri Lanka schreiben Menschen Sätze, die sie nie laut aussprechen.","en":"Across Tamil Nadu, Puducherry and northern Sri Lanka, people write sentences they never speak out loud."},"teaser":{"ar":"التاميلية تفصل بحدّة بين المكتوب والمنطوق، حتى إن الفعل نفسه يتغيّر شكله كلياً بين السطر والصوت.","de":"Tamilisch trennt scharf zwischen Schrift und gesprochener Sprache – sogar das Verb wechselt dabei seine ganze Form.","en":"Tamil splits sharply between written and spoken forms, so the same verb changes shape entirely between page and voice."},"readingMinutes":1,"sections":{"ar":[{"heading":"جملة لا تُقال","paragraphs":["في التاميلية انشقاق واضح بين اللغة الأدبية والمنطوقة، يظهر في نهايات الأفعال والضمائر والمفردات. جملة مكتوبة مثل «نان فاروغيرين» أي «أنا آتٍ» تُقال في الكلام «نان فارّين»، بنهاية فعل مختلفة تماماً.","هذا الانشقاق قديم، تفصل بين شعر عصر سنغم والكلام الحديث ألفا سنة من التغيّر، وقد حاولت حركات سياسية مراراً تنقية الشكل المكتوب. والاختلاف يتفاوت أيضاً بين الأجيال والمناطق: تلاميذ المدارس في الشتات يتعلّمون الأدبي ويقرأون تاميلية غير التي يتكلمونها في البيت."]},{"heading":"بين النشرة والحوار","paragraphs":["مذيعو الأخبار والسينما يقفون في نقاط مختلفة على هذا المقياس: النشرات تستخدم التاميلية الأدبية، والحوار يستخدم المنطوقة، والجمهور يقبل الاثنتين بوصفهما تاميلية.","التاميلية السريلانكية والهندية متقاربتان في الكتابة لكنهما تختلفان في مفردات الكلام ونبرته. ومع ذلك يبقى الفهم ممكناً، لأن الكاتب والقارئ يتقاسمان معرفة بالمقياسين."]}],"de":[{"heading":"Der Satz, der stumm bleibt","paragraphs":["Tamilisch hat eine deutliche Diglossie: Schriftsprache und gesprochene Sprache unterscheiden sich in Verbendungen, Pronomen und Wortschatz. Ein geschriebener Satz wie „nan varugiren“ (ich komme) wird gesprochen zu „nan varren“ – mit einer völlig anderen Verbendung.","Die Spaltung ist alt: Zwischen der Sangam-Dichtung und heutiger Rede liegen zwei Jahrtausende Wandel, und politische Bewegungen versuchten wiederholt, die Schriftform zu reinigen. Auch regional und zwischen Generationen variiert das Verhältnis: Kinder in Diaspora-Schulen lernen die Schriftform und sprechen zu Hause ein anderes Tamilisch."]},{"heading":"Zwischen Nachricht und Dialog","paragraphs":["Nachrichtensprecher und Filme stehen an verschiedenen Punkten dieser Skala: Bulletins nutzen literarisches Tamilisch, Dialoge das gesprochene, und das Publikum akzeptiert beides als Tamilisch.","Sri-lankisches und indisches Tamilisch sind in der Schrift nah verwandt, unterscheiden sich aber im gesprochenen Wortschatz und in der Intonation. Verständigung bleibt möglich, weil beide Seiten das Nebeneinander der Register kennen."]}],"en":[{"heading":"The sentence left unsaid","paragraphs":["Tamil has a sharp diglossia, and literary Tamil differs from spoken Tamil in verb endings, pronouns and vocabulary. A written sentence such as nan varugiren (I am coming) is spoken as nan varren, with a different verb ending entirely.","The split is old: Sangam-era poetry and modern speech are separated by two millennia of change, and political movements have repeatedly tried to purify the written form. The balance also shifts by region and generation, and diaspora schools teach the literary form, so children speak one Tamil and read another."]},{"heading":"Between bulletin and dialogue","paragraphs":["Newsreaders and films occupy different points on the scale: bulletins use literary Tamil, dialogue uses spoken Tamil, and audiences accept both as Tamil.","Sri Lankan Tamil and Indian Tamil are close in writing but differ in spoken vocabulary and intonation. Understanding holds because writer and reader share knowledge of both registers."]}]},"context":{"countries":["IN","LK"],"region":"Tamil Nadu, Puducherry and northern Sri Lanka","continent":"asia","languages":["ta","en"],"period":"contemporary"},"tags":["languages","Tamil Nadu, Puducherry and northern Sri Lanka"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tamil language","de":"Tamil language","en":"Tamil language"},"url":"https://en.wikipedia.org/wiki/Tamil_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Diglossia","de":"Diglossia","en":"Diglossia"},"url":"https://en.wikipedia.org/wiki/Diglossia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبة في تشيناي تكتب رسالة إلى جدّتها بالتاميلية الأدبية، ثم تهاتفها بالتاميلية المنطوقة؛ الخبر نفسه يتّخذ شكلين لأنها لا تنطق الصيغ المكتوبة أبداً.","de":"Eine Studentin in Chennai schreibt ihrer Großmutter einen Brief in literarischem Tamilisch und ruft sie danach in gesprochenem Tamilisch an; dieselbe Nachricht hat zwei Gestalten, weil sie die Schriftformen nie laut sagt.","en":"A Chennai student writes a letter to her grandmother in literary Tamil and then phones her in spoken Tamil; the same news takes two shapes because she never says the written forms aloud."},"misunderstanding":{"ar":"كثيرون يظنون أن المنطوقة مجرد أدبية مبتسرة أو مهملة، لكنها نظام كامل بقواعده ونهاياته الخاصة.","de":"Viele halten das Gesprochene für nachlässiges, verkürztes Schriftsprachliches – dabei ist es ein eigenes System mit festen Endungen.","en":"Many assume spoken Tamil is merely careless or shortened literary Tamil, but it is a full system with its own endings and rules."},"comparison":{"ar":"كما تختلف الفصحى والعامية في العربية، تختلف التاميلية الأدبية والمنطوقة، لكن الفارق في الأفعال أشدّ وضوحاً.","de":"Ähnlich wie Hocharabisch und Dialekt stehen hier zwei Register nebeneinander, doch die Verbformen weichen stärker voneinander ab.","en":"Like formal and colloquial Arabic, the two registers coexist, though Tamil's verb forms diverge more visibly."},"expression":{"original":"நான் வருகிறேன்","language":"தமிழ் (Tamil)","gloss":{"ar":"أنا آتٍ (الصيغة الأدبية)","de":"ich komme (literarische Form)","en":"I am coming (literary form)"},"usage":{"ar":"تُكتب في الرسائل والنشرات، ولا تُقال في الحديث اليومي.","de":"Erscheint in Briefen und Nachrichten, wird im Alltag nicht gesprochen.","en":"Written in letters and news copy; never spoken in everyday conversation."},"transliteration":"nan varugiren"}},{"id":"lng-028","version":2,"slug":"kreng-jai-the-thai-reluctance-that-keeps-everyone-s-options-open","contentType":"note","category":"communication","title":{"ar":"كْرينغ جاي: أدب يترك الباب مفتوحاً","de":"Kreng jai: Rücksicht, die Türen offen lässt","en":"Kreng jai: the Thai art of not imposing"},"deck":{"ar":"في تايلاند، كثيراً ما يُفضَّل ألا تطلب ما تريد على أن تضع الآخر في موقف الرفض.","de":"In Thailand wird oft lieber nicht gesagt, was man will, damit niemand ablehnen muss.","en":"In Thailand people often avoid saying what they want so that no one has to refuse them."},"teaser":{"ar":"كْرينغ جاي ليس خجلاً بل مهارة اجتماعية: لا تطلب توصيلة، ولا تُنهِ الطبق الأخير، وتترك للآخر مساحة كي لا يضطر إلى قول لا.","de":"Kreng jai ist keine Schüchternheit, sondern soziale Fertigkeit: keine Mitfahrgelegenheit erbitten, das letzte Gericht stehen lassen, dem anderen die Wahl lassen.","en":"Kreng jai is not shyness but a social skill: don't ask for a lift, don't take the last dish, leave the other person room to say no."},"readingMinutes":1,"sections":{"ar":[{"heading":"صغائر تحمي العلاقات","paragraphs":["كْرينغ جاي يعني ألا تُثقل على غيرك: لا تطلب توصيلة بالسيارة، ولا تأكل آخر طبق، ولا تصرّح بما تريد حتى لا يضطر الآخر إلى الرفض.","يظهر ذلك في رفض صغير: يُرفَض الطبق الإضافي ثم يُقبَل، ويُعرض على الضيف أكثر من مرة قبل أن يوافق.","هذا السلوك يتحرك صعوداً ونزولاً، لكن يُنتظر من الأصغر أن يُظهره أكثر، فيصير تقييم العمل غير مباشر."]},{"heading":"الرفض بلطف والاحترام في النبرة","paragraphs":["قد تُسمَع كلمة «لا» المباشرة كأنها هجوم، لذلك يُبنى الرفض على عبارة مثل «غير مريح كثيراً» أو على تأجيل صامت.","نظام أدوات اللباقة يحمل المكانة: تُنهى الجمل المهذبة بـ«خراب» للرجل وبـ«خا» للمرأة.","يختلف ذلك بين الأجيال والمناطق: سكان المدن العاملون في شركات التقنية والدولية قد يفضّلون المباشرة، كما تختلف عادات التايلانديين من أصل صيني ومجتمعات المسلمين في الجنوب."]}],"de":[{"heading":"Kleine Gesten, die Beziehungen schonen","paragraphs":["Kreng jai bedeutet, niemandem zur Last zu fallen: nicht nach einer Mitfahrgelegenheit fragen, das letzte Gericht nicht nehmen, nicht sagen, was man will, damit der andere nicht ablehnen muss.","Es zeigt sich in kleinen Ablehnungen: Eine zweite Portion wird erst zurückgewiesen und dann angenommen, und Gastgeber bieten mehr als einmal an.","Die Norm wirkt nach oben und unten, doch Jüngere sollen sie stärker zeigen, weshalb Rückmeldungen am Arbeitsplatz indirekt ausfallen."]},{"heading":"Sanftes Nein und Höflichkeitspartikel","paragraphs":["Ein direktes Nein kann wie ein Angriff klingen, deshalb wird die Ablehnung als „nicht sehr günstig“ formuliert oder als stilles Zögern.","Das Partikelsystem trägt Status: Höfliche Sätze enden bei Männern auf khrap, bei Frauen auf kha.","Das variiert regional und zwischen Generationen: Stadtbewohner in Tech- und internationalen Firmen schätzen oft Direktheit, ebenso unterscheiden sich chinesisch-thailändische und muslimische Gemeinschaften im Süden."]}],"en":[{"heading":"Small refusals that protect the relationship","paragraphs":["Kreng jai describes not imposing: not asking for a lift, not finishing the last dish, not saying what you want so the other person need not refuse.","It is enacted in small refusals, where a second helping is declined before being accepted and a host offers more than once.","The norm works upward and downward, but juniors are expected to show it more, which makes workplace feedback indirect."]},{"heading":"Soft noes and the grammar of respect","paragraphs":["A direct no can be heard as an attack, so refusal is built as mai khoi saduak, not very convenient, or as a silent delay.","The particle system carries status, with khrap ending polite sentences for male speakers and kha for female speakers.","This shifts with region and generation: urban Thais in tech and international firms often prefer directness, and Chinese-Thai and southern Muslim communities differ."]}]},"context":{"countries":["TH"],"region":"Nationwide","continent":"asia","languages":["th"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Thai language","de":"Thai language","en":"Thai language"},"url":"https://en.wikipedia.org/wiki/Thai_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Thai honorifics","de":"Thai honorifics","en":"Thai honorifics"},"url":"https://en.wikipedia.org/wiki/Thai_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"متدربة في بانكوك تُعرَض عليها مهمة لا تستطيع إنجازها، فتقول آسفة وتطلب موعداً جديداً بدل أن ترفض، ومديرها يفهم الرفض رغم ذلك.","de":"Eine Praktikantin in Bangkok bekommt eine Aufgabe, die sie nicht schafft, entschuldigt sich und bittet um eine neue Frist, statt abzulehnen – und ihr Chef hört die Ablehnung trotzdem.","en":"A Bangkok intern offered work she cannot finish says sorry and asks for a new deadline instead of refusing, and her manager hears the refusal anyway."},"misunderstanding":{"ar":"الغريب قد يظن أن الصمت أو التأجيل موافقة، بينما هو في الحقيقة رفض مهذّب ينتظر أن يُقرأ.","de":"Außenstehende halten Schweigen oder Zögern für Zustimmung, dabei ist es eine höfliche Ablehnung, die gelesen werden will.","en":"Outsiders read silence or delay as agreement, when it is often a polite refusal waiting to be understood."},"comparison":{"ar":"في ثقافات أخرى يُعدّ الرفض الصريح احتراماً للوقت، أما هنا فالاحترام يُقاس بما لا يُقال صراحة.","de":"Andernorts gilt ein klares Nein als Respekt vor der Zeit; hier zeigt sich Respekt darin, was nicht offen gesagt wird.","en":"Elsewhere a blunt no signals respect for time; here respect is measured by what is left unsaid."},"expression":{"original":"เกรงใจ","language":"ไทย (Thai)","gloss":{"ar":"أن تشعر بالاعتبار وترفض أن تُثقل على الآخر","de":"rücksichtsvoll sein, sich scheuen, jemandem zur Last zu fallen","en":"to feel considerate, reluctant to impose"},"usage":{"ar":"تُقال لوصف من يتجنب إحراج غيره أو إلزامه بطلب.","de":"Beschreibt Menschen, die vermeiden, andere in Verlegenheit zu bringen oder zu verpflichten.","en":"Said of someone who avoids embarrassing or obliging others."},"transliteration":"kreng jai"}},{"id":"lng-029","version":2,"slug":"anh-em-chi-vietnamese-turns-pronouns-into-a-family-tree","contentType":"note","category":"communication","title":{"ar":"أنه وإم وتشي: شجرة عائلة في الضمائر","de":"Anh, em, chi: Pronomen als Familienstammbaum","en":"Anh, em, chi: pronouns as a family tree"},"deck":{"ar":"في الفيتنامية ليس اختيار الضمير مسألة نحوية فقط، بل هو تقدير للعمر والجنس والقرابة في آن واحد.","de":"Im Vietnamesischen wählt man mit jedem Anredepronomen ein Verwandtschaftsverhältnis – und legt damit Alter und Geschlecht des Gegenübers fest.","en":"In Vietnamese, choosing a second-person pronoun means placing your listener in a family: it fixes relative age and gender, and the pair must match."},"teaser":{"ar":"حين تتكلم الفيتنامية تختار لكل محاور موقعاً في شجرة عائلة خيالية، فتصبح أنت الأخ الأصغر أو الأخت الكبرى بحسب الحال.","de":"Wer Vietnamesisch spricht, platziert sein Gegenüber in einer gedachten Familie: als älteren Bruder, ältere Schwester oder jüngeres Geschwister.","en":"Every conversation in Vietnamese begins with a quiet calculation of age, because the pronoun you pick makes you someone's older or younger sibling."},"readingMinutes":1,"sections":{"ar":[{"heading":"ضمائر تُنسب الناس إلى بعضهم","paragraphs":["تستعمل الفيتنامية ألفاظ القرابة ضمائرَ للمخاطبة: «أنه» للأخ الأكبر، و«تشي» للأخت الكبرى، و«إم» للأخ أو الأخت الأصغر، و«أونغ» أو «با» للجدّين.","اختيار أحدها يحدّد عمر المحاور وجنسه نسبةً إليك، ويجب أن يكون الزوج متبادلاً: إن كنتَ «إم» له صار هو «أنه» لك، فلا ضمير يقف وحده.","حتى بائع ومشترية يبدوان في العمر نفسه يتفاوضان على الضمير ثوانيَ قبل أن يكملا الحديث، كأنهما يتفقان على صلة قرابة مؤقتة."]},{"heading":"«دا»: إقرارٌ فيه انحناء","paragraphs":["تفتتح «دا» الجوابَ الموجّه إلى الأكبر سناً، فهي «نعم» وإشارة احترام في كلمة واحدة، وتقول للمخاطب إنك تعرف موقعه منك.","أما «بان» فهي الضمير المحايد بين الأنداد، انتشرت في القرن العشرين مع المدرسة والإعلام، وتتيح حديثاً بلا نسب عائلي مفترض."]}],"de":[{"heading":"Verwandtschaftswörter statt Pronomen","paragraphs":["Vietnamesische Anredepronomen sind Verwandtschaftsbegriffe: anh für den älteren Bruder, chi für die ältere Schwester, em für das jüngere Geschwister, ong oder ba für Großeltern.","Die Wahl legt relatives Alter und Geschlecht fest, und das Paar muss wechselseitig sein: Bin ich dein em, bist du mein anh. Kein Pronomen steht für sich allein.","Selbst eine Verkäuferin und ein Kunde, die gleich alt aussehen, verhandeln ein paar Sekunden lang die Pronomen, bevor sie weitersprechen."]},{"heading":"Dạ: Zustimmung mit Respekt","paragraphs":["Mit dạ beginnt die Antwort an eine ältere Person; ein Wort ist zugleich Ja und Zeichen der Ehrerbietung.","Ban dagegen ist das neutrale Pronomen unter Gleichrangigen, im 20. Jahrhundert durch Schule und Medien verbreitet, und erlaubt ein Gespräch ohne angenommene Verwandtschaft."]}],"en":[{"heading":"Kinship terms doing pronoun work","paragraphs":["Vietnamese second-person pronouns are kinship terms: anh for an older brother, chi for an older sister, em for a younger sibling, and ong or ba for grandparents.","Choosing one assigns a relative age and gender, and the pair must be reciprocal: if I am your em, you are my anh. No pronoun stands alone.","A shop assistant and a customer who look the same age still negotiate pronouns for a few seconds before continuing."]},{"heading":"Dạ: a yes that bows","paragraphs":["Da opens an answer to an elder, functioning as yes and as a signal of deference at once.","Ban is the neutral peer pronoun, a twentieth-century standard spread by schooling and media, which lets people talk without assuming kinship."]}]},"context":{"countries":["VN"],"region":"Nationwide","continent":"asia","languages":["vi"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Vietnamese language","de":"Vietnamese language","en":"Vietnamese language"},"url":"https://en.wikipedia.org/wiki/Vietnamese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pronouns in Vietnamese","de":"Pronouns in Vietnamese","en":"Pronouns in Vietnamese"},"url":"https://en.wikipedia.org/wiki/Pronouns_in_Vietnamese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"غريبان في قطار فيتنامي يقضيان الدقيقة الأولى في تقدير عمر كل منهما؛ يصير الأكبر «تشي» والأصغر «إم»، ويمضي بقية السفر داخل هذين الدورين.","de":"Zwei Fremde im vietnamesischen Zug schätzen in der ersten Minute ihr Alter; der Ältere wird chi, der Jüngere em, und die restliche Fahrt verläuft in diesen Rollen.","en":"Two strangers on a Vietnamese train spend the first minute estimating each other's age; the older becomes chi and the younger em, and the rest of the journey runs inside those roles."},"misunderstanding":{"ar":"يظن بعض المتعلمين أن هذه الضمائر مجاملات، لكنها في الحقيقة تحديد لموقعك من محاورك، فاستعمالها الخاطئ يخلط الأنساب لا الأدب فحسب.","de":"Manche halten diese Pronomen für bloße Höflichkeitsfloskeln, doch sie bestimmen den eigenen Platz gegenüber dem Gegenüber; ein falscher Gebrauch verwirrt die Verhältnisse, nicht nur den Ton.","en":"Learners often treat these pronouns as politeness formulas, but they are positional: a wrong choice misplaces you in the relationship, not just the tone."},"comparison":{"ar":"حيث تكتفي لغات كثيرة بضمير محايد للخطاب، توزّع الفيتنامية الأدوار العائلية على كل لقاء، فتكون الكلمة الأولى تعريفاً بالهوية النسبية.","de":"Wo viele Sprachen ein neutrales Du kennen, verteilt das Vietnamesische bei jeder Begegnung Familienrollen – das erste Wort ist eine relative Standortbestimmung.","en":"Where many languages offer one neutral you, Vietnamese assigns family roles at every encounter, so the first word already locates both speakers."},"expression":{"original":"Dạ","language":"Tiếng Việt (Vietnamese)","gloss":{"ar":"نعم (إقرار مؤدّب لشخص أكبر سناً)","de":"ja (respektvolle Bestätigung gegenüber Älteren)","en":"yes (respectful acknowledgement to an elder)"},"usage":{"ar":"تُفتتح بها الإجابة عن سؤال موجّه إلى الأكبر سناً، فتجمع الموافقة والاحترام.","de":"Eröffnet die Antwort auf eine Frage an eine ältere Person und verbindet Zustimmung mit Ehrerbietung.","en":"Opens a reply to an older person, combining agreement with deference in a single syllable."},"transliteration":"da"}},{"id":"lng-030","version":2,"slug":"ngoko-and-krama-javanese-that-changes-with-the-person-you-face","contentType":"note","category":"languages","title":{"ar":"الجاوية تتغير حسب من تخاطب","de":"Javanisch wechselt mit dem Gegenüber","en":"Javanese shifts with the person you face"},"deck":{"ar":"في جاوة الوسطى والشرقية، يختار المتحدث مستوى لغوياً بحسب عمر المخاطب ومكانته وقربه، فيتبدل الكلام في منتصف الجملة.","de":"In Zentral- und Ostjava wählen Menschen ihre Sprachebene nach Alter, Status und Nähe – und wechseln mitten im Gespräch die Wörter.","en":"In Central and East Java speakers pick a speech level by age, status and familiarity, and can switch mid-conversation when someone new arrives."},"teaser":{"ar":"للجاوية ثلاث طبقات كلام، وكل فكرة لها أكثر من كلمة. كيف يعيش الناس هذا الاختيار اليومي؟","de":"Drei Sprachebenen, parallele Wörter für Alltag und ein Wechsel mitten im Satz: So leben Javaner ihre Sprache.","en":"Three speech levels, parallel words for everyday things, and switches mid-sentence: how Javanese people choose their words daily."},"readingMinutes":1,"sections":{"ar":[{"heading":"ثلاث طبقات لكلام واحد","paragraphs":["للجاوية ثلاث طبقات رئيسية: ngoko للأقرباء، وmadya الوسطى، وkrama للتوقير، ولكل طبقة مفرداتها الخاصة. كلمة البيت omah في ngoko وgriya في krama، وهكذا قاموس كامل من الكلمات اليومية بصور متوازية.","يحدد المستوى المكانة والعمر والألفة، وقد ينتقل المتحدث في منتصف الحديث إذا انضم شخص جديد إلى المجلس."]},{"heading":"أين تصمد krama وأين تتراجع","paragraphs":["تصمد krama بقوة في يوجياكارتا وسوراكارتا، حيث تعززها تقاليد البلاط ومناهج المدارس. وفي المدن، يتحدث كثير من الشباب بمزيج مختلط، وتسجل المسوحات اللغوية تراجع krama.","تختلف هذه الاستخدامات اختلافاً حاداً بين المدينة والقرية وبين الأجيال؛ فكثير من الأسر تستخدم ngoko في البيت وkrama مع الغرباء الأكبر سناً، بينما تحل الإندونيسية تدريجياً محل الاثنتين في الحياة العامة."]}],"de":[{"heading":"Drei Ebenen für dieselbe Sache","paragraphs":["Javanisch kennt drei Hauptebenen: ngoko für Vertrautes, madya als Mitte und krama für Ehrerbietung, jede mit eigenem Wortschatz. Das Haus heißt omah in ngoko und griya in krama, und so hat ein ganzes Wörterbuch des Alltags parallele Formen.","Ausgelöst werden die Ebenen durch Status, Alter und Vertrautheit; wer dazukommt, kann einen Sprecher mitten im Gespräch umstellen lassen."]},{"heading":"Wo krama bleibt und wo es schwindet","paragraphs":["In Yogyakarta und Surakarta hält sich krama stark, gestützt von Hoftraditionen und Schulplänen. Viele junge Städter sprechen dagegen ein gemischtes Register, und Sprachuntersuchungen verzeichnen abnehmenden krama-Gebrauch in den Städten.","Die Verwendung unterscheidet sich stark zwischen Stadt und Dorf und von Generation zu Generation; viele Familien sprechen zu Hause ngoko und nur mit älteren Fremden krama, während Indonesisch in der Öffentlichkeit beides zunehmend ersetzt."]}],"en":[{"heading":"Three levels for the same idea","paragraphs":["Javanese has three main speech levels: ngoko for intimacy, madya in the middle and krama for deference, each with separate vocabulary for the same ideas. A house is omah in ngoko and griya in krama, and a whole dictionary of everyday words has parallel forms.","Status, age and familiarity trigger the level, and a speaker can shift mid-conversation when a new person joins."]},{"heading":"Where krama holds and where it fades","paragraphs":["Krama survives strongly in Yogyakarta and Surakarta, reinforced by court traditions and school curricula. Many young urban Javanese speak a mixed register, and language surveys record declining krama use in cities.","Level use varies sharply between cities and villages and is generational; many families use ngoko at home and krama only with older strangers, while Indonesian increasingly replaces both in public life."]}]},"context":{"countries":["ID"],"region":"Central and East Java, Yogyakarta","continent":"asia","languages":["jv","id"],"period":"contemporary"},"tags":["languages","Central and East Java, Yogyakarta"],"sources":[{"organization":"Wikipedia","title":{"ar":"Javanese language","de":"Javanese language","en":"Javanese language"},"url":"https://en.wikipedia.org/wiki/Javanese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Register (sociolinguistics)","de":"Register (sociolinguistics)","en":"Register (sociolinguistics)"},"url":"https://en.wikipedia.org/wiki/Register_(sociolinguistics)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبة في يوجياكارتا تتحدث ngoko مع أخيها، وعندما يصل جار أكبر سناً تبقى في krama حتى يغادر، ولا يعلّق أحد على هذا التحول.","de":"Eine Studentin in Yogyakarta spricht ngoko mit ihrem Bruder, bis ein älterer Nachbar kommt; dann bleibt sie in krama, bis er geht, und niemand kommentiert den Wechsel.","en":"A Yogyakarta student speaks ngoko to her brother until an older neighbour arrives, then stays in krama until the neighbour leaves, and nobody comments on the switch."},"misunderstanding":{"ar":"يظن بعض الغرباء أن تبديل المستوى تظاهر أو تكلف، لكنه في نظر أهل جاوة احترام دقيق للعلاقة، وليس تغييراً في الشخص نفسه.","de":"Ortsfremde halten den Ebenenwechsel oft für Verstellung. Für Javaner ist er genaue Achtung vor der Beziehung, keine Veränderung der eigenen Person.","en":"Outsiders often read the switch as showing off. For Javanese speakers it is precise respect for the relationship, not a change in who the speaker is."},"comparison":{"ar":"يشبه الأمر من يتحول إلى صيغة رسمية في لغة أخرى عند دخول مدير، لكن الفرق أن الجاوية تبدّل المفردات كلها لا النبرة وحدها.","de":"Es ähnelt dem Wechsel in eine förmliche Anrede, wenn der Chef hereinkommt – nur dass Javanisch den gesamten Wortschatz tauscht, nicht bloß den Ton.","en":"It resembles switching to a formal register when the boss walks in, except Javanese swaps whole sets of words rather than just the tone."},"expression":{"original":"Griya","language":"Basa Jawa (Javanese)","gloss":{"ar":"بيت (في طبقة krama؛ وفي ngoko: omah)","de":"Haus (krama; ngoko: omah)","en":"house (krama; ngoko is omah)"},"usage":{"ar":"تُقال عند مخاطبة من يستحق التوقير، كالشيوخ أو المعارف الرسميين.","de":"Verwendet gegenüber Personen, denen Ehrerbietung gebührt, etwa Älteren oder offiziellen Bekannten.","en":"Used with people owed deference, such as elders or formal acquaintances."},"transliteration":"griya"}},{"id":"lng-031","version":2,"slug":"po-and-opo-the-filipino-respect-words-that-no-sentence-can-omit","contentType":"note","category":"communication","title":{"ar":"بو وأوبو: كلمات الاحترام الفلبينية","de":"Po und Opo: Respektwörter der Philippinen","en":"Po and opo: the respect words Filipinos keep"},"deck":{"ar":"في الفلبين، تُثقل كلمة صغيرة الجملة باحترام لا يستطيع النحو وحده أن يمنحه.","de":"Auf den Philippinen trägt eine kleine Partikel den Respekt, den die Grammatik allein nicht leisten kann.","en":"In the Philippines a small particle carries the respect that grammar alone cannot supply."},"teaser":{"ar":"يتعلم الفلبينيون مبكرًا أن الاحترام ليس فكرة مجردة، بل مقطع صوتي يوضع في نهاية العبارة عند مخاطبة الكبير والغريب.","de":"Filipinos lernen früh, dass Respekt keine bloße Idee ist, sondern ein Laut am Satzende, wenn man Ältere und Fremde anspricht.","en":"Filipinos learn early that respect is not just an idea but a sound placed after a phrase when addressing elders and strangers."},"readingMinutes":1,"sections":{"ar":[{"heading":"جسيم لا يُحذف من الأدب","paragraphs":["«بو» جسيم تأدّبي يوضع بعد العبارات، و«أوبو» هي كلمة «نعم» المهذبة، ويُستخدمان مع كبار السن والغرباء والرؤساء. الجسيم اختياري في القواعد لكنه ليس اختياريًا في الأخلاق؛ فحذفه أمام شخص أكبر يُقرأ كوقاحة.","في العائلات، تُدمج إيماءة «مانو» — أخذ يد الكبير ووضعها على الجبهة — عادةً مع «أوبو»، فتبقى العلاقة بين الجيلين محسوسة في الحركة والكلمة معًا."]},{"heading":"الأقارب في كل مكان","paragraphs":["«كوايا» (الأخ الأكبر) و«أتي» (الأخت الكبرى) تُستخدمان لخطاب الغرباء والزملاء كأنهم من العائلة، حتى مع المشرفين في أعمال الخدمة، فيصبح مكان العمل شبكة قرابة مصغّرة.","في تاگليش، تختلط الإنجليزية والتاگالوغية، لكن جسيمات الاحترام تبقى عادةً تاگالوغية، فتظهر جمل مثل «Yes po, I understand po». يختلف الأمر إقليميًا وجيليًا: فالتاگالوغية أساس الفلبينية لكنها ليست لغة الجميع الأولى، ولدى السيبوانو والإيلوكانو أنظمة احترام مختلفة، وقد يستخدم شباب المدن «بو» على سبيل الدعابة."]}],"de":[{"heading":"Eine Partikel, die Manieren verlangen","paragraphs":["Po ist eine Höflichkeitspartikel nach Phrasen, opo das respektvolle Ja; beide gelten gegenüber Älteren, Fremden und Vorgesetzten. Grammatisch ist die Partikel optional, in der Etikette nicht – wer sie gegenüber Älteren weglässt, wirkt unhöflich.","In Familien verbindet sich die Mano-Geste, bei der man die Hand eines Älteren an die Stirn führt, meist mit opo, sodass die Beziehung zwischen den Generationen in Bewegung und Wort zugleich spürbar bleibt."]},{"heading":"Verwandte überall","paragraphs":["Kuya (älterer Bruder) und ate (ältere Schwester) sprechen Fremde und Kollegen wie Verwandte an, auch Vorgesetzte im Dienstleistungsbereich – der Arbeitsplatz wird so zu einem kleinen Verwandtschaftsnetz.","In Taglish mischen sich Englisch und Tagalog, doch die Respektpartikeln bleiben meist Tagalog, etwa in „Yes po, I understand po“. Regional und generationell variiert das: Tagalog ist Basis des Filipino, aber nicht für alle Erstsprache; Cebuano und Ilocano haben eigene Respektsysteme, und jüngere Stadtbewohner gebrauchen po manchmal scherzhaft."]}],"en":[{"heading":"A particle manners will not drop","paragraphs":["Po is a politeness particle placed after phrases, and opo is the respectful yes, both used with elders, strangers and superiors. The particle is optional in grammar but not in manners, and dropping it with an older person reads as rudeness.","In families the mano gesture, taking an elder's hand to the forehead, usually comes with opo, so the bond between generations stays felt in movement and word at once."]},{"heading":"Kin words everywhere","paragraphs":["Kuya (older brother) and ate (older sister) address strangers and colleagues as kin, including supervisors in service work, turning a workplace into a small family network.","English and Tagalog mix in Taglish, but the respect particles usually stay Tagalog, giving sentences such as Yes po, I understand po. This varies by region and generation: Tagalog is the base of Filipino but not everyone's first language, Cebuano and Ilocano have different respect systems, and younger urban speakers sometimes use po playfully."]}]},"context":{"countries":["PH"],"region":"Luzon and Tagalog-speaking provinces","continent":"asia","languages":["tl","en"],"period":"contemporary"},"tags":["communication","Luzon and Tagalog-speaking provinces"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tagalog language","de":"Tagalog language","en":"Tagalog language"},"url":"https://en.wikipedia.org/wiki/Tagalog_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Filipino language","de":"Filipino language","en":"Filipino language"},"url":"https://en.wikipedia.org/wiki/Filipino_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظف في مركز اتصال بمانيلا يتحدث إنجليزية سليمة، ومع ذلك يقول «نعم بو» لمتصل فلبيني، فيلين لهجة المتصل فورًا، لأن الجسيم يؤدي عملًا لا تؤديه اللكنة.","de":"Ein Callcenter-Mitarbeiter in Manila spricht fehlerfreies Englisch und sagt dennoch „yes po“ zu einem philippinischen Anrufer – dessen Ton wird sofort weicher, weil die Partikel leistet, was der Akzent nicht kann.","en":"A Manila call-centre agent speaking flawless English still says yes po to a Filipino caller, and the caller's tone softens immediately, because the particle does work the accent cannot."},"misunderstanding":{"ar":"قد يظن المستمع الأجنبي أن «بو» مجرد حشو كلامي أو تردد، لكنه في الحقيقة إشارة وعي بالعلاقة الهرمية والاحترام.","de":"Ausländische Zuhörer halten po oft für ein Füllwort oder Zögern, dabei zeigt es Bewusstsein für die Beziehung und den Respekt an.","en":"Foreign listeners often hear po as filler or hesitation, when it actually signals awareness of the relationship and the respect owed."},"comparison":{"ar":"يشبه «بو» أدوات التأدب في لغات أخرى، لكنه يتميز بأنه يُلحق بالجملة كلها ويحمل وزنًا اجتماعيًا أكبر من وزنه النحوي.","de":"Po ähnelt Höflichkeitsmarkern anderer Sprachen, hängt aber am ganzen Satz und trägt mehr soziales als grammatisches Gewicht.","en":"Po resembles politeness markers in other languages, but it attaches to the whole sentence and carries more social than grammatical weight."},"expression":{"original":"Opo","language":"Tagalog / Filipino","gloss":{"ar":"نعم (باحترام)","de":"ja (respektvoll)","en":"yes (respectful)"},"usage":{"ar":"تُقال عند الرد على شخص أكبر أو غريب أو رئيس، وغالبًا مع إيماءة مانو.","de":"Antwort an Ältere, Fremde oder Vorgesetzte, oft zusammen mit der Mano-Geste.","en":"Said when answering an elder, stranger or superior, often together with the mano gesture."},"transliteration":"opo"}},{"id":"lng-032","version":2,"slug":"can-lah-the-singlish-particles-that-adjust-a-sentence-s-mood","contentType":"language","category":"languages","title":{"ar":"جزيئات سينغليش التي تعدل مزاج الجملة","de":"Singlish-Partikeln, die die Stimmung eines Satzes verändern","en":"Singlish particles that adjust a sentence's mood"},"deck":{"ar":"في سنغافورة، كلمات صغيرة مثل lah وleh وmeh تحمل نبرة المتحدث وتحول جملة بسيطة إلى تعبير عن الثقة أو الشك أو الشكوى.","de":"In Singapur tragen kleine Wörter wie lah, leh und meh die Haltung des Sprechers und verwandeln einen einfachen Satz in Zustimmung, Zweifel oder leichte Beschwerde.","en":"In Singapore, small words like lah, leh and meh carry the speaker's stance and turn a simple sentence into reassurance, doubt or mild complaint."},"teaser":{"ar":"كيف تعمل جزيئات سينغليش على تعديل نبرة الجملة، ولماذا تعتبر علامة على الهوية الوطنية رغم حملات اللغة الإنجليزية الفصيحة؟","de":"Wie Singlish-Partikeln die Stimmung eines Satzes modulieren und warum sie trotz der Speak Good English Movement als nationales Identitätsmerkmal gelten.","en":"How Singlish particles modulate a sentence's mood, and why they remain a marker of national identity despite the Speak Good English Movement."},"readingMinutes":1,"sections":{"ar":[{"heading":"جزيئات تحمل الموقف","paragraphs":["في سينغليش، اللغة الإنجليزية المحلية في سنغافورة، تحمل الجزيئات موقف المتحدث: lah تلطف أو تؤكد، leh تشير إلى شكوى خفيفة، meh تدل على عدم التصديق، وsia تضيف توكيدًا. كما أن can وcannot إجابتان كاملتان، وتكرار الأفعال يزيد الشدة، كما في wait wait wait أو big big.","تختلف هذه الاستخدامات حسب الخلفية العرقية والعمر والتعليم؛ فالعديد من السنغافوريين يتحولون إلى الإنجليزية الفصيحة في الكتابة وإلى سينغليش في مراكز الطعام، والحدود تتعلق بالهوية لا بالقدرة."]},{"heading":"بين الهوية والحدود","paragraphs":["يُستخدم سينغليش بين السكان المحليين ويُتجنب مع السياح، مما يجعله علامة على الحدود وليس الخيار الافتراضي. وقد شنت حركة التحدث بالإنجليزية الجيدة حملة ضده منذ عام 2000، لكنه ظل علامة على الهوية الوطنية."]}],"de":[{"heading":"Partikeln tragen Haltung","paragraphs":["Im Singlish, dem lokalen Englisch Singapurs, tragen Partikeln die Haltung des Sprechers: lah mildert ab oder bekräftigt, leh signalisiert eine leichte Beschwerde, meh markiert Unglauben und sia fügt Nachdruck hinzu. Can und cannot sind vollständige Antworten, und die Verdopplung von Verben verstärkt die Intensität, wie in wait wait wait oder big big.","Diese Verwendungen variieren je nach ethnischem Hintergrund, Alter und Bildung; viele Singapurer wechseln beim Schreiben zu Standardenglisch und in Hawker-Centern zu Singlish, wobei die Grenze Identität und nicht Fähigkeit betrifft."]},{"heading":"Zwischen Identität und Abgrenzung","paragraphs":["Singlish wird unter Einheimischen verwendet und gegenüber Touristen vermieden, was es zu einem Grenzmarker statt zu einer Standardwahl macht. Die Speak Good English Movement führt seit 2000 eine Kampagne dagegen, doch Singlish bleibt ein Merkmal nationaler Identität."]}],"en":[{"heading":"Particles carry stance","paragraphs":["In Singlish, Singapore's local English, particles carry stance: lah softens or asserts, leh signals a mild complaint, meh marks disbelief and sia adds emphasis. Can and cannot are complete answers, and reduplicated verbs intensify the sense, as in wait wait wait or big big.","These uses vary by ethnic background, age and education; many Singaporeans switch to Standard English in writing and to Singlish in hawker centres, and the boundary is about identity, not ability."]},{"heading":"Between identity and boundary","paragraphs":["Singlish is used between locals and avoided with tourists, which makes it a boundary marker rather than a default. The Speak Good English Movement has campaigned against it since 2000, yet Singlish remains a marker of national identity."]}]},"context":{"countries":["SG"],"region":"Singapore","continent":"asia","languages":["en","zh","ms","ta"],"period":"contemporary"},"tags":["languages","Singapore"],"sources":[{"organization":"Wikipedia","title":{"ar":"Singlish","de":"Singlish","en":"Singlish"},"url":"https://en.wikipedia.org/wiki/Singlish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Singapore","de":"Languages of Singapore","en":"Languages of Singapore"},"url":"https://en.wikipedia.org/wiki/Languages_of_Singapore","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميل سنغافوري يرد على طلب بقوله can lah، ثم لاحقًا ah؛ المكافئ بالإنجليزية الفصيحة سيكون ثلاث جمل، لكن ترتيب الجزيئات لا يزال يخبرك أن الإجابة هي نعم.","de":"Ein singapurischer Kollege antwortet auf eine Bitte mit can lah, später mit ah; die standardenglische Entsprechung wären drei Sätze, doch die Partikelreihenfolge verrät dennoch, dass die Antwort Ja lautet.","en":"A Singaporean colleague replies can lah, but later ah to a request; the Standard English equivalent would be three sentences, and the particle order still tells you the answer is yes."},"misunderstanding":{"ar":"يعتقد بعض الأجانب أن سينغليش إنجليزية مكسورة أو غير صحيحة، لكنه في الواقع نظام لغوي منظم يحمل معاني دقيقة لا توجد في الإنجليزية الفصيحة.","de":"Manche Ausländer halten Singlish für gebrochenes oder falsches Englisch, doch es ist ein regelhaftes sprachliches System mit präzisen Bedeutungen, die im Standardenglischen fehlen.","en":"Some foreigners think Singlish is broken or incorrect English, but it is a rule-governed system carrying precise meanings absent from Standard English."},"comparison":{"ar":"تمامًا كما تستخدم بعض اللهجات العربية كلمات مثل 'خلاص' و'يعني' لتعديل النبرة، يستخدم سينغليش جزيئاته لتحقيق تأثير مماثل.","de":"So wie manche deutschen Dialekte Wörter wie 'halt' oder 'eben' zur Nuancierung nutzen, setzt Singlish seine Partikeln für eine ähnliche Wirkung ein.","en":"Just as some English dialects use words like 'innit' or 'eh' to adjust tone, Singlish uses its particles for a similar effect."},"expression":{"original":"Can lah!","language":"Singlish","gloss":{"ar":"بالتأكيد، لا مشكلة (طمأنة)","de":"klar, kein Problem (beruhigend)","en":"sure, no problem (reassuring)"},"usage":{"ar":"تستخدم للرد بالإيجاب مع طمأنة المتحدث وإزالة القلق.","de":"Wird als zustimmende, beruhigende Antwort verwendet, um Bedenken zu zerstreuen.","en":"Used as an affirmative, reassuring reply to remove doubt."},"transliteration":"can lah"}},{"id":"lng-033","version":2,"slug":"ayubowan-the-sinhala-greeting-that-wishes-you-long-life","contentType":"note","category":"communication","title":{"ar":"آيوبوان: تحية سريلانكية تتمنى لك طول العمر","de":"Ayubowan: der singhalesische Gruß für ein langes Leben","en":"Ayubowan: the Sinhala greeting that wishes you long life"},"deck":{"ar":"كلمة واحدة تعمل كتحية وداع وترحيب، وردّها هو نفس الكلمة، في حوار متكافئ بين شخصين.","de":"Ein Wort dient als Hallo, Abschied und Willkommen zugleich – und die Antwort ist dasselbe Wort, ein symmetrischer Austausch.","en":"One word serves as hello, goodbye and welcome at once, and the reply is the same word, making the exchange symmetrical."},"teaser":{"ar":"في سريلانكا، تحية واحدة تحمل معنى طول العمر وتُستخدم للترحيب والوداع، ويرد عليها الشخص بنفس الكلمة.","de":"In Sri Lanka wünscht ein einziges Wort langes Leben und dient als Gruß und Abschied; die Erwiderung ist identisch.","en":"In Sri Lanka, a single word wishes long life and works as both greeting and farewell; the reply is identical, creating balance."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمة واحدة، معانٍ متعددة","paragraphs":["تعني كلمة «آيوبوان» (Ayubowan) «عساك تعيش طويلاً»، وتُستخدم كتحية عند اللقاء والوداع والترحيب في آن واحد. والرد عليها هو نفس الكلمة، لذا يكون تبادل التحية بين شخصين متماثلاً ومتوازناً. هذا التناظر يعكس روح المساواة في التواصل اليومي.","لا تقلّ الإيماءة أهمية عن الكلمة: راحتان مضمومتان على الصدر مع انحناءة خفيفة، تُستخدم مع كبار السن والرهبان. هذه الإيماءة تعبّر عن الاحترام العميق، وتُعدّ جزءاً لا يتجزأ من التحية. وتختلف درجة الانحناء حسب مقام الشخص المُحيَّا."]},{"heading":"احترام يظهر في اللغة والتنوع","paragraphs":["تُعبّر اللغة السنهالية عن الاحترام عبر لواحق الأفعال والضمائر، حيث يشكّل ضميرا «أوبا» (oba) و«أويا» (oya) ثنائياً مهذباً وأكثر حميمية. هذا التمييز اللغوي يعكس التسلسل الاجتماعي والعلاقات الشخصية. وتختلف درجة الرسمية حسب السياق والمكانة.","يستخدم التحية السنهاليون البوذيون على نطاق واسع، وتُستخدم في المناسبات الرسمية. بينما يحيّي التاميل السريلانكيون بـ«فانكام» (vankkam). هذا التنوع يعكس النسيج الثقافي المتعدد في البلاد. كما تختلف التحية حسب المنطقة والجيل، حيث يميل الشباب في المدن إلى استخدام «hello» في السياقات غير الرسمية."]}],"de":[{"heading":"Ein Wort, viele Bedeutungen","paragraphs":["Ayubowan bedeutet „Mögest du lange leben“ und dient gleichzeitig als Hallo, Abschied und Willkommen. Die Antwort ist dasselbe Wort, sodass ein Grußaustausch zwischen zwei Personen symmetrisch verläuft. Diese Symmetrie spiegelt eine egalitäre Kommunikationskultur wider.","Die Geste ist ebenso wichtig wie das Wort: Handflächen vor der Brust zusammengelegt mit einer leichten Verbeugung, verwendet gegenüber Älteren und Mönchen. Diese Geste drückt tiefen Respekt aus und ist untrennbar mit dem Gruß verbunden. Die Tiefe der Verbeugung variiert je nach Status der gegrüßten Person."]},{"heading":"Respekt in Sprache und Vielfalt","paragraphs":["Singhalesisch markiert Respekt durch Verbendungen und Pronomen, wobei oba und oya ein höfliches und ein vertrautes Paar bilden. Diese sprachliche Unterscheidung spiegelt soziale Hierarchien und persönliche Beziehungen wider. Der Grad der Förmlichkeit hängt vom Kontext und der Position ab.","Der Gruß wird von singhalesischen Buddhisten geteilt und in offiziellen Kontexten verwendet, während sri-lankische Tamilen mit vankkam grüßen. Diese Vielfalt spiegelt die multikulturelle Gesellschaft des Landes wider. Zudem variiert der Gruß je nach Region und Generation: In städtischen Kontexten verwenden Jüngere oft „hello“ in informellen Situationen."]}],"en":[{"heading":"One word, many meanings","paragraphs":["Ayubowan means “may you live long” and serves as hello, goodbye and welcome at once. The reply is the same word, so a greeting exchange between two people is symmetrical. This symmetry reflects an egalitarian approach to everyday communication.","The gesture matters as much as the word: palms together at the chest with a slight bow, used with elders and monks. This gesture conveys deep respect and is inseparable from the greeting. The depth of the bow varies according to the status of the person greeted."]},{"heading":"Respect in language and diversity","paragraphs":["Sinhala marks respect through verb endings and pronouns, with oba and oya forming a polite and familiar pair. This linguistic distinction reflects social hierarchies and personal relationships. The degree of formality depends on context and status.","The greeting is shared by Sinhala Buddhists and used in official settings, while Sri Lankan Tamils greet with vankkam. This diversity reflects the country’s multicultural fabric. The greeting also varies by region and generation: in urban settings, younger people often use “hello” informally."]}]},"context":{"countries":["LK"],"region":"Nationwide, especially southern and central Sri Lanka","continent":"asia","languages":["si","ta","en"],"period":"contemporary"},"tags":["communication","Nationwide, especially southern and central Sri Lanka"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sinhala language","de":"Sinhala language","en":"Sinhala language"},"url":"https://en.wikipedia.org/wiki/Sinhala_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sinhalese people","de":"Sinhalese people","en":"Sinhalese people"},"url":"https://en.wikipedia.org/wiki/Sinhalese_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مصعد في مكتب بكولومبو يمتلئ بأصوات «آيوبوان» مع دخول كل شخص؛ لا يتحدث أحد بعد ذلك حتى الطابق الأرضي، لكن الجميع قد حظي بالتحية.","de":"Ein Aufzug in einem Büro in Colombo füllt sich mit Ayubowan, als jede Person einsteigt; niemand spricht danach bis zum Erdgeschoss, aber alle wurden wahrgenommen.","en":"A Colombo office lift fills with ayubowan as each person enters; nobody speaks again until the ground floor, but everyone has been acknowledged."},"misunderstanding":{"ar":"قد يعتقد البعض أن «آيوبوان» تحية عالمية في سريلانكا، لكنها ترتبط بالبوذية السنهالية، لذا يفضّل بعض التاميل والمسلمين تحيات أخرى. في أماكن العمل المختلطة، شائع استخدام «hello»، وتختلف الإيماءة حسب الموقف.","de":"Manche nehmen an, Ayubowan sei in ganz Sri Lanka universell, doch der Begriff hat buddhistische Resonanz, weshalb einige tamilische und muslimische Sri Lanker andere Grüße bevorzugen. In gemischten Arbeitsumgebungen ist „hello“ üblich, und die Geste variiert je nach Situation.","en":"Some assume ayubowan is universal in Sri Lanka, but the word’s Buddhist resonance means some Tamil and Muslim Sri Lankans prefer other greetings. In mixed workplaces, hello is common, and the palms-together gesture varies by setting."},"comparison":{"ar":"مثل تحية «ناماستي» في الهند، تجمع «آيوبوان» بين الكلمة والإيماءة، لكنها تتميز بمعنى طول العمر وتناظر الرد. في المقابل، تحية «فانكام» التاميلية لها جذور لغوية مختلفة.","de":"Ähnlich wie Namaste in Indien verbindet Ayubowan Wort und Geste, betont aber das lange Leben und die symmetrische Erwiderung. Der tamilische Gruß vankkam hat hingegen andere sprachliche Wurzeln.","en":"Like namaste in India, ayubowan combines word and gesture, but it emphasizes long life and symmetrical reply. The Tamil greeting vankkam has different linguistic roots."},"expression":{"original":"ආයුබෝවන්","language":"සිංහල (Sinhala)","gloss":{"ar":"عساك تعيش طويلاً (تحية وداع)","de":"Mögest du lange leben (Hallo und Abschied)","en":"may you live long (hello and goodbye)"},"usage":{"ar":"تُستخدم عند اللقاء والوداع والترحيب، مع ضم الراحتين على الصدر وانحناءة خفيفة.","de":"Wird als Gruß, Abschied und Willkommen verwendet, oft mit zusammengelegten Handflächen vor der Brust und leichter Verbeugung.","en":"Used as hello, goodbye and welcome, often with palms together at the chest and a slight bow."},"transliteration":"ayubowan"}},{"id":"lng-034","version":2,"slug":"khanubhayo-how-nepali-conjugates-respect-into-the-verb","contentType":"note","category":"languages","title":{"ar":"خانوبهايو: كيف يصرف النيبالي الاحترام في الفعل","de":"Khanubhayo: Wie Nepali Respekt in das Verb konjugiert","en":"Khanubhayo: how Nepali conjugates respect into the verb"},"deck":{"ar":"في النيبالية، تُحمل الأفعال درجات الاحترام، فتتغير صيغة الفعل حسب مكانة الشخص الذي نتحدث عنه، لا حسب المستمع.","de":"Im Nepali tragen Verben Höflichkeitsstufen, sodass sich die Verbform je nach Status der Person ändert, über die gesprochen wird – nicht nach dem Zuhörer.","en":"In Nepali, verbs carry levels of politeness, so the verb form changes according to the status of the person being talked about, not the listener."},"teaser":{"ar":"اكتشف كيف يدمج الناطقون بالنيبالية الاحترام في قواعد اللغة، وكيف يمكن لصيغة فعل واحدة أن تكشف عن مكانة شخص غائب.","de":"Entdecken Sie, wie Nepali-Sprecher Respekt in die Grammatik einbetten und wie eine einzige Verbform den Status einer abwesenden Person verraten kann.","en":"Discover how Nepali speakers build respect into grammar, and how a single verb form can reveal the status of someone who isn't even in the room."},"readingMinutes":1,"sections":{"ar":[{"heading":"الاحترام يُصرف مع الفعل","paragraphs":["في اللغة النيبالية، يُعبَّر عن الاحترام من خلال تصريف الفعل، فصيغة مثل 'خايو' (أكل) تُستخدم مع شخص عادي، بينما 'خانوبهايو' (أكل، صيغة احترام) تُستخدم مع شخص محترم. هذا التمييز يصف نفس الفعل لكنه يحمل دلالة اجتماعية مختلفة.","تنطبق صيغة الاحترام على الفاعل وليس على المستمع، لذا يمكن لجملة أن تُكنّ الاحترام لشخص غير موجود في الغرفة. هذا يعني أن المتحدث يختار الفعل بناءً على من يتحدث عنه، وليس بناءً على من يخاطبه."]},{"heading":"أنت بين الأدب والتكبر","paragraphs":["توجد في النيبالية ثلاثة مستويات للضمير 'أنت': 'تاپايم' (محترم)، 'تيمي' (مألوف)، و'تا' (حميمي أو مهين). كل ضمير يأتي مع تصريف فعل يناسبه، مما يضيف طبقة أخرى من التعقيد الاجتماعي.","يستمد هذا النظام من الآلية الهندو-آرية نفسها الموجودة في الهندية والبنغالية، لكن النيبالية توسع نطاق أفعال الاحترام أكثر من جيرانها. في كاتماندو، يُتوقع استخدام أفعال الاحترام مع الأصهار والمعلمين، واستخدام الصيغة العادية قد يُذكر لسنوات."]}],"de":[{"heading":"Respekt wird mit dem Verb konjugiert","paragraphs":["Im Nepali wird Höflichkeit durch die Verbkonjugation ausgedrückt: Die Form 'khayo' (er aß) wird für eine gewöhnliche Person verwendet, während 'khanubhayo' (er aß, honorifisch) für eine respektierte Person steht. Diese Unterscheidung beschreibt dieselbe Handlung, trägt aber eine andere soziale Bedeutung.","Die honorifische Form bezieht sich auf das Subjekt, nicht auf den Zuhörer. Daher kann ein Satz jemanden ehren, der nicht im Raum ist. Der Sprecher wählt das Verb also danach, über wen er spricht, nicht danach, wen er anspricht."]},{"heading":"Du zwischen Höflichkeit und Überheblichkeit","paragraphs":["Im Nepali gibt es drei Stufen für 'du': 'tapaim' (respektvoll), 'timi' (vertraut) und 'ta' (intim oder beleidigend). Jede Stufe bringt ihre eigene Verbkongruenz mit, was eine weitere Ebene sozialer Komplexität hinzufügt.","Das System basiert auf derselben indo-arischen Mechanik wie Hindi und Bengalisch, aber Nepali dehnt honorifische Verben weiter aus als seine Nachbarn. In Kathmandu werden honorifische Verben gegenüber Schwiegereltern und Lehrern erwartet, und die Verwendung der einfachen Form kann jahrelang in Erinnerung bleiben."]}],"en":[{"heading":"Respect is conjugated with the verb","paragraphs":["In Nepali, politeness is expressed through verb conjugation: the form 'khayo' (he ate) is used for an ordinary person, while 'khanubhayo' (he ate, honorific) is used for a respected person. This distinction describes the same action but carries a different social meaning.","The honorific form applies to the subject, not the listener, so a sentence can honour someone who is not in the room. This means the speaker chooses the verb based on who is being talked about, not who is being addressed."]},{"heading":"You: between respect and arrogance","paragraphs":["Nepali has three levels for 'you': 'tapaim' (respectful), 'timi' (familiar), and 'ta' (intimate or insulting). Each brings its own verb agreement, adding another layer of social complexity.","The system draws on the same Indo-Aryan machinery as Hindi and Bengali, but Nepali extends honorific verbs further than its neighbours. In Kathmandu, honorific verbs are expected with in-laws and teachers, and using the plain form can be remembered for years."]}]},"context":{"countries":["NP"],"region":"Kathmandu Valley and hill districts","continent":"asia","languages":["ne","en"],"period":"contemporary"},"tags":["languages","Kathmandu Valley and hill districts"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nepali language","de":"Nepali language","en":"Nepali language"},"url":"https://en.wikipedia.org/wiki/Nepali_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في كاتماندو يجيب عن سؤال حول معلم غائب يستخدم أفعال الاحترام طوال حديثه، لأن قواعد الاحترام تتبع الشخص الذي يتم الحديث عنه، وليس المستمع.","de":"Ein Student in Kathmandu, der auf eine Frage über einen abwesenden Lehrer antwortet, verwendet durchgehend honorifische Verben, weil die Grammatik des Respekts der Person folgt, über die gesprochen wird, nicht dem Zuhörer.","en":"A Kathmandu student answering a question about an absent teacher uses honorific verbs throughout, because the grammar of respect follows the person being discussed, not the listener."},"misunderstanding":{"ar":"يعتقد بعض المتعلمين أن صيغة الاحترام تُستخدم لإظهار الأدب للمستمع فقط، لكنها في الواقع تُستخدم لتكريم الشخص الذي نتحدث عنه، حتى لو لم يكن حاضرًا.","de":"Manche Lernende glauben, die honorifische Form diene nur dazu, dem Zuhörer Höflichkeit zu erweisen. Tatsächlich ehrt sie die Person, über die gesprochen wird, auch wenn diese nicht anwesend ist.","en":"Some learners think the honorific form is only used to show politeness to the listener, but it actually honours the person being talked about, even if they are not present."},"comparison":{"ar":"على عكس الإنجليزية التي تعبر عن الاحترام باختيار الكلمات، تدمج النيبالية الاحترام في بنية الفعل نفسها، مما يجعلها جزءًا لا يتجزأ من القواعد.","de":"Anders als im Englischen, wo Respekt durch Wortwahl ausgedrückt wird, integriert Nepali den Respekt in die Verbstruktur selbst und macht ihn zu einem untrennbaren Teil der Grammatik.","en":"Unlike English, which expresses respect through word choice, Nepali integrates respect into the verb structure itself, making it an inseparable part of grammar."},"expression":{"original":"तपाईं कस्तो हुनुहुन्छ?","language":"नेपाली (Nepali)","gloss":{"ar":"كيف حالك؟ (بصيغة الاحترام)","de":"Wie geht es Ihnen? (respektvoll)","en":"How are you? (respectful)"},"usage":{"ar":"تُستخدم لتحية شخص محترم، مثل معلم أو قريب أكبر سنًا، وتظهر فيها صيغة الفعل 'هونوهونتشا' التي تحمل علامة الاحترام.","de":"Wird verwendet, um eine respektierte Person zu begrüßen, z. B. einen Lehrer oder älteren Verwandten; die Verbform 'hunuhuncha' trägt die honorifische Markierung.","en":"Used to greet a respected person, such as a teacher or elder relative; the verb form 'hunuhuncha' carries the honorific marker."},"transliteration":"tapaim kasto hunuhuncha?"}},{"id":"lng-035","version":2,"slug":"sain-baina-uu-and-the-mongolian-oo-that-keeps-a-story-going","contentType":"note","category":"communication","title":{"ar":"ساين باينا أوو: تحية تفتح الحكاية","de":"Sain baina uu und das mongolische oo","en":"Sain baina uu and the Mongolian oo"},"deck":{"ar":"في منغوليا، التحية ليست مجرد كلمة عابرة، بل بداية حوار يستمع فيه الناس بعمق.","de":"In der Mongolei beginnt jede Begegnung mit einer Frage nach dem Wohlbefinden – und einem aufmerksamen Zuhören.","en":"In Mongolia, a greeting is more than hello – it's an invitation to listen closely and keep the story going."},"teaser":{"ar":"كيف تتحول تحية بسيطة إلى دعوة للاستماع؟ في منغوليا، الرد 'ساين' يفتح الباب لحكاية طويلة.","de":"Wie eine einfache Begrüßung zum Anfang einer langen Geschichte wird: Das mongolische 'oo' hält das Gespräch am Leben.","en":"How does a simple 'are you well?' open a long conversation? The Mongolian 'oo' turns listening into an active art."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تتجاوز المجاملة","paragraphs":["عند لقاء شخص في أولانباتار أو السهوب، يبدأ الحوار بعبارة 'ساين باينا أوو' أي 'هل أنت بخير؟'. الرد المعتاد 'ساين، ساين' أو 'ساين باينا' يعكس اهتمامًا حقيقيًا بالآخر.","خلال سرد طويل، يستخدم المستمعون 'أوو' و'تيم' كإشارات استماع، وقد يمدونها لإظهار الانتباه. هذه الإشارات ليست مجرد أصوات، بل جزء من آداب الحوار."]},{"heading":"اللغة التي تحافظ على الإيقاع","paragraphs":["تتميز المنغولية بتناغم الحركات، حيث تتبدل اللواحق وفق حركات الكلمة، مما يجعل للending الواحد عدة تهجئات صحيحة. هذا التناغم يضفي موسيقى على الكلام.","كما أن طول الحركة يغير المعنى، فالحركة القصيرة أو الطويلة قد تبدل كلمة بأكملها. هذا يجعل الاستماع الدقيق أمرًا ضروريًا."]}],"de":[{"heading":"Mehr als eine Begrüßung","paragraphs":["In Ulaanbaatar und den Steppenprovinzen begrüßt man sich mit 'Sain baina uu' – 'Bist du wohlauf?'. Die Antwort 'sain, sain' oder 'sain baina' zeigt echtes Interesse am Gegenüber.","Während eines langen Berichts nutzen Zuhörer 'oo' und 'tiim' als Rückmeldung, oft gedehnt, um Aufmerksamkeit zu signalisieren. Diese Laute sind kein Füllsel, sondern Teil der Gesprächskultur."]},{"heading":"Eine Sprache mit Rhythmus","paragraphs":["Die mongolische Vokalharmonie lässt Suffixe mit den Vokalen des Wortes wechseln, sodass eine Endung mehrere korrekte Schreibweisen in Kyrillisch hat. Das verleiht der Sprache einen musikalischen Fluss.","Auch die Vokallänge trägt Bedeutung: Ein kurzer oder langer Vokal kann ein Wort verändern, nicht nur den Akzent färben. Genau hinzuhören ist daher entscheidend."]}],"en":[{"heading":"A greeting that goes deeper","paragraphs":["In Ulaanbaatar and the steppe provinces, people greet each other with 'Sain baina uu' – 'Are you well?'. The usual reply, 'sain, sain' or 'sain baina', signals genuine care for the other person.","During a long account, listeners use 'oo' and 'tiim' as backchannels, often drawn out to show attention. These sounds are not filler; they are part of the etiquette of conversation."]},{"heading":"A language with its own rhythm","paragraphs":["Mongolian vowel harmony makes suffixes alternate with the word's vowels, so one ending has several correct spellings in Cyrillic. This gives the language a musical flow.","Vowel length carries meaning, too: a short or long vowel can change a word rather than merely colour an accent. Listening closely is therefore essential."]}]},"context":{"countries":["MN"],"region":"Ulaanbaatar and the steppe provinces","continent":"asia","languages":["mn","ru"],"period":"contemporary"},"tags":["communication","Ulaanbaatar and the steppe provinces"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mongolian language","de":"Mongolian language","en":"Mongolian language"},"url":"https://en.wikipedia.org/wiki/Mongolian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mongolian script","de":"Mongolian script","en":"Mongolian script"},"url":"https://en.wikipedia.org/wiki/Mongolian_script","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"راعٍ يشرح شتاءً قاسيًا يتوقف كل بضع جمل ليقول 'أوو'؛ صمت الباحثة الزائرة يُفسر كعدم اهتمام، بينما 'مم-هم' الإنجليزية لا تبدو الشكل الصحيح للاستماع.","de":"Ein Hirte erklärt einen harten Winter und hält alle paar Sätze inne für ein 'oo'; die Stille der Forscherin wirkt wie Unaufmerksamkeit, während ihr englisches 'mm-hm' nicht die richtige Form des Zuhörens zu sein scheint.","en":"A herder explaining a hard winter pauses for 'oo' every few sentences; the visiting researcher's silence reads as inattention, while her own English 'mm-hm' does not feel like the right shape of listening."},"misunderstanding":{"ar":"قد يظن الزائر أن الصمت أثناء الاستماع علامة احترام، لكنه في الثقافة المنغولية قد يُفهم كإهمال.","de":"Besucher mögen Schweigen als Respekt deuten, doch in der mongolischen Kultur kann es als Desinteresse missverstanden werden.","en":"Visitors may think silence shows respect, but in Mongolian culture it can be taken as disinterest."},"comparison":{"ar":"في حين أن الإنجليزية تستخدم 'mm-hm'، تفضل المنغولية 'أوو' الممتدة، مما يعكس اختلافًا في إيقاع الاستماع.","de":"Während im Englischen 'mm-hm' üblich ist, zieht das Mongolische ein gedehntes 'oo' vor – ein anderer Rhythmus des Zuhörens.","en":"While English uses 'mm-hm', Mongolian prefers a drawn-out 'oo' – a different rhythm of listening."},"expression":{"original":"Сайн байна уу?","language":"Монгол хэл (Mongolian)","gloss":{"ar":"هل أنت بخير؟ / مرحبًا","de":"Bist du wohlauf? / Hallo","en":"Are you well? / Hello"},"usage":{"ar":"تحية قياسية تُستخدم عند اللقاء، ويُرد عليها بـ 'ساين' أو 'ساين باينا'.","de":"Standardbegrüßung, beantwortet mit 'sain' oder 'sain baina'.","en":"Standard greeting, answered with 'sain' or 'sain baina'."},"transliteration":"sain baina uu?"}},{"id":"lng-036","version":2,"slug":"taarof-the-iranian-ritual-of-refusing-what-you-want","contentType":"note","category":"communication","title":{"ar":"تعارف: طقوس الرفض الإيرانية","de":"Taarof: Das iranische Ritual der Ablehnung","en":"Taarof: The Iranian Ritual of Refusing"},"deck":{"ar":"في إيران، الرفض الأول ليس رفضاً حقيقياً، بل خطوة في رقصة اجتماعية متقنة.","de":"Im Iran ist die erste Ablehnung keine echte Ablehnung, sondern ein Schritt in einem sozialen Tanz.","en":"In Iran, the first refusal is not a real refusal, but a step in an elaborate social dance."},"teaser":{"ar":"تعارف هو فن تقديم ورفض الأشياء، من دفع الحساب إلى أخذ أفضل مقعد، ويحتاج إلى لغة مشتركة لفهم ما وراء الكلمات.","de":"Taarof ist die Etikette des Anbietens und Ablehnens, vom Bezahlen bis zum besten Sitzplatz, und erfordert ein gemeinsames Verständnis für das, was hinter den Worten steht.","en":"Taarof is the etiquette of offering and refusing, from paying the bill to taking the best seat, and it requires a shared understanding of what lies behind the words."},"readingMinutes":1,"sections":{"ar":[{"heading":"رقصة الرفض","paragraphs":["في إيران، تعارف هو آداب تقديم ورفض الأشياء. عندما يشتري شخص ما، يقول البائع 'ناقابل' ويرفض الدفع، بينما يصر المشتري على الدفع. هذا ليس مجرد مجاملة، بل نظام كامل يحكم التفاعلات اليومية.","يحدد تعارف من يجلس في أفضل مقعد، ومن يأخذ آخر قطعة فاكهة، ومن يمر أولاً عند الباب. الرفض مرة واحدة أمر روتيني، والرفض الثالث هو عادةً حيث تكمن الإجابة الحقيقية."]},{"heading":"ما وراء الكلمات","paragraphs":["عبارة 'خواهش می‌کنم' (khahesh mikonam) تعني 'على الرحب والسعة' وتستخدم أيضاً لتلطيف الطلب، فهي تغطي معنى 'من فضلك' و'على الرحب والسعة' معاً. هذا يظهر كيف تتشابك اللغة مع الآداب الاجتماعية."]}],"de":[{"heading":"Der Tanz der Ablehnung","paragraphs":["Im Iran ist Taarof die Etikette des Anbietens und Ablehnens. Wenn jemand etwas kauft, sagt der Verkäufer 'naqabel' (nicht würdig für Sie) und winkt ab, während der Käufer auf der Zahlung besteht. Das ist nicht nur Höflichkeit, sondern ein ganzes System, das den Alltag prägt.","Taarof bestimmt, wer den besten Platz bekommt, wer das letzte Stück Obst nimmt und wer an der Tür zuerst durchgeht. Einmal abzulehnen ist Routine, und die dritte Ablehnung ist meistens die, hinter der die echte Antwort liegt."]},{"heading":"Jenseits der Worte","paragraphs":["Der Ausdruck 'khahesh mikonam' bedeutet 'Sie sind willkommen' und wird auch verwendet, um eine Bitte abzumildern; derselbe Satz deckt also sowohl 'bitte' als auch 'gern geschehen' ab. Das zeigt, wie Sprache und soziale Etikette miteinander verwoben sind."]}],"en":[{"heading":"The Dance of Refusal","paragraphs":["In Iran, taarof is the etiquette of offering and refusing. When someone buys something, the shopkeeper says 'naqabel' (not worthy of you) and waves away payment while the buyer insists on paying. This is not just politeness but a whole system that structures ordinary exchanges.","Taarof determines who takes the best seat, who gets the last piece of fruit and who has the right of way at a doorway. Declining once is routine, and the third refusal is usually where the real answer lies."]},{"heading":"Beyond the Words","paragraphs":["The phrase 'khahesh mikonam' means 'you are welcome' and is also used to soften a request, so the same phrase covers both 'please' and 'you are welcome'. This shows how language and social etiquette are intertwined."]}]},"context":{"countries":["IR"],"region":"Nationwide, strongest in Tehran, Isfahan and Shiraz","continent":"asia","languages":["fa"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in Tehran, Isfahan and Shiraz"],"sources":[{"organization":"Wikipedia","title":{"ar":"Taarof","de":"Taarof","en":"Taarof"},"url":"https://en.wikipedia.org/wiki/Taarof","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Persian language","de":"Persian language","en":"Persian language"},"url":"https://en.wikipedia.org/wiki/Persian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق تاكسي في طهران يرفض الأجرة ثلاث مرات؛ يصر الراكب على الدفع، وكلاهما راضٍ عندما تُترك النقود أخيراً على المقعد، لأن الأجرة لم تكن موضع شك، بل الطقس فقط.","de":"Ein Taxifahrer in Teheran lehnt den Fahrpreis dreimal ab; der Fahrgast bietet weiter an, und beide sind zufrieden, als das Geld schließlich auf dem Sitz liegt, denn der Fahrpreis stand nie in Frage, nur das Ritual.","en":"A Tehran taxi driver refuses the fare three times; the passenger keeps offering, and both are satisfied when the money is finally left on the seat, because the fare was never in doubt, only the ritual."},"misunderstanding":{"ar":"يقع الأجانب في فخ تعارف، فيأخذون الرفض الأول على أنه حقيقي، ثم يبدون وقحين إذا أصرّوا أو جشعين إذا قبلوا.","de":"Ausländer tappen in die Taarof-Falle, indem sie die erste Ablehnung wörtlich nehmen und dann unhöflich wirken, wenn sie darauf bestehen, oder gierig, wenn sie annehmen.","en":"Foreigners fall into the taarof trap by taking the first refusal at face value and then appear rude when they insist or greedy when they accept."},"comparison":{"ar":"في الثقافات التي تُقدَّر فيها المباشرة، قد يُنظر إلى تعارف على أنه غموض أو إهدار للوقت، لكنه في إيران وسيلة للحفاظ على الكرامة والانسجام الاجتماعي.","de":"In Kulturen, die Direktheit schätzen, mag Taarof als unklar oder zeitverschwendend erscheinen, doch im Iran dient es der Wahrung von Würde und sozialer Harmonie.","en":"In cultures that value directness, taarof may seem ambiguous or time-wasting, but in Iran it is a way to preserve dignity and social harmony."},"expression":{"original":"خواهش میکنم","language":"فارسی (Persian)","gloss":{"ar":"على الرحب والسعة / من فضلك، لا تزعج نفسك","de":"Sie sind willkommen / bitte, bemühen Sie sich nicht","en":"you are welcome / please, do not trouble yourself"},"usage":{"ar":"تستخدم كرد على الشكر وأيضاً لتلطيف الطلب.","de":"Wird als Antwort auf Dank und zur Abschwächung einer Bitte verwendet.","en":"Used as a response to thanks and to soften a request."},"transliteration":"khahesh mikonam"}},{"id":"lng-037","version":2,"slug":"inshallah-the-phrase-that-commits-the-future-to-god-and-the-present-to-flexibili","contentType":"note","category":"communication","title":{"ar":"إن شاء الله: كلمة تربط المستقبل بالإيمان","de":"Inshallah: Wenn Gott will, entscheidet die Zukunft","en":"Inshallah: the phrase that leaves the future open"},"deck":{"ar":"عبارة تسبق كل وعد بالمستقبل، وتحمل بين طيّاتها تواضع المؤمن ومرونة الحياة اليومية.","de":"Ein Satz, der jedes Versprechen an den Glauben bindet und dem Alltag Spielraum lässt.","en":"One expression follows nearly every promise about tomorrow, carrying humility and everyday flexibility at once."},"teaser":{"ar":"من موعد اجتماع إلى دعوة عرس، تسبق العبارة كل حديث عن الغد، ويتعلّم الناس قراءة نبرتها قبل معناها.","de":"Von der Verabredung bis zur Hochzeitseinladung steht die Wendung nach jedem Satz über morgen – und wird oft erst am Tonfall gedeutet.","en":"From a meeting time to a wedding invitation, the phrase trails every plan for the future, and people read its tone before its meaning."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف نستخدمها كل يوم","paragraphs":["تأتي «إن شاء الله» بعد أي كلام عن المستقبل، من موعد لقاء إلى دعوة عرس. وتعلّم النصوص الدينية المؤمن أن يقولها بدل أن يجزم بما سيحمله الغد، فتغدو علامة تواضع لا مجرد عادة كلامية.","في الاستعمال اليومي تتراوح بين الصدق والتشكيك، وتكرارها قد يعني أن الوعد بعيد عن التحقق. ومع ذلك يبقى الموعد المؤكد بها صادق النية، لكن من يحتاج يقيناً يسأل مرة أخرى قبل الموعد."]},{"heading":"بين النية والموعد","paragraphs":["يقول صاحب دكان في القاهرة «إن شاء الله» حين يعد بتسليم طلب يوم الخميس، فيأتي الزبون السبت ولا يستغرب، لأن الوعد كان عن نية لا عن جدول. ويختلف الاستعمال كثيراً بحسب البلد والطبقة والتدين، فبعض المتحدثين العلمانيين يستخدمونها كعادة لا كموقف ديني، ورجل الأعمال الذي يحجز رحلة يظل يتحقق من موعده."]}],"de":[{"heading":"Wie sie den Alltag prägt","paragraphs":["„In sha Allah“, wenn Gott will, folgt fast jeder Aussage über die Zukunft, von der Verabredung bis zur Hochzeitseinladung. Der Koran lehrt Gläubige, sie zu sagen, statt zu behaupten, was morgen kommt – ein Zeichen von Demut, nicht nur eine Redewendung.","Im Alltag reicht die Bedeutung von aufrichtig bis skeptisch; ein wiederholtes Inshallah kann andeuten, dass ein Versprechen kaum gehalten wird. Ein mit der Wendung bestätigter Termin ist ehrlich gemeint, doch wer Sicherheit braucht, fragt kurz vorher noch einmal nach."]},{"heading":"Absicht und Zeitplan","paragraphs":["Ein Ladenbesitzer in Kairo sagt Inshallah, als er die Lieferung für Donnerstag zusagt; der Kunde kommt am Samstag und ist nicht überrascht, weil das Versprechen die Absicht betraf, nicht den Kalender. Der Gebrauch variiert stark nach Land, Schicht und Religiosität: Säkulare arabische Sprecher nutzen sie als Gewohnheit, und ein Geschäftsmann mit Flugticket prüft dennoch den Plan."]}],"en":[{"heading":"How it shapes daily life","paragraphs":["In sha Allah, if God wills, follows almost any statement about the future, from a meeting time to a wedding invitation. The Quran instructs believers to say it rather than assert what tomorrow will bring, so it marks humility in Islamic practice.","In everyday use it ranges from sincere to sceptical, and a repeated inshallah can signal that a promise is unlikely to be kept. A time confirmed with the phrase is meant sincerely, but people who need certainty usually ask again closer to the date."]},{"heading":"Intention versus schedule","paragraphs":["A Cairo shop owner says inshallah when promising a delivery on Thursday; the customer comes on Saturday and is not surprised, because the promise was about intention rather than scheduling. Usage varies enormously by country, class and religiosity: secular Arabic speakers may use it as a habit, and a businessman planning a flight still checks the schedule."]}]},"context":{"countries":["SA","EG","JO"],"region":"Arabic-speaking Middle East","continent":"asia","languages":["ar","en"],"period":"contemporary"},"tags":["communication","Arabic-speaking Middle East"],"sources":[{"organization":"Wikipedia","title":{"ar":"Inshallah","de":"Inshallah","en":"Inshallah"},"url":"https://en.wikipedia.org/wiki/Inshallah","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Arabic","de":"Arabic","en":"Arabic"},"url":"https://en.wikipedia.org/wiki/Arabic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صاحب دكان في القاهرة يعد بتسليم طلب يوم الخميس ويقول «إن شاء الله»، فيأتي الزبون السبت غير مستغرب، لأن الوعد كان عن نية لا عن موعد محدد.","de":"Ein Ladenbesitzer in Kairo verspricht die Lieferung für Donnerstag mit Inshallah; der Kunde kommt am Samstag und ist nicht überrascht, weil das Versprechen die Absicht betraf, nicht den Termin.","en":"A Cairo shop owner says inshallah when promising a delivery on Thursday; the customer comes on Saturday and is not surprised, because the promise was about intention rather than scheduling."},"misunderstanding":{"ar":"يفهم بعض الزوار أن العبارة تهرّب أو رفض، لكنها في أصلها إقرار بأن الأمر بيد الله، وقد تكون صادقة تماماً.","de":"Manche Besucher hören in der Wendung eine Ausrede oder Ablehnung, doch ursprünglich bekennt sie, dass die Sache in Gottes Hand liegt – und kann völlig ernst gemeint sein.","en":"Some visitors hear evasion or refusal, yet the phrase originally acknowledges that the outcome rests with God, and it can be entirely sincere."},"comparison":{"ar":"تنتقل العبارة مع التأثير العربي إلى التركية «إن شاء الله» والملايوية والفارسية، فتصبح جسراً لغوياً بين شعوب مختلفة.","de":"Mit dem arabischen Einfluss wandert die Wendung ins Türkische, Malaiische und Persische und wird so zur sprachlichen Brücke zwischen Gesellschaften.","en":"Arabic influence carries the phrase into Turkish insallah, Malay insyaallah and Persian enshallah, making it a linguistic bridge between societies."},"expression":{"original":"إن شاء الله","language":"العربية (Arabic)","gloss":{"ar":"إذا أراد الله / على أمل","de":"wenn Gott will / hoffentlich","en":"if God wills / hopefully"},"usage":{"ar":"تُقال بعد أي وعد أو خطة للمستقبل، من موعد عمل إلى دعوة عرس.","de":"Steht nach jeder Zusage oder jedem Plan für die Zukunft, vom Arbeitstermin bis zur Hochzeitseinladung.","en":"Said after any promise or plan for the future, from a work appointment to a wedding invitation."},"transliteration":"in sha Allah"}},{"id":"lng-038","version":2,"slug":"kolay-gelsin-the-turkish-blessing-for-whoever-happens-to-be-working","contentType":"note","category":"communication","title":{"ar":"كولاي غيلسين: تحية من يعمل","de":"Kolay gelsin: der türkische Segen für alle, die arbeiten","en":"Kolay gelsin: the Turkish blessing for whoever is working"},"deck":{"ar":"عبارة تركية تُقال لكل من يعمل، من النادل إلى المزارع، لتخفيف عناء العمل دون انتظار رد.","de":"Ein türkischer Satz, der jedem gilt, der sichtbar arbeitet – vom Kellner bis zum Bauern – und Mühe anerkennt, ohne eine Gegenleistung zu erwarten.","en":"A Turkish phrase said to anyone visibly working, from a waiter to a farmer, acknowledging effort without expecting anything in return."},"teaser":{"ar":"في تركيا، كلمة واحدة تكفي لتقول لمن يعمل: أرى جهدك. إنها ليست تحية ولا شكرًا، بل اعتراف لطيف بالتعب.","de":"In der Türkei genügt ein Wort, um jemandem zu sagen: Ich sehe deine Anstrengung. Kolay gelsin ist weder Gruß noch Dank, sondern eine freundliche Anerkennung.","en":"In Turkey, one phrase says it all to someone at work: I see your effort. Kolay gelsin is neither a greeting nor a thank-you, but a gentle nod to labour."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف تُستخدم في الحياة اليومية","paragraphs":["كولاي غيلسين، ومعناها \"ليكن سهلًا\"، تُقال لأي شخص يعمل بشكل مرئي: نادل، عامل نظافة، مزارع، أو زميل يجلس إلى مكتبه. إنها ليست تحية ولا شكرًا؛ إنها تعترف بالجهد دون أن توحي بأن المتحدث يريد شيئًا. تختلف طريقة الأداء حسب المنطقة والجيل: فقد يختصرها سكان المدن إلى \"كولاي\" ككلمة مرور عابرة، بينما ينطقها كبار السن في الريف بنبرة دعاء كامل."]},{"heading":"عبارات أخرى وشبكة المعنى","paragraphs":["إلى جانب كولاي غيلسين، تُقال إلينه صاغليق (صحة ليديك) للطاهي بعد الطعام، وللحلاق أو الخياط بعد عملهما. هوش غيلدينيز ترحب بالزائر، وغوله غوله تودعه، والرد على الترحيب هو هوش بولودوك. هذا النمط مشترك بين اللغات التركية واللغات المجاورة، من الأذربيجانية كولاي غيلسين إلى الاستخدام التركي في البلقان.","في المثال: رجل يمر بجانب ميكانيكي مستلقٍ تحت سيارة يقول كولاي غيلسين دون توقف؛ فيتمتم الميكانيكي من الأرض \"صاغ أول\"، ولا يتوقع أي منهما أن يتحول التبادل إلى محادثة."]}],"de":[{"heading":"Wie es im Alltag verwendet wird","paragraphs":["Kolay gelsin, „möge es leicht sein“, sagt man zu jedem, der sichtbar arbeitet: einem Kellner, einer Reinigungskraft, einem Bauern oder einem Kollegen am Schreibtisch. Es ist weder ein Gruß noch ein Dankeschön; es würdigt die Mühe, ohne dass der Sprecher etwas will. Die Aussprache variiert regional und generationell: Städter kürzen es oft zu einem knappen „kolay“ als Gruß im Vorbeigehen, während ältere Menschen auf dem Land es mit vollem Segenston aussprechen."]},{"heading":"Weitere Wendungen und ihr Bedeutungsnetz","paragraphs":["Neben kolay gelsin sagt man eline sağlık (Gesundheit für deine Hände) zu einem Koch nach dem Essen und zu einem Friseur oder Schneider nach der Arbeit. Hoş geldiniz heißt einen Besucher willkommen, güle güle verabschiedet ihn, und die Antwort auf den Willkommensgruß ist hoş bulduk. Das Muster teilen viele Turksprachen und Nachbarsprachen, vom aserbaidschanischen kolay gelsin bis zum türkischen Gebrauch auf dem Balkan.","Ein Mann, der an einem Mechaniker vorbeigeht, der unter einem Auto liegt, sagt kolay gelsin, ohne stehen zu bleiben; der Mechaniker brummt vom Boden aus „sağ ol“, und keiner erwartet, dass daraus ein Gespräch wird."]}],"en":[{"heading":"How it works in daily life","paragraphs":["Kolay gelsin, meaning \"may it come easy\", is said to anyone visibly working: a waiter, a cleaner, a farmer or a colleague at a desk. It is neither a greeting nor a thank-you; it acknowledges effort without implying that the speaker wants anything. Delivery varies by region and generation: city dwellers often shorten it to a passing \"kolay\" as a kind of password, while older speakers in rural areas pronounce it with the full weight of a blessing."]},{"heading":"Other phrases and their web of meaning","paragraphs":["Alongside kolay gelsin, eline sağlık (health to your hands) is said to a cook after a meal and to a hairdresser or tailor after their work. Hoş geldiniz welcomes a visitor and güle güle sends them off, and the answer to the welcome is hoş bulduk. The pattern is shared across Turkic and neighbouring languages, from Azerbaijani kolay gelsin to Balkan Turkish usage.","A man walking past a mechanic lying under a car says kolay gelsin without stopping; the mechanic grunts sağ ol from the floor, and neither expects the exchange to become a conversation."]}]},"context":{"countries":["TR"],"region":"Nationwide","continent":"asia","languages":["tr"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Turkish language","de":"Turkish language","en":"Turkish language"},"url":"https://en.wikipedia.org/wiki/Turkish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Turkey","de":"Culture of Turkey","en":"Culture of Turkey"},"url":"https://en.wikipedia.org/wiki/Culture_of_Turkey","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"رجل يمر بجانب ميكانيكي مستلقٍ تحت سيارة يقول كولاي غيلسين دون توقف؛ فيتمتم الميكانيكي من الأرض \"صاغ أول\"، ولا يتوقع أي منهما أن يتحول التبادل إلى محادثة.","de":"Ein Mann, der an einem Mechaniker vorbeigeht, der unter einem Auto liegt, sagt kolay gelsin, ohne stehen zu bleiben; der Mechaniker brummt vom Boden aus „sağ ol“, und keiner erwartet, dass daraus ein Gespräch wird.","en":"A man walking past a mechanic lying under a car says kolay gelsin without stopping; the mechanic grunts sağ ol from the floor, and neither expects the exchange to become a conversation."},"misunderstanding":{"ar":"قد يظن البعض أن العبارة دعوة للحديث أو مقدمة لطلب خدمة، لكنها في الواقع مجرد اعتراف بالجهد.","de":"Manche halten den Satz für eine Gesprächseinladung oder eine Vorstufe zu einer Bitte, doch er ist nur eine Anerkennung der Mühe.","en":"Some take the phrase as an invitation to chat or a prelude to a request, but it is simply an acknowledgment of effort."},"comparison":{"ar":"تشبه عبارة \"يعطيك العافية\" في العربية، لكنها لا تُقال بعد الطعام فقط بل لكل من يعمل.","de":"Ähnlich dem arabischen „yaʿtīk al-ʿāfiya“, aber nicht nur nach dem Essen, sondern für jede sichtbare Arbeit.","en":"Similar to the Arabic \"yaʿtīk al-ʿāfiya\" (may God give you health), but said for any visible work, not just after a meal."},"expression":{"original":"Kolay gelsin","language":"Türkçe (Turkish)","gloss":{"ar":"ليكن سهلًا (تُقال لمن يعمل)","de":"Möge es leicht sein (zu jemandem, der arbeitet)","en":"May it come easy (said to someone working)"},"usage":{"ar":"تُقال لمن يعمل، من النادل إلى المزارع، دون توقف أو انتظار رد.","de":"Zu jedem, der sichtbar arbeitet, im Vorbeigehen gesagt, ohne eine Antwort zu erwarten.","en":"Said to anyone visibly working, often in passing, without expecting a reply."},"transliteration":"kolay gelsin"}},{"id":"lng-039","version":2,"slug":"salemetsiz-be-kazakh-between-two-alphabets-and-two-languages","contentType":"note","category":"languages","title":{"ar":"كيف يعيش الكازاخ بين أبجديتين ولغتين","de":"Wie Kasachen zwischen zwei Alphabeten leben","en":"How Kazakhs live between two alphabets"},"deck":{"ar":"في كازاخستان، اللغة اليومية ليست خياراً واحداً بل تبديل مستمر بين الكازاخية والروسية، بين جيلين وأبجديتين.","de":"In Kasachstan ist die Alltagssprache keine feste Wahl, sondern ein ständiges Wechseln zwischen Kasachisch und Russisch, zwischen Generationen und Schriften.","en":"In Kazakhstan, everyday language is not a single choice but a constant switch between Kazakh and Russian, between generations and scripts."},"teaser":{"ar":"تحية واحدة تكفي لتبدأ الحديث، لكن اختيار اللغة بعدها يحكي الكثير عن الجيل والمدينة والموقف.","de":"Ein Gruß genügt, um ein Gespräch zu beginnen, doch die Wahl der Sprache danach verrät viel über Generation, Stadt und Situation.","en":"One greeting opens any conversation, but the language chosen afterwards says much about generation, city and situation."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تفتح الباب","paragraphs":["«ساليميتسيز بي» هي التحية الكازاخية الرسمية، بينما يستخدم الأصدقاء والنظراء الصيغة الأقصر «ساليم».","كازاخستان ثنائية اللغة في الممارسة: الكازاخية لغة الدولة والروسية لغة التواصل بين القوميات، ومعظم الكازاخ الحضريين يبدّلون بينهما يومياً.","يختلف الاستخدام sharply بين الشمال والجنوب وبين المدينة والريف؛ فالتقارير الذاتية في التعداد تبالغ في تقدير الكازاخية المنطوقة، وقد أُجّل الانتقال إلى الأبجدية اللاتينية أكثر من مرة."]},{"heading":"أصوات وأجيال","paragraphs":["انتقلت الكازاخية في القرن العشرين من العربية إلى اللاتينية ثم الكيريلية، وهي الآن في خطة تمتد عقداً للعودة إلى اللاتينية، وهو تغيير يقسم الأجيال.","تحتوي الكازاخية على حركات غائبة عن الروسية، تُكتب بالكيريلية بحروف مثل الألف ذات القوس والأو المشطوبة والواو ذات الخط المستقيم.","اختيار اللغة سياسي: شباب ألماتي يتحدثون الكازاخية في العمل أكثر فأكثر، بينما تبقى المدن الشمالية ذات أغلبية روسية."]}],"de":[{"heading":"Ein Gruß öffnet die Tür","paragraphs":["Salemetsiz be ist die formelle kasachische Begrüßung, während Freunde und Gleichgestellte das kürzere Salem verwenden.","Kasachstan ist in der Praxis zweisprachig: Kasachisch ist Staatssprache, Russisch Sprache der interethnischen Kommunikation, und die meisten städtischen Kasachen wechseln täglich den Code.","Der Sprachgebrauch unterscheidet sich stark zwischen Nord und Süd sowie Stadt und Land; Volkszählungen zur Selbstauskunft überschätzen gesprochenes Kasachisch, und der Wechsel zum lateinischen Alphabet wurde mehrfach verschoben."]},{"heading":"Laute und Generationen","paragraphs":["Im 20. Jahrhundert wechselte das Kasachische vom Arabischen über das Lateinische zum Kyrillischen und soll nun in einem Jahrzehntplan zum Lateinischen zurückkehren, eine Veränderung, die Generationen trennt.","Das Kasachische hat Vokale, die dem Russischen fehlen, im Kyrillischen geschrieben mit Buchstaben wie einem A mit Bogen, einem O mit Strich und einem U mit gerader Linie.","Die Sprachwahl ist politisch: Junge Kasachen in Almaty sprechen bei der Arbeit zunehmend Kasachisch, während nördliche Städte russisch geprägt bleiben."]}],"en":[{"heading":"A greeting opens the door","paragraphs":["Salemetsiz be is the formal Kazakh hello, while friends and equals use the shorter Salem.","Kazakhstan is bilingual in practice: Kazakh is the state language and Russian the language of interethnic communication, and most urban Kazakhs code-switch daily.","Language use differs sharply between north and south and between city and countryside; census self-reports overstate spoken Kazakh, and the Latin transition has been postponed more than once."]},{"heading":"Sounds and generations","paragraphs":["Kazakh moved from Arabic to Latin to Cyrillic in the twentieth century and is now under a decade-long plan to return to Latin, a change that divides generations.","Kazakh has vowels absent from Russian, written in Cyrillic with letters such as a with a bow, o with a bar and u with a straight line.","Language choice is political: young Kazakhs in Almaty increasingly speak Kazakh at work, while northern cities remain Russian-dominant."]}]},"context":{"countries":["KZ"],"region":"Nationwide, with a Russian-majority north","continent":"asia","languages":["kk","ru"],"period":"contemporary"},"tags":["languages","Nationwide, with a Russian-majority north"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kazakh language","de":"Kazakh language","en":"Kazakh language"},"url":"https://en.wikipedia.org/wiki/Kazakh_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kazakhstan","de":"Kazakhstan","en":"Kazakhstan"},"url":"https://en.wikipedia.org/wiki/Kazakhstan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يبدأ زميلان في مكتب بألماتي الاجتماع بالروسية، ثم ينتقلان إلى الكازاخية عند دخول المدير، ويعودان إلى الروسية في النقاش التقني لأن المصطلحات وصلت بالروسية.","de":"Zwei Kollegen in einem Büro in Almaty beginnen die Besprechung auf Russisch, wechseln ins Kasachische, als der Manager dazukommt, und kehren für die technische Diskussion zum Russischen zurück, weil das Vokabular auf Russisch kam.","en":"Two colleagues in an Almaty office start a meeting in Russian, switch to Kazakh when the manager joins and return to Russian for the technical discussion, because the vocabulary arrived in Russian."},"misunderstanding":{"ar":"يظن كثيرون أن ثنائية اللغة تعني إتقاناً متساوياً للغتين، لكن الواقع أن كل مجال حياتي له لغته المعتادة.","de":"Viele halten Zweisprachigkeit für gleiche Beherrschung beider Sprachen, doch tatsächlich hat jeder Lebensbereich seine gewohnte Sprache.","en":"Many assume bilingualism means equal command of both languages, but in reality each area of life has its habitual language."},"comparison":{"ar":"يشبه الأمر عائلة تستخدم لغة في المطبخ وأخرى في العمل، دون أن يعني ذلك أن إحداهما أقل قيمة.","de":"Es ähnelt einer Familie, die in der Küche die eine und bei der Arbeit die andere Sprache spricht, ohne dass eine davon weniger wert wäre.","en":"It resembles a family that speaks one language in the kitchen and another at work, without either being worth less."},"expression":{"original":"Сәлеметсіз бе","language":"Қазақ тілі (Kazakh)","gloss":{"ar":"مرحباً (رسمية، لشخص أكبر سناً)","de":"guten Tag (formell, zu einer älteren Person)","en":"hello (formal, to an older person)"},"usage":{"ar":"تُقال عند دخول مكان أو لقاء شخص أكبر أو رسمي، ويُردّ عليها بتحية مماثلة.","de":"Wird beim Betreten eines Raums oder bei der Begrüßung älterer und offizieller Personen gesagt und mit derselben Formel erwidert.","en":"Said when entering a room or greeting someone older or official, and answered with the same formula."},"transliteration":"salemetsiz be"}},{"id":"lng-040","version":2,"slug":"melmastia-the-pashtun-code-that-makes-a-guest-untouchable","contentType":"note","category":"communication","title":{"ar":"ملمستيا: كرم الضيافة كالتزام","de":"Melmastia: Gastfreundschaft als Pflicht","en":"Melmastia: Hospitality as Sacred Duty"},"deck":{"ar":"في جنوب أفغانستان وخيبر بختونخوا، الضيف لا يُمس حتى لو كان عدواً.","de":"In Südafghanistan und Khyber Pakhtunkhwa ist ein Gast unantastbar, selbst wenn er ein Feind ist.","en":"In southern Afghanistan and Khyber Pakhtunkhwa, a guest is untouchable even if he is an enemy."},"teaser":{"ar":"الضيف في البشتونwali ليس مجرد زائر، بل أمانة مقدسة تفرض على المضيف التضحية بكل شيء.","de":"Melmastia ist mehr als Höflichkeit: Es ist ein Ehrenkodex, der Familien zwingt, über ihre Verhältnisse zu leben.","en":"Melmastia is more than courtesy: it is a code that compels families to spend beyond their means to honor a visitor."},"readingMinutes":1,"sections":{"ar":[{"heading":"الضيف بين الحق والواجب","paragraphs":["ملمستيا هي الضيافة كالتزام: يجب إطعام الضيف وحمايته حتى لو كان عدواً لعائلة المضيف. هذا القانون العرفي، المعروف بالبشتونwali، يجعل من الضيف شخصاً لا يمكن المساس به.","وتتيح نناواتي طلب اللجوء بدخول بيت وطلب الحماية، والمضيف ملزم بمنحها. أما بدل فهي المعاملة بالمثل والانتقام: تُرد الجميل ويُنتقم من الظلم ما لم يحل مجلس الشيوخ النزاع.","وللضيافة عواقب عملية، فالعائلة الريفية تنفق فوق طاقتها لإطعام الزائر بدلاً من فقدان الشرف. ويختلف تطبيق هذا العرف بين المناطق والأجيال، إذ يلتزم به سكان المدن ودول المهجر رمزياً في كثير من الأحيان."]},{"heading":"العرف بين الدين والمجتمع","paragraphs":["البشتونwali قانون عرفي وليس كتاباً مقدساً، رغم أنه يوصف غالباً بلغة دينية، وتطبقه المجالس القبلية بشكل غير متساوٍ. وهذا يجعله عرضة للتغير بحسب السياق الاجتماعي.","دور المرأة فيه محل جدل ومتغير، مما يعكس توتراً بين التقاليد والتحولات الحديثة."]}],"de":[{"heading":"Der Gast zwischen Recht und Pflicht","paragraphs":["Melmastia ist Gastfreundschaft als Verpflichtung: Ein Gast muss verpflegt und geschützt werden, selbst wenn er ein Feind der Familie des Gastgebers ist. Dieses Gewohnheitsrecht, Paschtunwali genannt, macht den Gast unantastbar.","Nanawatai gewährt das Recht, durch Betreten eines Hauses Asyl zu suchen, und der Gastgeber muss es gewähren. Badal ist Gegenseitigkeit und Vergeltung: Gefälligkeiten werden erwidert, Unrecht wird gerächt, es sei denn, ein Ältestenrat schlichtet den Streit.","Die Gastregel hat praktische Folgen, denn eine ländliche Familie gibt mehr aus, als sie sich leisten kann, um einen Besucher zu bewirten, statt ihre Ehre zu verlieren. Regionale und generationelle Unterschiede zeigen sich darin, dass städtische Paschtunen und die Diaspora den Kodex oft nur symbolisch befolgen."]},{"heading":"Zwischen Religion und Gesellschaft","paragraphs":["Paschtunwali ist Gewohnheitsrecht, keine Schriftreligion, obwohl es oft in religiöser Sprache beschrieben wird, und Stammesräte wenden es ungleichmäßig an. Dadurch bleibt es flexibel und umstritten.","Die Rolle der Frauen darin ist umkämpft und im Wandel, was die Spannung zwischen Tradition und Moderne widerspiegelt."]}],"en":[{"heading":"The Guest Between Right and Duty","paragraphs":["Melmastia is hospitality as obligation: a guest must be fed and protected even if he is an enemy of the host's family. This customary law, known as Pashtunwali, makes the guest untouchable.","Nanawatai grants the right to seek asylum by entering a house and asking for refuge, and the host is bound to grant it. Badal is reciprocity and retribution: favors are returned, and wrongs are avenged unless a council of elders settles them.","The guest rule has practical consequences, because a rural family will spend beyond its means to feed a visitor rather than lose honour. Regional and generational variation is evident as urban Pashtuns and the diaspora often observe the code symbolically."]},{"heading":"Custom Between Faith and Society","paragraphs":["Pashtunwali is customary law rather than scripture, though it is often described in religious language, and tribal councils apply it unevenly. This makes it adaptable yet contested.","Women's roles within it are contested and changing, reflecting the tension between tradition and modern life."]}]},"context":{"countries":["AF","PK"],"region":"Southern Afghanistan and Khyber Pakhtunkhwa","continent":"asia","languages":["ps","fa","ur"],"period":"contemporary"},"tags":["communication","Southern Afghanistan and Khyber Pakhtunkhwa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pashtunwali","de":"Pashtunwali","en":"Pashtunwali"},"url":"https://en.wikipedia.org/wiki/Pashtunwali","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pashto","de":"Pashto","en":"Pashto"},"url":"https://en.wikipedia.org/wiki/Pashto","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"غريب تعطلت سيارته يستضيفه أهل في تلال خيبر ليلة، ويرفض المضيف الدفع صباحاً، فيترك الضيف هدية بدلاً من ذلك، لأن الدين لا يمكن تسويته مباشرة.","de":"Ein Fremder, dessen Auto liegen bleibt, wird von einer Familie in den Khyber-Bergen für eine Nacht aufgenommen; der Gastgeber lehnt am Morgen die Bezahlung ab, und der Gast hinterlässt stattdessen ein Geschenk, weil die Schuld nicht direkt beglichen werden kann.","en":"A stranger whose car breaks down is taken in for the night by a family in the Khyber hills; the host refuses payment the next morning and the guest leaves a gift instead, because the debt cannot be settled directly."},"misunderstanding":{"ar":"يظن البعض أن ملمستيا مجرد كرم ضيافة عادي، لكنها التزام صارم قد يعرض المضيف للخطر أو الفقر.","de":"Viele halten Melmastia für gewöhnliche Gastfreundschaft, doch es ist eine strenge Pflicht, die den Gastgeber in Gefahr oder Armut bringen kann.","en":"Some think melmastia is just ordinary hospitality, but it is a strict obligation that can put the host at risk or in poverty."},"comparison":{"ar":"مثل كرم الضيافة في ثقافات أخرى، لكن هنا الضيف يصبح مقدساً حتى لو كان عدواً، مما يرفع الالتزام إلى مستوى الشرف.","de":"Ähnlich der Gastfreundschaft in anderen Kulturen, doch hier wird der Gast sogar als Feind unantastbar, was die Verpflichtung auf eine Ehrensache hebt.","en":"Like hospitality in other cultures, but here the guest becomes sacred even if an enemy, elevating the obligation to a matter of honor."},"expression":{"original":"په خير راغلې","language":"پښتو (Pashto)","gloss":{"ar":"مرحباً (تقال للضيف)","de":"Willkommen (zu einem Gast gesagt)","en":"welcome (said to a guest)"},"usage":{"ar":"تقال عند استقبال الضيف للترحيب به وتأكيد حمايته.","de":"Wird bei der Begrüßung eines Gastes gesagt, um Willkommen und Schutz zu signalisieren.","en":"Said when receiving a guest to welcome them and affirm protection."},"transliteration":"pa kher raghle"}},{"id":"lng-041","version":2,"slug":"u-and-daw-burmese-honorifics-that-stand-where-a-surname-would-be","contentType":"note","category":"communication","title":{"ar":"يو وداو: ألقاب بورمية تحل محل اسم العائلة","de":"U und Daw: birmanische Ehrentitel statt Nachnamen","en":"U and Daw: Burmese honorifics that replace surnames"},"deck":{"ar":"في ميانمار، حيث لا توجد أسماء عائلية، تسبق ألقاب مثل يو وداو الأسماء الشخصية لتعكس الاحترام والعمر والمكانة.","de":"In Myanmar gibt es keine Familiennamen. Ehrentitel wie U und Daw stehen vor dem persönlichen Namen und zeigen Respekt, Alter und Status.","en":"In Myanmar, where family names don't exist, honorifics like U and Daw precede personal names to show respect, age, and social standing."},"teaser":{"ar":"كيف يعرف البورميون بعضهم دون ألقاب عائلية؟ يو وداو وكو وما تكشف نظامًا اجتماعيًا دقيقًا.","de":"Wie erkennen Burmesen einander ohne Nachnamen? U, Daw, Ko und Ma verraten ein fein abgestuftes soziales System.","en":"How do Burmese people identify each other without surnames? U, Daw, Ko, and Ma reveal a finely tuned social system."},"readingMinutes":1,"sections":{"ar":[{"heading":"ألقاب بدل الأسماء العائلية","paragraphs":["في ميانمار، لا تحمل الأسماء اسم عائلة. بدلاً من ذلك، يسبق البالغين لقب مثل يو (بمعنى السيد) للرجال أو داو (بمعنى السيدة) للنساء، كما في يو ثانت أو داو أونغ سان سو كي. وتُستخدم كو وما للشباب الأصغر سنًا، بينما تظهر ماونغ وتو في سجلات رسمية.","غالبًا ما يُخطئ الأجانب في اعتبار اللقب اسمًا أوليًا، فيُفهرس الشخص نفسه باسم ثانت في قاعدة بيانات وباسم يو ثانت في أخرى. هذا الالتباس يعكس اختلافًا عميقًا في بنية التسمية."]},{"heading":"الاحترام في الكلام اليومي","paragraphs":["تنتهي الجمل المهذبة بجزيئات تختلف حسب جنس المتحدث: خينبيا للرجال وشين للنساء، حتى ضمائر المتكلم نفسها صيغ متواضعة. هذا يعكس حساسية اجتماعية عالية في التواصل.","يختلف اختيار اللقب حسب العمر والسياق، ويستخدم البورميون في المنفى أعرافًا مختلفة، كما أن مجتمعات شان وكارين وتشين داخل ميانمار لها أنظمة مخاطبة خاصة بها."]}],"de":[{"heading":"Ehrentitel statt Familiennamen","paragraphs":["In Myanmar tragen Menschen keine Familiennamen. Stattdessen steht bei Erwachsenen ein Ehrentitel wie U (etwa Herr) für Männer oder Daw (etwa Frau) für Frauen vor dem persönlichen Namen, wie bei U Thant oder Daw Aung San Suu Kyi. Ko und Ma werden für jüngere Männer und Frauen verwendet, Maung und Thu erscheinen in formellen Dokumenten.","Im Ausland wird der Ehrentitel oft für einen Vornamen gehalten, sodass dieselbe Person in einer Datenbank als Thant und in einer anderen als U Thant geführt wird. Diese Verwechslung spiegelt ein grundlegend anderes Namenssystem wider."]},{"heading":"Höflichkeit im Alltag","paragraphs":["Höfliche Sätze enden mit Partikeln, die sich nach dem Geschlecht des Sprechers richten: khinbya für Männer und shin für Frauen. Sogar die Pronomen für „ich“ sind bescheidene Formen. Das zeigt eine hohe soziale Sensibilität in der Kommunikation.","Die Wahl des Ehrentitels hängt von Alter und Situation ab. Burmesen im Exil verwenden andere Konventionen, und die Shan-, Karen- und Chin-Gemeinschaften in Myanmar haben eigene Anredesysteme."]}],"en":[{"heading":"Honorifics instead of family names","paragraphs":["In Myanmar, people do not carry family names. Instead, adults are preceded by an honorific such as U (roughly Mr) for men or Daw (roughly Mrs) for women, as in U Thant or Daw Aung San Suu Kyi. Ko and Ma are used for younger men and women, while Maung and Thu appear in formal documents.","Abroad, the honorific is often mistaken for a first name, so the same person is indexed as Thant in one database and U Thant in another. This confusion reflects a fundamentally different naming system."]},{"heading":"Politeness in everyday speech","paragraphs":["Polite sentences end with particles that differ by speaker gender: khinbya for men and shin for women. Even the pronouns for 'I' are humble forms. This shows a high degree of social sensitivity in communication.","Honorific choices depend on age and setting. Burmese in exile use different conventions, and Shan, Karen, and Chin communities inside Myanmar have their own address systems."]}]},"context":{"countries":["MM"],"region":"Yangon, Mandalay and central Myanmar","continent":"asia","languages":["my","en"],"period":"contemporary"},"tags":["communication","Yangon, Mandalay and central Myanmar"],"sources":[{"organization":"Wikipedia","title":{"ar":"Burmese language","de":"Burmese language","en":"Burmese language"},"url":"https://en.wikipedia.org/wiki/Burmese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Burmese names","de":"Burmese names","en":"Burmese names"},"url":"https://en.wikipedia.org/wiki/Burmese_names","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عامل في منظمة غير حكومية أجنبية يكتب إلى مسؤول بورمي يتجنب اسم العائلة غير الموجود ويضع يو قبل الاسم؛ مخاطبته بـ «السيد ثانت» ستُفهم لكنها تميز الكاتب كأجنبي.","de":"Ein Mitarbeiter einer ausländischen NGO, der einem burmesischen Beamten schreibt, vermeidet den nicht existierenden Nachnamen und setzt U vor den Namen; ihn als Mr Thant anzusprechen wäre verständlich, kennzeichnet den Schreiber aber als Außenstehenden.","en":"A foreign NGO worker writing to a Burmese official avoids the nonexistent surname and puts U before the name; addressing him as Mr Thant would be understood but marks the writer as an outsider."},"misunderstanding":{"ar":"يعتقد الكثيرون خارج ميانمار أن «يو» اسم أول، مما يسبب ارتباكًا في الفهرسة والتوثيق.","de":"Viele außerhalb Myanmars halten „U“ für einen Vornamen, was zu Verwirrung bei der Indexierung und Dokumentation führt.","en":"Many outside Myanmar assume 'U' is a first name, causing confusion in indexing and documentation."},"comparison":{"ar":"على عكس العديد من الثقافات حيث اللقب العائلي ثابت، فإن اللقب البورمي يعكس العمر والجنس والمكانة الاجتماعية.","de":"Anders als in vielen Kulturen, in denen der Familienname konstant ist, spiegelt der birmanische Ehrentitel Alter, Geschlecht und sozialen Status wider.","en":"Unlike many cultures where the family name is constant, Burmese honorifics reflect age, gender, and social status."},"expression":{"original":"ကျေးဇူးတင်ပါတယ်","language":"မြန်မာဘာသာ (Burmese)","gloss":{"ar":"شكرًا لك","de":"Danke","en":"thank you"},"usage":{"ar":"تعبير شائع للشكر، يستخدم في المواقف اليومية.","de":"Häufiger Ausdruck des Dankes im Alltag.","en":"A common expression of thanks used in everyday situations."},"transliteration":"kyeizu tin ba de"}},{"id":"lng-042","version":2,"slug":"a-language-brought-back-to-the-dinner-table-hebrew-s-revival","contentType":"note","category":"languages","title":{"ar":"العبرية تعود إلى مائدة العشاء","de":"Hebräisch kehrt an den Esstisch zurück","en":"Hebrew Comes Back to the Dinner Table"},"deck":{"ar":"كيف صار لسانٌ كان للصلاة وحدها لغةَ حياةٍ يوميةٍ في إسرائيل","de":"Wie eine Sprache, die fast nur der Liturgie diente, wieder Alltag wurde","en":"How a language once reserved for prayer became ordinary household speech"},"teaser":{"ar":"من أواخر القرن التاسع عشر قاد إليعازر بن يهودا إحياء العبرية منطوقةً، فاحتاج البيت والسوق إلى كلمات جديدة.","de":"Ab dem späten 19. Jahrhundert führte Elieser Ben-Jehuda die Wiederbelebung des gesprochenen Hebräisch an – Küche und Markt brauchten neue Wörter.","en":"From the late nineteenth century Eliezer Ben-Yehuda led Hebrew's revival as a spoken tongue, and daily life needed new words fast."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمات تُصنع من جذور قديمة","paragraphs":["قاد إليعازر بن يهودا إحياء العبرية لغةً منطوقةً من أواخر القرن التاسع عشر، بعد نحو ألفي سنة كانت فيها لسانَ صلاةٍ بالأساس.","احتاجت الحياة الحديثة إلى مفردات، فأُعيد استخدام لفظ توراتي قديم للكهرباء، واشتُقّت كلمة الحاسوب من جذر يعني التفكير أو الحساب.","تُبنى معظم الكلمات العبرية من جذور ثلاثية، فكل صياغة جديدة يجب أن تدخل قالبًا يعرفه المتكلمون مسبقًا."]},{"heading":"أدب الحديث في الشارع","paragraphs":["لا تملك العبرية الحديثة صيغةَ تأدّبٍ واحدةً للمخاطبة، فيحمل التلطّفَ تعبير «بفاكاشا» مع النبرة والمستوى اللغوي.","والعربية لغة رسمية في إسرائيل، والعبرية تقترض منها: يلّا، صبابة، ووالله صارت كلماتٍ عاديةً.","يختلف هذا الاستعمال بين الأجيال والمناطق، فالشباب في المدن يخلطون أكثر، بينما تختلف وتيرة الاقتراض في المجتمعات المتشددة دينيًا."]}],"de":[{"heading":"Wörter aus alten Wurzeln","paragraphs":["Elieser Ben-Jehuda führte die Wiederbelebung des gesprochenen Hebräisch ab dem späten 19. Jahrhundert an, nach fast zwei Jahrtausenden vorwiegend liturgischen Gebrauchs.","Das moderne Leben verlangte neue Wörter: Für Elektrizität wurde ein altes biblisches Wort wiederverwendet, „Computer“ aus einer Wurzel für Denken oder Rechnen geprägt.","Die meisten hebräischen Wörter entstehen aus drei Konsonanten, jede Neuschöpfung muss in ein Muster passen, das Sprecher schon kennen."]},{"heading":"Höflichkeit im Tonfall","paragraphs":["Dem modernen Hebräisch fehlt ein einheitliches höfliches „Sie“; Höflichkeit tragen „bevakasha“ (bitte, gern geschehen), Intonation und Register.","Arabisch ist in Israel Amtssprache, und Hebräisch entlehnt daraus: yalla, sababa und walla sind gewöhnliche hebräische Wörter.","Je nach Region und Generation klingt das anders: Jüngere in den Städten mischen mehr, in streng religiösen Kreisen verläuft die Entlehnung zurückhaltender."]}],"en":[{"heading":"New words from old roots","paragraphs":["Eliezer Ben-Yehuda led Hebrew's revival as a spoken language from the late nineteenth century, after nearly two millennia of mainly liturgical use.","Modern life required new words, so electricity reused an ancient biblical term and computer was coined from a root meaning to think or calculate.","Hebrew builds most words from three-consonant roots, so every new coinage has to fit a pattern that speakers already recognise."]},{"heading":"Politeness carried by tone","paragraphs":["Modern Hebrew has no single polite you; politeness is carried by bevakasha (please, you are welcome) plus intonation and register.","Arabic is an official language in Israel and Hebrew borrows from it: yalla, sababa and walla are ordinary Hebrew.","Usage shifts by region and generation: younger city speakers mix more freely, while Haredi communities keep a different everyday register."]}]},"context":{"countries":["IL"],"region":"Israel","continent":"asia","languages":["he","ar","en"],"period":"contemporary"},"tags":["languages","Israel"],"sources":[{"organization":"Wikipedia","title":{"ar":"Revival of the Hebrew language","de":"Revival of the Hebrew language","en":"Revival of the Hebrew language"},"url":"https://en.wikipedia.org/wiki/Revival_of_the_Hebrew_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hebrew language","de":"Hebrew language","en":"Hebrew language"},"url":"https://en.wikipedia.org/wiki/Hebrew_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة إسرائيلية تتجادل حول العشاء بكلمتَي «يلّا» و«صبابة» العربيتين، في لغةٍ لم يكن لها متحدثون أصليون قبل مئة وخمسين سنة.","de":"Eine israelische Familie streitet beim Abendessen mit yalla und sababa, aus dem Arabischen entlehnten Wörtern, in einer Sprache ohne Muttersprachler vor hundertfünfzig Jahren.","en":"An Israeli family argues about dinner plans with yalla and sababa, words borrowed from Arabic, in a language that had no native speakers a hundred and fifty years ago."},"misunderstanding":{"ar":"يُبسَّط الإحياء كثيرًا: العبرية لم تتوقف عن القراءة والكتابة، والمعيار المنطوق استند إلى النطق السفاردي بينما شكّلت اليديشية اللكنة والتعابير.","de":"Die Wiederbelebung wird oft vereinfacht: Hebräisch blieb stets gelesen und geschrieben, der gesprochene Standard stützte sich auf sephardische Aussprache, während Jiddisch Akzent und Wendungen prägte.","en":"Revival is often oversimplified: Hebrew never stopped being read and written, and the spoken standard drew on Sephardi pronunciation while Yiddish shaped accent and idiom."},"comparison":{"ar":"كالعربية التي وسّعت معجمها بالاشتقاق من جذورها، تصنع العبرية كلماتها من جذور ثلاثية، لكنها تفتقر إلى صيغة تأدّبٍ موحّدة.","de":"Wie das Arabische seinen Wortschatz aus Wurzeln erweitert, bildet Hebräisch Wörter aus drei Konsonanten – kennt aber kein einheitliches höfliches „Sie“.","en":"Like Arabic expanding its vocabulary from roots, Hebrew coins words from three consonants — but it has no single polite you."},"expression":{"original":"יאללה","language":"עברית (Hebrew)","gloss":{"ar":"هيا / لنذهب","de":"los / komm schon","en":"come on / let's go"},"usage":{"ar":"تعبير يومي شائع في البيت والشارع، مأخوذ من العربية.","de":"Alltäglicher Ausdruck zu Hause und auf der Straße, aus dem Arabischen entlehnt.","en":"Everyday expression at home and in the street, borrowed from Arabic."},"transliteration":"yalla"}},{"id":"lng-043","version":2,"slug":"duzen-and-siezen-the-german-moment-when-a-stranger-becomes-a-du","contentType":"note","category":"communication","title":{"ar":"التبديل بين du وSie في ألمانيا","de":"Duzen und Siezen: Der Moment des Übergangs","en":"Duzen and siezen: when a stranger becomes a du"},"deck":{"ar":"اختيار الضمير ليس تفصيلاً صغيراً، بل يحدد مسافة اجتماعية دقيقة.","de":"Die Wahl zwischen du und Sie ist kein Small Talk, sondern eine soziale Markierung.","en":"The choice between du and Sie is not small talk; it marks social distance precisely."},"teaser":{"ar":"في ألمانيا، الانتقال من Sie إلى du قرار اجتماعي حساس، يقترحه عادة الأكبر أو الأعلى مقاماً.","de":"In Deutschland entscheidet die Wahl zwischen du und Sie über Nähe und Distanz – und der Wechsel will gelernt sein.","en":"In Germany, switching from Sie to du is a delicate social decision, usually proposed by the older or senior person."},"readingMinutes":1,"sections":{"ar":[{"heading":"متى يُعرض التبديل؟","paragraphs":["في ألمانيا، ينقسم ضمير المخاطب بين du (غير الرسمي) وSie (الرسمي، جمع نحوياً). الاختيار ليس حديثاً جانبياً، بل يحدد العلاقة. زملاء عملوا معاً سنوات قد يبقون على Sie، بينما جار لم تقابله قد يعرض du على السلالم.","العرض يأتي عادة من الأكبر أو الأعلى مقاماً، بعبارة Wollen wir uns duzen؟ (هل ننتقل إلى du؟). الرفض ممكن دون إحراج. يجب توافق الفعل والضمير: Sie kommen وdu kommst يتبعان النمط نفسه لكنهما عالمين اجتماعيين مختلفين."]},{"heading":"فروق إقليمية وجيلية","paragraphs":["في شرق ألمانيا والمناطق الجنوبية ذات الطبقة العاملة، يُستخدم du أبكر من بيئات العمل الشمالية. الشباب الألمان يبدلون أسرع من آبائهم. لا توجد قاعدة وطنية: الشركات والمناطق والفئات العمرية تختلف بحدة، والسياح الذين يبدؤون بـSie نادراً ما يخطئون، بينما المتعلمون الذين يبدؤون بـdu كثيراً ما يخطئون."]}],"de":[{"heading":"Wer bietet den Wechsel an?","paragraphs":["Im Deutschen trennt die zweite Person zwischen du (vertraut) und Sie (formell, grammatisch Plural). Die Wahl ist kein optionales Geplänkel. Kollegen, die jahrelang zusammenarbeiten, bleiben oft beim Sie, während ein nie getroffener Nachbar im Treppenhaus das Du anbietet.","Der Wechsel wird normalerweise von der älteren oder ranghöheren Person vorgeschlagen, oft mit „Wollen wir uns duzen?“. Eine Ablehnung ist möglich. Verben und Pronomen müssen übereinstimmen: Sie kommen und du kommst gehören zum selben Satzmuster, aber zu verschiedenen sozialen Welten."]},{"heading":"Regionale und generationelle Unterschiede","paragraphs":["In Ostdeutschland und südlichen Arbeitermilieus wird du früher verwendet als in nördlichen Berufsfeldern. Jüngere Deutsche wechseln schneller als ihre Eltern. Eine nationale Regel gibt es nicht: Unternehmen, Regionen und Altersgruppen unterscheiden sich stark. Touristen, die standardmäßig Sie verwenden, liegen selten falsch; Lernende, die standardmäßig du verwenden, oft schon."]}],"en":[{"heading":"Who offers the switch?","paragraphs":["German splits the second person between du (familiar) and Sie (formal, grammatically plural), and the choice is not optional small talk. Colleagues who have worked together for years may still use Sie, while a neighbour you have never met may offer du on the stairs.","The switch is normally proposed by the older or senior person, often with Wollen wir uns duzen? (shall we use du), and refusal is possible. Verbs and pronouns must agree: Sie kommen and du kommst belong to the same sentence pattern but different social worlds."]},{"heading":"Regional and generational variation","paragraphs":["East German and southern working-class settings often use du earlier than northern professional ones, and younger Germans switch faster than their parents did. There is no national rule: companies, regions and age groups differ sharply, and tourists who default to Sie are rarely wrong while learners who default to du often are."]}]},"context":{"countries":["DE"],"region":"Nationwide, strongest in offices and among neighbours","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in offices and among neighbours"],"sources":[{"organization":"Wikipedia","title":{"ar":"German language","de":"German language","en":"German language"},"url":"https://en.wikipedia.org/wiki/German_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفلة عيد ميلاد مكتب في بون، يقول مدير لموظف جديد بعد شهرين إننا نستطيع استخدام du؛ يجيبه الموظف بـdu فوراً، ثم يعود إلى Sie في الصباح التالي ويُصحح بلطف.","de":"Auf einer Weihnachtsfeier in Bonn sagt ein Manager nach zwei Monaten zu einem neuen Mitarbeiter, sie könnten sich duzen; der Mitarbeiter antwortet sofort mit du, wechselt am nächsten Morgen zurück zum Sie und wird sanft korrigiert.","en":"At a Bonn office Christmas party a manager says we can duzen to a new hire after two months; the hire answers with du immediately, then reverts to Sie the next morning and is gently corrected."},"misunderstanding":{"ar":"الاعتقاد أن du أكثر ودية دائماً؛ في بعض السياقات المهنية قد يُعتبر تجاوزاً.","de":"Die Annahme, du sei immer freundlicher; im Beruf kann es als Grenzüberschreitung gelten.","en":"Assuming du is always friendlier; in professional settings it can be seen as overstepping."},"comparison":{"ar":"في العربية، تختلف صيغ المخاطبة حسب العمر والجنس والمنطقة، لكن التبديل أقل مؤسسية من الألمانية.","de":"Im Arabischen variiert die Anrede nach Alter, Geschlecht und Region, aber der Wechsel ist weniger institutionalisiert als im Deutschen.","en":"In Arabic, address forms vary by age, gender and region, but the switch is less institutionalised than in German."},"expression":{"original":"Wollen wir uns duzen?","language":"Deutsch (German)","gloss":{"ar":"هل ننتقل إلى du مع بعضنا؟","de":"Shall we switch to du with each other?","en":"Shall we switch to du with each other?"},"usage":{"ar":"تُقال عند عرض الانتقال من Sie إلى du، عادة من الأكبر أو الأعلى مقاماً.","de":"Wird verwendet, um den Wechsel von Sie zu du anzubieten, meist von der älteren oder ranghöheren Person.","en":"Used to offer the switch from Sie to du, typically by the older or senior person."},"transliteration":"Wollen wir uns duzen?"}},{"id":"lng-044","version":2,"slug":"kaixo-basque-greets-in-a-language-that-has-no-living-relatives","contentType":"note","category":"languages","title":{"ar":"كايكسو: تحية لغة بلا أقارب أحياء","de":"Kaixo: Ein Gruß ohne lebende Verwandte","en":"Kaixo: A Greeting From a Language Alone"},"deck":{"ar":"في بلاد الباسك، التحية اليومية كلمة قصيرة تحمل خلفها تاريخاً لغوياً فريداً وعلاقات اجتماعية دقيقة.","de":"Im Baskenland trägt ein kurzes Alltagswort eine einzigartige Sprachgeschichte und ein feines Gespür für soziale Nähe.","en":"In the Basque Country, a short everyday word carries a singular linguistic history and a fine sense of social distance."},"teaser":{"ar":"كلمة كايكسو هي التحية اليومية في لغة الباسك، لغة معزولة لا تجد لها أقارب، ومع ذلك يعيشها الناس كل يوم.","de":"Kaixo ist der baskische Alltagsgruß, in einer Sprache ohne nachweisbare Verwandte, die Menschen täglich lebendig halten.","en":"Kaixo is the everyday Basque hello, spoken in a language with no demonstrable relatives, and people keep it alive daily."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يحيّي الناس بعضهم","paragraphs":["يستخدم سكان بلاد الباسك كلمة كايكسو كتحية يومية، وكلمة أغور للوداع، فيقولونها للغرباء وللكبار وفي نهاية السهرة. أما صيغة المخاطبة المألوفة فهي هي مع الأصدقاء المقربين والأطفال، بينما زو هي الصيغة المهذبة العامة وزويك للجمع.","تختلف هذه الاختيارات بين الأجيال والمناطق، فالشباب في المدن ينتقلون بسهولة بين الباسكية والإسبانية أو الفرنسية، بينما يحافظ كبار الريف على صيغ محلية أقدم."]},{"heading":"لغة صمدت في الجبال","paragraphs":["صمدت الباسكية في الوديان الجبلية والمزارع حيث هيمنت اللغات المشتقة من اللاتينية في المدن، وتختلف لهجات الساحل اختلافاً واضحاً.","في الستينيات صُنعت لغة معيارية موحّدة تُدرَّس اليوم في المدارس، لكن بعض المتحدثين الريفيين الأكبر سناً ما زالوا يتحدثون أصنافهم المحلية.","تظل هذه اللغة معزولة بلا أقارب مثبتين، وقواعدها تستخدم حالة الفاعل المميَّز، فيأخذ فاعل الفعل المتعدي نهاية مختلفة."]}],"de":[{"heading":"Wie Menschen einander begrüßen","paragraphs":["Im Baskenland grüßt man mit kaixo, verabschiedet sich mit agur, gegenüber Fremden, Älteren oder am Ende des Abends. Das vertraute Du ist hi für enge Freunde und Kinder, während zu die allgemeine höfliche Form und zuek der Plural ist.","Diese Wahl unterscheidet sich regional und generationell: Jüngere in den Städten wechseln mühelos zwischen Baskisch und Spanisch oder Französisch, ältere Landbewohner halten an lokalen Formen fest."]},{"heading":"Eine Sprache, die in Tälern überlebte","paragraphs":["Das Baskische überlebte in Bergtälern und Bauernhäusern, während in den Städten lateinisch geprägte Sprachen dominierten, und die Küstendialekte unterscheiden sich deutlich.","In den 1960er Jahren entstand das standardisierte euskara batua, das heute in Schulen gelehrt wird, doch ältere ländliche Sprecher verwenden weiterhin ihre lokalen Varietäten.","Die Sprache bleibt ein Isolat ohne nachweisbare Verwandte, und ihre Grammatik nutzt den Ergativ, sodass das Subjekt eines transitiven Verbs eine andere Endung trägt."]}],"en":[{"heading":"How People Greet Each Other","paragraphs":["In the Basque Country people say kaixo as the everyday hello and agur as goodbye, with strangers, elders or at the end of the night. The familiar you is hi, used with close friends and children, while zu is the general polite form and zuek the plural.","These choices vary by region and generation: younger city speakers move easily between Basque and Spanish or French, while older rural speakers keep older local forms."]},{"heading":"A Language That Survived in Valleys","paragraphs":["Basque survived in mountain valleys and farmhouses while Latin-based languages dominated the towns, and the coastal dialects differ markedly.","In the 1960s the standardised euskara batua was created and is now taught in schools, though older rural speakers still speak local varieties.","The language remains an isolate with no demonstrable relatives, and its grammar uses ergative case, so the subject of a transitive verb takes a different ending."]}]},"context":{"countries":["ES","FR"],"region":"Basque Country (Bilbao, San Sebastian, Bayonne)","community":"Basque speakers","continent":"europe","languages":["eu","es","fr"],"period":"contemporary"},"tags":["languages","Basque Country (Bilbao, San Sebastian, Bayonne)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Basque language","de":"Basque language","en":"Basque language"},"url":"https://en.wikipedia.org/wiki/Basque_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Basques","de":"Basques","en":"Basques"},"url":"https://en.wikipedia.org/wiki/Basques","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حانة في سان سيباستيان يحيّي زبون منتظم النادل بكلمة كايكسو، ويحيّي زبوناً لا يعرفه بعبارة إيغون أون أي صباح الخير، لأن كايكسو تفترض علاقة لا تفترضها التحية الثانية.","de":"In einer Bar in San Sebastián begrüßt ein Stammgast den Barkeeper mit kaixo und einen unbekannten Gast mit egun on (guten Morgen), weil kaixo eine Beziehung voraussetzt, die der zweite Gruß nicht braucht.","en":"In a San Sebastian bar a regular greets the barman with kaixo and a customer he does not know with egun on (good morning), because kaixo presupposes a relationship that the second greeting does not."},"misunderstanding":{"ar":"يظن بعض الزوار أن كايكسو مرادف بسيط لكلمة مرحباً في كل السياقات، لكنها تفترض نوعاً من الألفة أو الاعتياد لا تناسب كل لقاء أول.","de":"Manche Besucher halten kaixo für ein einfaches Synonym von hallo in jeder Lage, doch es setzt eine gewisse Vertrautheit voraus, die bei einer ersten Begegnung fehlen kann.","en":"Some visitors assume kaixo is a simple synonym for hello in every situation, but it presumes a degree of familiarity that a first encounter may not have."},"comparison":{"ar":"حيث تستخدم الإسبانية هولا والفرنسية بونجور في معظم اللقاءات، يوزّع متحدثو الباسك تحياتهم بحسب العلاقة والعمر والوقت من اليوم.","de":"Wo Spanisch mit hola und Französisch mit bonjour fast jede Begegnung abdecken, verteilen baskische Sprecher ihre Grüße nach Beziehung, Alter und Tageszeit.","en":"Where Spanish hola and French bonjour cover almost any encounter, Basque speakers distribute their greetings by relationship, age and time of day."},"expression":{"original":"Kaixo","language":"Euskara (Basque)","gloss":{"ar":"مرحباً","de":"hallo","en":"hello"},"usage":{"ar":"تحية يومية غير رسمية تُقال للغرباء والجيران وفي نهاية السهرة عند الوداع بكلمة أغور.","de":"Alltäglicher, lockerer Gruß unter Fremden, Nachbarn und am Ende des Abends beim Abschied mit agur.","en":"Everyday, informal greeting used with strangers, neighbours and at the end of the night when parting with agur."},"transliteration":"kaixo"}},{"id":"lng-045","version":2,"slug":"gezellig-the-dutch-word-for-a-room-that-is-going-well","contentType":"detail","category":"languages","title":{"ar":"Gezellig: كلمة هولندية لجو يسود المكان","de":"Gezellig: das niederländische Wort für gelungene Geselligkeit","en":"Gezellig: The Dutch word for a room going well"},"deck":{"ar":"كلمة تصف الحالة الاجتماعية لا الأشياء، وتربط الراحة بالألفة.","de":"Es beschreibt Situationen, keine Dinge, und verbindet Behaglichkeit mit sozialer Leichtigkeit.","en":"It describes situations, not objects, and blends cosiness with social ease."},"teaser":{"ar":"في هولندا، الكلمة لا تصف الكرسي بل الجلسة. تعرف كيف تصنع الأمسية الناجحة بكلمة واحدة.","de":"In den Niederlanden beschreibt das Wort nicht den Stuhl, sondern den Abend. Ein Wort fasst zusammen, ob ein Treffen gelingt.","en":"In the Netherlands, the word doesn't describe the chair but the evening. One term captures whether a gathering succeeds."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه Gezellig حقًا","paragraphs":["Gezellig تصف المواقف لا الأشياء: مقهى أو أمسية أو زيارة يمكن أن تكون gezellig، أما كرسي جميل فلا. تجمع الكلمة بين الدفء الاجتماعي والسهولة، والاسم gezelligheid يشير إلى الصفة نفسها لا إلى نشاط معين.","تأتي من الجذر نفسه كلمة gezelschap (رفقة)، ما يربطها بفكرة أن تكون في صحبة الآخرين لا بمجرد الشعور بالراحة. وتختلف الكلمة قليلاً في اللهجة الفلمنكية، كما أن الأجيال الشابة تستخدمها بتحفظ أكبر."]},{"heading":"كلمة تُلخص المساء كله","paragraphs":["تُستخدم الكلمة صفةً وحالاً ومجامل��ً. ووصف حفلة بأنها niet gezellig حكم خطير يُنطق بلطف. الحياة الاجتماعية الهولندية تعتبر الوقت المشترك شيئًا يُنتج بنشاط، وgezellig هي شرط النجاح لذلك الجهد."]}],"de":[{"heading":"Was gezellig wirklich meint","paragraphs":["Gezellig gilt für Situationen, nicht für Gegenstände: Ein Café, ein Abend oder ein Besuch können gezellig sein, ein schöner Stuhl nicht. Das Wort verbindet Gemütlichkeit mit sozialer Leichtigkeit; das Substantiv gezelligheid benennt die Eigenschaft selbst, nicht eine bestimmte Aktivität.","Derselbe Wortstamm steckt in gezelschap (Gesellschaft), was die Verbindung zur Idee der Gemeinschaft betont, nicht bloß zum Komfort. Regional und generationell wird das Wort unterschiedlich verwendet: In Flandern klingt es etwas anders, und jüngere Sprecher nutzen es zurückhaltender."]},{"heading":"Ein Wort für den ganzen Abend","paragraphs":["Man verwendet es als Adjektiv, Adverb und Kompliment. Eine Party als niet gezellig zu bezeichnen, ist ein ernstes Urteil, mild vorgetragen. Das niederländische Sozialleben versteht gemeinsame Zeit als etwas, das aktiv hergestellt wird, und gezellig ist die Erfolgsbedingung dieses Bemühens."]}],"en":[{"heading":"What gezellig really means","paragraphs":["Gezellig applies to situations rather than objects: a cafe, an evening or a visit can be gezellig, and a nice chair cannot. It combines cosiness with social ease, and the noun gezelligheid names the quality itself rather than any specific activity.","The same root gives gezelschap (company), linking the word to being in company rather than being comfortable. Usage varies by region and generation: Flemish Dutch uses it slightly differently, and younger speakers often apply it more sparingly."]},{"heading":"A word for the whole evening","paragraphs":["The word is used as an adjective, an adverb and a compliment. Calling a party niet gezellig is a serious verdict delivered mildly. Dutch social life treats shared time as something to be actively produced, and gezellig is the success condition of that effort."]}]},"context":{"countries":["NL"],"region":"Nationwide","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gezelligheid","de":"Gezelligheid","en":"Gezelligheid"},"url":"https://en.wikipedia.org/wiki/Gezelligheid","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Dutch language","de":"Dutch language","en":"Dutch language"},"url":"https://en.wikipedia.org/wiki/Dutch_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميلة هولندية ترفض حانة صاخبة وتقترح غرفة معيشة صغيرة مع القهوة؛ وعندما تُسأل عن السبب تقول ببساطة إنها ستكون أكثر gezellig، ويفهم الجميع طبيعة الأمسية كلها بكلمة واحدة.","de":"Eine niederländische Kollegin lehnt eine laute Bar ab und schlägt ein kleines Wohnzimmer mit Kaffee vor; auf die Frage nach dem Grund sagt sie nur, es werde gezelliger sein, und alle verstehen den ganzen Abend in einem Wort.","en":"A Dutch colleague declines a loud bar and suggests a small living room with coffee; when asked why, she says simply that it will be more gezellig, and everyone understands the whole evening in one word."},"misunderstanding":{"ar":"Gezellig معيار بقدر ما هي شعور، وبعض الهولنديين يجدون ضغط إنتاجها مرهقًا؛ كما أن السياح يفرطون في استخدامها.","de":"Gezellig ist ebenso eine Norm wie ein Gefühl; manche Niederländer empfinden den Druck, es herzustellen, als anstrengend. Touristen verwenden das Wort oft zu häufig.","en":"Gezellig is a norm as much as a feeling, and some Dutch people find the pressure to produce it tiring; tourists often overuse it."},"comparison":{"ar":"في العربية، قد نصف الجلسة بـ«ونسة» أو «جو رايق»، لكن gezellig تربط الراحة بالرفقة نفسها، لا بالمكان أو النشاط.","de":"Im Deutschen gibt es „gemütlich“ und „gesellig“, aber gezellig vereint beides und bezieht sich fast immer auf die Situation, nicht auf den Raum.","en":"English has 'cosy' and 'convivial', but gezellig fuses them and almost always evaluates a shared situation, not a physical space."},"expression":{"original":"Gezellig","language":"Nederlands (Dutch)","gloss":{"ar":"مريح ومؤنس (للموقف)","de":"gemütlich und gesellig (von einer Situation)","en":"cosy and convivial (of a situation)"},"usage":{"ar":"تُستخدم لوصف جو اجتماعي ناجح ومريح، غالبًا كصفة أو حال أو مجاملة.","de":"Wird verwendet, um eine gelungene, entspannte soziale Situation zu beschreiben, oft als Adjektiv, Adverb oder Kompliment.","en":"Used to describe a successful, relaxed social situation, often as an adjective, adverb or compliment."},"transliteration":"gezellig"}},{"id":"lng-046","version":2,"slug":"hygge-the-danish-word-for-deliberately-lowering-the-room-s-temperature-of-excite","contentType":"detail","category":"languages","title":{"ar":"هيغّة: دفء دانماركي بلا جدول","de":"Hygge: Dänemarks Wort für Ruhe ohne Plan","en":"Hygge: the Danish word for lowering excitement"},"deck":{"ar":"كلمة تصف معيّة هادئة في ضوء خفيف، يمارسها الدنماركيون كفعل لا كمفهوم فقط.","de":"Das Wort meint ruhiges, sicheres Beisammensein, meist drinnen, bei wenig Licht, mit Essen und ohne Zeitplan.","en":"The term names calm, safe togetherness, usually indoors, with low light, food and no schedule, and Danes treat it as an activity."},"teaser":{"ar":"في الدنمارك ليست هيغّة ديكوراً بل اتفاقاً اجتماعياً على خفض حرارة الإثارة وإبقاء الهواتف بعيداً.","de":"In Dänemark ist Hygge kein Einrichtungsstil, sondern eine soziale Absprache: weniger Lärm, weniger Telefone, mehr gemeinsames Dasein.","en":"In Denmark hygge is not a decor style but a social agreement: fewer phones, quieter voices, and an evening deliberately kept small."},"readingMinutes":1,"sections":{"ar":[{"heading":"معيّة هادئة تُرتَّب عمداً","paragraphs":["تشير هيغّة إلى معيّة آمنة وهادئة، غالباً في الداخل، بضوء خفيف وطعام بلا جدول. وهي فعل واسم في الاستعمال اليومي، إذ يتحدث الدنماركيون عن هيغّة سيغ كفعل يُرتَّب ويُخطَّط له.","ثمة قواعد اجتماعية: الجدال الصاخب والهواتف وحديث العمل تفسد الجو، والضيف الذي يصل خالي اليدين قد يُطلب منه أن يشارك بقصة. وتختلف الممارسة بين الأجيال والمناطق، فالنسخة الحضرية الشابة أكثر تهكماً على تسويق الكلمة."]},{"heading":"سوء فهم عالمي لمساء عادي","paragraphs":["دخلت الكلمة صحافة أسلوب الحياة العالمية في العقد الثاني من الألفية، ويصف الدنماركيون ذلك غالباً بأنه سوء فهم لمساء عادي بسيط.","تُربط هيغّة بالثقة الاجتماعية الدنماركية وبالشتاء الطويل المظلم، لكن هذا تفسير وطني أكثر منه سبباً مُثبتاً. مثال: أسرة في كوبنهاغن تلغي عشاءها بسبب المطر وتبقى بالشموع والخبز ولعبة طاولة، وتسمي المساء هيغّة رغم أنه لم يُخطَّط له."]}],"de":[{"heading":"Beisammensein, das man verabredet","paragraphs":["Hygge benennt ein ruhiges, sicheres Beisammensein, meist drinnen, meist bei wenig Licht, mit Essen und ohne Zeitplan. Im Alltag ist es Verb und Substantiv zugleich; Dänen sprechen von hygge sig als einer Tätigkeit, die man organisieren kann.","Es gelten soziale Regeln: laute Streitgespräche, Telefone und Arbeitsgespräche können die Stimmung brechen, und wer als Gast nichts mitbringt, wird vielleicht um eine Geschichte gebeten. Regional und zwischen Generationen unterscheidet sich die Praxis spürbar, jüngere Städter spotten über die Kommerzialisierung."]},{"heading":"Ein weltweites Missverständnis","paragraphs":["In den 2010er Jahren kam das Wort in die globale Lifestyle-Publizistik; Dänen beschreiben das oft als Missverständnis eines ganz gewöhnlichen Abends.","Hygge wird mit dänischem Sozialvertrauen und den langen dunklen Wintern verbunden, doch das ist eine nationale Erklärung, keine bewiesene Ursache. Beispiel: Eine Kopenhagener Familie sagt das Abendessen wegen Regens ab, bleibt mit Kerzen, Brot und einem Brettspiel zu Hause und nennt den Abend hygge, obwohl nichts Besonderes geplant war."]}],"en":[{"heading":"Togetherness you arrange on purpose","paragraphs":["Hygge names a calm, safe togetherness, usually indoors, usually with low light, food and no schedule. In practice it is a verb as well as a noun, and Danes talk about hygge sig as an activity to be arranged.","Social rules apply: loud arguments, phones and work talk can break the atmosphere, and a guest who brings nothing may still be asked to contribute a story. The practice varies by region and generation, with younger urban Danes mocking its commercial packaging."]},{"heading":"A global misunderstanding","paragraphs":["The word entered global lifestyle publishing in the 2010s, which Danes often describe as a misunderstanding of an ordinary evening.","Hygge is linked to Danish social trust and to the long dark winters, though the connection is a national explanation rather than a proven cause. Example: a Copenhagen family cancels dinner plans because of rain and stays in with candles, bread and a board game, calling the evening hygge even though nothing was planned as special."]}]},"context":{"countries":["DK"],"region":"Nationwide","continent":"europe","languages":["da"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hygge","de":"Hygge","en":"Hygge"},"url":"https://en.wikipedia.org/wiki/Hygge","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Danish language","de":"Danish language","en":"Danish language"},"url":"https://en.wikipedia.org/wiki/Danish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"أسرة في كوبنهاغن تلغي عشاءها بسبب المطر وتبقى بالشموع والخبز ولعبة طاولة، وتسمي المساء هيغّة رغم أنه لم يُخطَّط له.","de":"Eine Kopenhagener Familie sagt das Abendessen wegen Regens ab, bleibt mit Kerzen, Brot und einem Brettspiel zu Hause und nennt den Abend hygge, obwohl nichts Besonderes geplant war.","en":"A Copenhagen family cancels dinner plans because of rain and stays in with candles, bread and a board game, calling the evening hygge even though nothing was planned as special."},"misunderstanding":{"ar":"كثيرون خارج الدنمارك يظنونها وصفة ديكور أو شراءً للشموع، بينما هي اتفاق على خفض الإثارة لا على شراء شيء.","de":"Viele außerhalb Dänemarks halten Hygge für eine Dekor-Anleitung oder einen Kerzenkauf, dabei geht es um weniger Aufregung, nicht um mehr Besitz.","en":"Outsiders often read hygge as a shopping list of candles and blankets, when it is an agreement to lower the room's temperature of excitement."},"comparison":{"ar":"حيث تُملأ الأمسيات بالضوضاء والالتزامات، تقترح هيغّة العكس: ضوء أقل، جدول أقل، وحضور أكبر.","de":"Wo anderswo Abende mit Lärm und Verpflichtungen gefüllt werden, schlägt Hygge das Gegenteil vor: weniger Licht, weniger Plan, mehr Anwesenheit.","en":"Where other evenings fill with noise and obligations, hygge proposes the reverse: less light, less schedule, more presence."},"expression":{"original":"Hygge","language":"Dansk (Danish)","gloss":{"ar":"معيّة دافئة مقصودة","de":"bewusstes gemütliches Beisammensein","en":"deliberate cosy togetherness"},"usage":{"ar":"تُقال عن مساء بيتي هادئ مع شموع وطعام وأحاديث بلا التزامات.","de":"Für einen ruhigen Abend zu Hause mit Kerzen, Essen und Gesprächen ohne Verpflichtungen.","en":"Said of a quiet evening at home with candles, food and talk that carries no obligations."},"transliteration":"hygge"}},{"id":"lng-047","version":2,"slug":"the-du-reform-how-sweden-abolished-titles-in-a-decade","contentType":"note","category":"languages","title":{"ar":"إصلاح du: كيف تخلّت السويد عن الألقاب في عقد واحد","de":"Die du-Reform: Wie Schweden die Titel abschaffte","en":"The du reform: Sweden's rapid shift away from titles"},"deck":{"ar":"في أواخر الستينيات، تحوّل السويديون من مخاطبة الرؤساء بصيغة الغائب إلى du، في تغيير لغوي عميق رافق توسّع دولة الرفاهية.","de":"In den späten 1960er Jahren wechselten die Schweden von der dritten Person zur du-Anrede – ein tiefgreifender Sprachwandel, begleitet vom Ausbau des Wohlfahrtsstaates.","en":"In the late 1960s, Swedes moved from third-person titles to du, a profound linguistic change that accompanied the expansion of the welfare state."},"teaser":{"ar":"لم يكن التحول إلى du مجرد تغيير في الكلمات، بل كان جزءاً من تحول ديمقراطي أوسع في أماكن العمل السويدية.","de":"Die Umstellung auf du war nicht nur ein Wortwechsel, sondern Teil einer breiteren Demokratisierung der schwedischen Arbeitswelt.","en":"The switch to du was not just a change of words but part of a wider democratisation of Swedish workplaces."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الألقاب إلى du","paragraphs":["حتى الستينيات، كان السويديون يخاطبون من هم أعلى منهم مكانة بصيغة الغائب، مثل 'هل يرغب المدير في القهوة؟' بدلاً من استخدام du أو ni. كان هذا النظام يعكس تسلسلاً هرمياً صارماً في المجتمع.","في أواخر الستينيات، جعل إصلاح du من du الخيار الافتراضي في معظم المواقف. دفع هذا التغيير الإعلاميون والنقابات والقطاع العام المتوسع، مما سرّع تحولاً ثقافياً كبيراً."]},{"heading":"التحول الديمقراطي","paragraphs":["خلال عقد واحد تقريباً، انهار نظام الألقاب القديم. اليوم، مخاطبة مدير أو أستاذ سويدي بـ ni تبدو بعيدة أو قديمة. كان الإصلاح جزءاً من ديمقراطية أوسع في أماكن العمل، وتزامن مع توسع دولة الرفاهية."]}],"de":[{"heading":"Von Titeln zu du","paragraphs":["Bis in die 1960er Jahre redeten Schweden Vorgesetzte in der dritten Person an („Möchte der Direktor Kaffee?“) statt mit du oder ni. Dieses System spiegelte eine strenge gesellschaftliche Hierarchie wider.","In den späten 1960er Jahren machte die du-Reform du in fast allen Situationen zur Standardanrede. Vorangetrieben von Medien, Gewerkschaften und dem expandierenden öffentlichen Sektor beschleunigte sich der kulturelle Wandel."]},{"heading":"Demokratisierung","paragraphs":["Innerhalb etwa eines Jahrzehnts brach das alte Titelsystem zusammen. Heute klingt es distanziert oder veraltet, einen schwedischen Manager oder Professor mit ni anzureden. Die Reform war Teil einer breiteren Demokratisierung der Arbeitsplätze und fiel mit dem Ausbau des Wohlfahrtsstaates zusammen."]}],"en":[{"heading":"From titles to du","paragraphs":["Until the 1960s, Swedes addressed superiors in the third person (Would the director like coffee?) rather than with du or ni. This system reflected a strict social hierarchy.","In the late 1960s, the du-reformen made du the default in almost every setting. Pushed by broadcasters, unions and an expanding public sector, the shift accelerated a major cultural change."]},{"heading":"A democratic shift","paragraphs":["Within about a decade, the old title system collapsed. Today, addressing a Swedish manager or professor as ni sounds distant or archaic. The reform was part of a wider democratisation of workplaces and coincided with the expansion of the welfare state."]}]},"context":{"countries":["SE"],"region":"Nationwide","continent":"europe","languages":["sv"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Du-reformen","de":"Du-reformen","en":"Du-reformen"},"url":"https://en.wikipedia.org/wiki/Du-reformen","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Swedish language","de":"Swedish language","en":"Swedish language"},"url":"https://en.wikipedia.org/wiki/Swedish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في ستوكهولم يراسل أستاذه باستخدام du والاسم الأول، ثم يعتذر عند الكتابة بالإنجليزية لأن الإنجليزية تفتقر إلى هذا التبديل، فتبدو الرسالة فجأة متعالية.","de":"Ein Stockholmer Student schreibt seinem Professor eine E-Mail mit du und Vornamen und entschuldigt sich dann auf Englisch, weil das Englische keinen entsprechenden Wechsel kennt und die E-Mail plötzlich anmaßend wirkt.","en":"A Stockholm student emails a professor with du and the first name, then apologises when writing in English because English has no equivalent switch and the email suddenly feels presumptuous."},"misunderstanding":{"ar":"du هو الافتراضي لكنه ليس عالمياً: موظفو الخدمة يستخدمون أحياناً ni مع العملاء الأكبر سناً، والناطقون بالسويدية في فنلندا يتبعون معايير مختلفة. كان الإصلاح تحولاً مدفوعاً بالإعلام، وليس قانوناً.","de":"du ist Standard, aber nicht universell: Servicekräfte verwenden gegenüber älteren Kunden manchmal ni, und schwedischsprachige Finnen folgen anderen Normen. Die Reform war ein mediengetriebener Wandel, kein Gesetz.","en":"Du is default but not universal: service staff sometimes use ni to older customers, and Swedish-speaking Finns follow different norms. The reform was a media-driven shift, not a law."},"comparison":{"ar":"تطورت الفنلندية والنرويجية بشكل مختلف، لذا فإن du السويدية خيار حديث وليست تقليداً عريقاً في المساواة. كما تختلف الممارسة بين الأجيال والمناطق.","de":"Finnisch und Norwegisch entwickelten sich anders, daher ist das schwedische du eine junge Wahl und keine uralte egalitäre Tradition. Auch zwischen Regionen und Generationen gibt es Unterschiede.","en":"Finnish and Norwegian developed differently, so Swedish du is a recent choice rather than an ancient egalitarian tradition. Practice also varies by region and generation."},"expression":{"original":"Vill du ha kaffe?","language":"Svenska (Swedish)","gloss":{"ar":"هل ترغب في القهوة؟ (باستخدام du، وليس لقباً)","de":"Möchtest du Kaffee? (mit du, nicht mit einem Titel)","en":"Would you like coffee? (using du, not a title)"},"usage":{"ar":"تعبير يومي يعكس الاستخدام الافتراضي لـ du في الحياة السويدية المعاصرة.","de":"Alltäglicher Ausdruck, der den Standardgebrauch von du im heutigen Schweden zeigt.","en":"An everyday phrase showing the default use of du in contemporary Sweden."},"transliteration":"Vill du ha kaffe?"}},{"id":"lng-048","version":2,"slug":"sisu-the-finnish-word-for-continuing-when-continuing-makes-no-sense","contentType":"detail","category":"languages","title":{"ar":"سيسو: كلمة فنلندية للاستمرار رغم اليأس","de":"Sisu: das finnische Wort für Weitermachen ohne Sinn","en":"Sisu: the Finnish word for continuing when continuing makes no sense"},"deck":{"ar":"كلمة تصف المثابرة في مواجهة الصعاب، لكنها تحمل تحذيرًا من رفض المساعدة.","de":"Sisu beschreibt Beharrlichkeit angesichts aussichtsloser Umstände – und warnt zugleich vor übertriebenem Stolz.","en":"Sisu names determination against hopeless odds, but it also carries a warning about refusing help."},"teaser":{"ar":"سيسو ليست مجرد تصميم، بل مفهوم فنلندي للتحمل دون وعد بمكافأة، يستخدم كمجاملة وتحذير في آن واحد.","de":"Sisu ist mehr als Durchhaltevermögen: ein finnisches Konzept für Ausdauer ohne Belohnungsversprechen, das als Kompliment und Warnung dient.","en":"Sisu is more than grit: a Finnish concept for endurance without promise of reward, used as both compliment and caution."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى سيسو في الحياة اليومية","paragraphs":["سيسو تعني التصميم في مواجهة الصعاب المستحيلة، وتُستخدم في إصلاحات الشتاء والأمراض الطويلة وإنهاء حصاد سنة سيئة. يستخدمها الفنلنديون كمجاملة، ولكن أيضًا كتحذير، لأن الكثير من سيسو قد يعني رفض المساعدة التي تُحتاج.","سيسو ليست مرادفًا للسعادة أو التفاؤل؛ إنها تصف التحمل دون وعد بمكافأة."]},{"heading":"من الشعار التسويقي إلى الهوية الوطنية","paragraphs":["أصبحت الكلمة شعارًا تسويقيًا وعلامة وطنية، وقد لاحظ الباحثون الفنلنديون الإفراط في استخدامها في النصوص السياحية. انتشر المفهوم إلى الإنجليزية عبر المجتمعات الفنلندية الأمريكية، ثم عاد إلى فنلندا كمنتج تصديري.","يختلف تصور سيسو بين الأجيال والمناطق؛ فبعض الشباب في المدن يرونها صفة نمطية، بينما يتمسك بها كبار السن في الريف. كما أن الفنلنديين الناطقين بالسويدية والمجتمعات المهاجرة الجديدة تتعامل معها بشكل مختلف."]}],"de":[{"heading":"Sisu im Alltag","paragraphs":["Sisu bezeichnet Entschlossenheit angesichts hoffnungsloser Umstände und wird für Winterreparaturen, lange Krankheiten und das Beenden einer schlechten Ernte verwendet. Finnen nutzen es als Kompliment, aber auch als Warnung, denn zu viel Sisu kann bedeuten, notwendige Hilfe abzulehnen.","Sisu ist nicht dasselbe wie Glück oder Optimismus; es beschreibt Ausdauer ohne Aussicht auf Belohnung."]},{"heading":"Vom Werbeslogan zur nationalen Marke","paragraphs":["Das Wort wurde zum Marketing-Slogan und zur nationalen Marke, und finnische Forscher haben seinen übermäßigen Gebrauch in Tourismus Texten bemerkt. Das Konzept verbreitete sich über finnisch-amerikanische Gemeinschaften ins Englische und kehrte als Exportprodukt nach Finnland zurück.","Die Wahrnehmung von Sisu variiert regional und generationell: Manche junge Städter sehen es als Klischee, während ältere Menschen auf dem Land daran festhalten. Auch schwedischsprachige Finnen und neuere Einwanderergemeinschaften haben eine andere Beziehung dazu."]}],"en":[{"heading":"Sisu in everyday life","paragraphs":["Sisu names determination in the face of hopeless odds, and it is used for winter repairs, long illnesses and finishing a bad year's harvest. Finnish speakers use it as a compliment but also as a warning, because too much sisu can mean refusing help that is needed.","Sisu is not the same as happiness or optimism; it describes endurance without a promise of reward."]},{"heading":"From marketing slogan to national brand","paragraphs":["The word became a marketing slogan and a national brand, and Finnish researchers have noted its overuse in tourism copy. The concept spread into English through Finnish-American communities and re-entered Finland as an export product.","Perceptions of sisu vary by region and generation: some young urban Finns see it as a stereotype, while older rural people hold on to it. Swedish-speaking Finns and newer immigrant communities also relate to it differently."]}]},"context":{"countries":["FI"],"region":"Nationwide","continent":"europe","languages":["fi"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sisu","de":"Sisu","en":"Sisu"},"url":"https://en.wikipedia.org/wiki/Sisu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Finnish language","de":"Finnish language","en":"Finnish language"},"url":"https://en.wikipedia.org/wiki/Finnish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مزارع فنلندي ينهار سقفه في فبراير، يصلحه في الظلام ويصف الجهد بأنه سيسو، ثم ينصح ابنه بعدم وراثة هذه العادة لأن السقف كان يجب إصلاحه في الخريف.","de":"Ein finnischer Bauer, dessen Dach im Februar einstürzt, repariert es im Dunkeln und nennt die Anstrengung Sisu – dann rät er seinem Sohn, diese Angewohnheit nicht zu erben, weil das Dach im Herbst hätte repariert werden sollen.","en":"A Finnish farmer whose roof collapses in February repairs it in the dark and calls the effort sisu, then tells his son not to inherit the habit because the roof should have been fixed in autumn."},"misunderstanding":{"ar":"يعتقد البعض أن سيسو تعني العناد أو رفض المساعدة دائمًا، لكنها في الواقع تصف التحمل في مواجهة الصعاب، وقد تكون رفضًا ضارًا للمساعدة في بعض الأحيان.","de":"Manche glauben, Sisu bedeute immer Sturheit oder die Ablehnung von Hilfe. Tatsächlich beschreibt es Ausdauer angesichts von Schwierigkeiten und kann manchmal schädliche Hilfsverweigerung sein.","en":"Some think sisu always means stubbornness or refusing help, but it actually describes endurance in the face of difficulty and can sometimes be harmful help-refusal."},"comparison":{"ar":"على عكس كلمات مثل السعادة أو التفاؤل، لا تعد سيسو بمكافأة؛ إنها ببساطة الاستمرار عندما لا يكون الاستمرار منطقيًا.","de":"Anders als Wörter wie Glück oder Optimismus verspricht Sisu keine Belohnung; es ist einfach das Weitermachen, wenn Weitermachen keinen Sinn ergibt.","en":"Unlike words like happiness or optimism, sisu does not promise a reward; it is simply continuing when continuing makes no sense."},"expression":{"original":"Sisu","language":"Suomi (Finnish)","gloss":{"ar":"تحمل عنيد","de":"sture Ausdauer","en":"stubborn endurance"},"usage":{"ar":"تستخدم لوصف المثابرة في مواقف صعبة، غالبًا مع نبرة إعجاب أو تحذير.","de":"Wird verwendet, um Beharrlichkeit in schwierigen Situationen zu beschreiben, oft mit Bewunderung oder als Warnung.","en":"Used to describe perseverance in difficult situations, often with admiration or as a warning."},"transliteration":"sisu"}},{"id":"lng-049","version":2,"slug":"icelandic-names-why-the-phone-book-is-sorted-by-first-name","contentType":"note","category":"languages","title":{"ar":"الأسماء الآيسلندية والترتيب حسب الاسم الأول","de":"Isländische Namen und das Telefonbuch","en":"Icelandic names and the first-name phone book"},"deck":{"ar":"في آيسلندا يتغيّر اسم العائلة كل جيل، ولهذا يُرتَّب دليل الهاتف حسب الاسم الأول لا حسب اللقب.","de":"In Island wechselt der Nachname mit jeder Generation, deshalb ist das Telefonbuch nach Vornamen sortiert.","en":"In Iceland the surname changes every generation, which is why the phone book is sorted by first name."},"teaser":{"ar":"معظم الآيسلنديين يحملون اسم أب أو أم لا لقب عائلة، ما يجعل الأسماء تتغيّر جيلاً بعد جيل ويقلب عادات المناداة رأساً على عقب.","de":"Die meisten Isländer tragen keinen Familiennamen, sondern einen Vater- oder Mutternamen. Das verändert, wie Menschen einander ansprechen und wie Behörden sie führen.","en":"Most Icelanders carry a father's or mother's name rather than a family name, which reshapes how people address each other and how officials keep records."},"readingMinutes":1,"sections":{"ar":[{"heading":"اسم يتغيّر مع كل جيل","paragraphs":["معظم الآيسلنديين لا يحملون لقب عائلة بل اسماً أبويّاً أو أمويّاً: ابن يون يُدعى يونسون وابنته يونسدوتير. لذلك يتغيّر اللقب في كل جيل، ولهذا يُرتَّب دليل الهاتف حسب الاسم الأول.","هذا يعني أن الأخوة قد يحملون ألقاباً مختلفة إذا اختارت العائلة اسماً أمويّاً عن قصد، وهي عادة تزداد شيوعاً اليوم. ويختلف الأمر قليلاً بين المناطق والأجيال، إذ يتمسّك بعض كبار السن بالأسماء الأبوية التقليدية."]},{"heading":"المناداة بالاسم الأول في كل مكان","paragraphs":["في آيسلندا يُنادى الناس بأسمائهم الأولى في كل سياق تقريباً، مع المعلمين والمسؤولين أيضاً، ونادراً ما يُستخدم اللقب في النداء.","تحتفظ البلاد بلجنة للأسماء توافق على الأسماء الأولى الجديدة، ويجب أن توافق القواعد النحوية الآيسلندية وأعراف الجنس. الألقاب العائلية موجودة فعلاً، خصوصاً لدى عائلات ذات أصول أجنبية، وقواعد اللجنة موضع جدل."]}],"de":[{"heading":"Ein Name, der mit jeder Generation wechselt","paragraphs":["Die meisten Isländer tragen keinen Familiennamen, sondern ein Patronym oder Matronym: Der Sohn von Jón heißt Jónsson, die Tochter Jónsdóttir. So ändert sich der Nachname in jeder Generation, und darum ist das isländische Telefonbuch nach Vornamen sortiert.","Geschwister können deshalb verschiedene Nachnamen tragen, wenn Eltern bewusst einen Matronym wählen, was heute häufiger vorkommt. Regional und je nach Generation gibt es Unterschiede, da manche Ältere an traditionellen Vatersnamen festhalten."]},{"heading":"Der Vorname gilt überall","paragraphs":["Fast überall werden Menschen mit dem Vornamen angesprochen, auch Lehrkräfte und Beamte, Nachnamen hört man im direkten Anreden selten.","Ein Ausschuss prüft neue Vornamen, die zur isländischen Grammatik und zu Geschlechterkonventionen passen müssen. Familiennamen gibt es durchaus, besonders bei Familien mit ausländischen Wurzeln; die Regeln des Ausschusses sind umstritten."]}],"en":[{"heading":"A name that changes each generation","paragraphs":["Most Icelanders have a patronymic or matronymic rather than a family name: a son of Jón is Jónsson and a daughter is Jónsdóttir. Surnames change every generation, which is why the Icelandic phone book is sorted by first name.","Matronymics have become more common as a deliberate choice, so siblings can carry different surnames from each other. Practice varies a little by region and generation, as some older people keep to traditional patronymics."]},{"heading":"First names in almost every setting","paragraphs":["People are addressed by first name in almost every setting, including with teachers and officials, and surnames are rarely used vocatively.","Iceland keeps a naming committee that must approve new first names, and names must fit Icelandic grammar and gender conventions. Family names do exist, especially among families with foreign ancestry, and the committee's rules are debated."]}]},"context":{"countries":["IS"],"region":"Nationwide","continent":"europe","languages":["is"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Icelandic name","de":"Icelandic name","en":"Icelandic name"},"url":"https://en.wikipedia.org/wiki/Icelandic_name","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Icelandic language","de":"Icelandic language","en":"Icelandic language"},"url":"https://en.wikipedia.org/wiki/Icelandic_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب آيسلندي يلتقي موظفة بنك فيناديها باسمها الأول ولا يعرف لقبها أبداً؛ وعندما يُسجَّل ابن الموظفة في المدرسة يُدرَج باسمه الأول مضافاً إليه اسم أبيه.","de":"Eine isländische Studentin spricht eine Bankangestellte mit dem Vornamen an und erfährt deren Nachnamen nie; als der Sohn der Angestellten in der Schule angemeldet wird, steht dort sein Vorname plus der Name seines Vaters.","en":"An Icelandic student meeting a bank clerk calls her by first name and never learns her surname; when the clerk's son is registered at school he is listed under his own first name plus his father's name."},"misunderstanding":{"ar":"يظن كثيرون أن غياب الألقاب يعني فوضى أو نقصاً في الرسمية، لكنه نظام دقيق تحكمه قواعد واضحة.","de":"Viele halten das Fehlen fester Familiennamen für Unordnung, doch dahinter steht ein klares, geregeltes System.","en":"Many assume the lack of fixed family names means informality or confusion, but it is a precise system with clear rules."},"comparison":{"ar":"في كثير من البلدان يُعرَّف الشخص بلقب عائلته الثابت، أما في آيسلندا فيُعرَّف بوالده أو والدته، فيحمل كل جيل اسماً جديداً.","de":"In vielen Ländern identifiziert ein stabiler Familienname die Person, in Island dagegen der Name des Vaters oder der Mutter, sodass jede Generation neu benannt wird.","en":"In many countries a stable family name identifies a person, while in Iceland the parent's name does, so each generation is named anew."},"expression":{"original":"Hvað heitir þú?","language":"Íslenska (Icelandic)","gloss":{"ar":"ما اسمك؟","de":"Wie heißt du?","en":"What are you called?"},"usage":{"ar":"سؤال يومي شائع عند التعارف، ويُجاب عليه بالاسم الأول وحده عادة.","de":"Eine alltägliche Frage beim Kennenlernen, meist mit dem Vornamen beantwortet.","en":"A common everyday question when meeting someone, usually answered with the first name alone."},"transliteration":"Hvad heitir thu?"}},{"id":"lng-050","version":2,"slug":"craic-the-irish-word-for-talk-that-is-worth-the-journey","contentType":"detail","category":"communication","title":{"ar":"الكريك: حديث يستحق الرحلة","de":"Craic: Gespräch, das die Reise wert ist","en":"Craic: talk worth the journey"},"deck":{"ar":"كلمة إيرلندية تصف متعة الكلام والأخبار والأجواء، وتُسأل بها عن حالك وعن ما يجري معًا.","de":"Ein irisches Wort für gutes Gerede, Neuigkeiten und Atmosphäre – es fragt zugleich, was läuft und wie es dir geht.","en":"An Irish word for enjoyable conversation, news and atmosphere – the question asks what's happening and how you are at once."},"teaser":{"ar":"في إيرلندا ليس السؤال عن «الكريك» استفسارًا عابرًا، بل دعوة لتبادل الأخبار وقياس جودة الحديث لا المكان.","de":"In Irland ist die Frage nach dem Craic keine Höflichkeitsfloskel, sondern eine Einladung zum Erzählen – gemessen an der Qualität des Gesprächs, nicht am Ort.","en":"In Ireland, asking about the craic is not small talk but an invitation to trade news, judged by the quality of the conversation rather than the venue."},"readingMinutes":1,"sections":{"ar":[{"heading":"سؤال يعني شيئين","paragraphs":["كلمة «كريك» تعني الحديث الممتع والأخبار والأجواء، وسؤال «ما الكريك؟» يسأل في الوقت نفسه عمّا يجري وعن حالك. وهي نشاط لا مزاج، يُقاس بجودة الكلام لا بفخامة المكان.","استُعيرت الكلمة إلى الإنجليزية من الإيرلندية أو من لهجة شمال إنجلترا، ثم صارت علامة على الهوية الإيرلندية في التسعينيات. ويختلف استعمالها بين الأجيال والمناطق، إذ تتراجع عند بعض الشباب في المدن وتزدهر في المناسبات."]},{"heading":"من التهجئة إلى الهوية","paragraphs":["روّج أصحاب الحانات في دبلن تهجئة «craic» في الستينيات والسبعينيات، ولا تزال الصيغة الإنجليزية الأقدم «crack» تظهر في اسكتلندا.","يشير كتّاب باللغة الإيرلندية إلى أن «spraoi» هي الكلمة الأصلية للمرح، وأن «craic» جاءت من لهجة إنجليزية قبل أن تصبح علامة إيرلندية."]}],"de":[{"heading":"Eine Frage, zwei Antworten","paragraphs":["Craic bedeutet unterhaltsames Gespräch, Neuigkeiten und Atmosphäre; die Frage „What's the craic?“ fragt zugleich, was gerade läuft und wie es dir geht. Craic ist eine Tätigkeit, keine Stimmung, und wird an der Qualität des Geredes gemessen, nicht an der Location.","Das Wort wurde aus dem Irischen oder aus einem nordenglischen Dialekt ins Englische entlehnt und wurde in den 1990er-Jahren zum Identitätsmarker. Je nach Region und Generation wird es unterschiedlich oft benutzt, in Städten bei Jüngeren seltener, im Westen häufiger."]},{"heading":"Schreibweise als Signal","paragraphs":["Dubliner Gastwirte förderten in den 1960er- und 1970er-Jahren die Schreibweise „craic“; die ältere englische Form „crack“ lebt in Schottland weiter.","Irischsprachige Autorinnen und Autoren betonen, dass „spraoi“ das einheimische Wort für Spaß ist und „craic“ aus dem Englischen kam, bevor es irisch wurde."]}],"en":[{"heading":"One question, two answers","paragraphs":["Craic means enjoyable conversation, news and atmosphere, and the question What's the craic? asks both what is happening and how you are. Having the craic is an activity rather than a mood, judged by the quality of the talk rather than the venue.","The word was borrowed into English from Irish or from northern English dialect and became a marker of Irish identity in the 1990s. Use varies by region and generation, thinning among younger city speakers and holding firm in the west."]},{"heading":"Spelling as a signal","paragraphs":["Dublin publicans promoted the spelling craic in the 1960s and 1970s, while the older English form crack still appears in Scotland.","Irish-language writers point out that spraoi is the native word for fun, and that craic came from English dialect before becoming a marker of Irishness."]}]},"context":{"countries":["IE"],"region":"Nationwide, strongest in Dublin and the west","continent":"europe","languages":["ga","en"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in Dublin and the west"],"sources":[{"organization":"Wikipedia","title":{"ar":"Craic","de":"Craic","en":"Craic"},"url":"https://en.wikipedia.org/wiki/Craic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Irish language","de":"Irish language","en":"Irish language"},"url":"https://en.wikipedia.org/wiki/Irish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسأل مضيف إيرلندي «ما الكريك؟» قبل أن يسأل إن كنت تريد شايًا، وجواب باهت عن الطقس ينهي الحديث أسرع من نكتة رديئة عنه.","de":"Ein irischer Gastgeber fragt nach dem Craic, bevor er fragt, ob du Tee willst; eine flache Antwort über das Wetter beendet das Gespräch schneller als ein schlechter Witz darüber.","en":"An Irish host asks what's the craic before asking whether you want tea, and a flat answer about the weather ends the exchange faster than a bad joke about it would."},"misunderstanding":{"ar":"يظن بعض الزوار أن الكلمة تعني المرح الصاخب أو السُكر، بينما هي في الأساس عن جودة الحديث وتبادل الأخبار.","de":"Viele Besucher halten Craic für laute Feierlaune oder Trunkenheit, dabei geht es vor allem um gutes Gespräch und Neuigkeiten.","en":"Visitors often assume craic means loud partying or drinking, when it is mainly about good talk and exchanged news."},"comparison":{"ar":"تشبه الكلمة الإنجليزية «small talk» لكنها أثقل وزنًا: الحديث العابر هنا ليس عابرًا، بل هو الغاية نفسها.","de":"Es ähnelt dem englischen „small talk“, wiegt aber mehr: Das Beiläufige ist hier nicht Nebensache, sondern der eigentliche Zweck.","en":"It resembles English small talk but carries more weight: the casual exchange is not a prelude to the evening, it is the point."},"expression":{"original":"Craic","language":"Gaeilge (Irish)","gloss":{"ar":"حديث وأجواء ممتعة","de":"unterhaltsames Gerede und Atmosphäre","en":"enjoyable talk and atmosphere"},"usage":{"ar":"تُستعمل في السؤال «ما الكريك؟» أي ما الأخبار وكيف حالك، وفي وصف أمسية طيّبة الحديث.","de":"In „What's the craic?“ als Frage nach Neuigkeiten und Befinden, sowie zur Beschreibung eines gelungenen Abends.","en":"Used in What's the craic? to ask for news and how someone is, and to describe a good night out."},"transliteration":"craic"}},{"id":"lng-051","version":2,"slug":"cwtch-the-welsh-word-for-a-hug-that-is-also-a-safe-place","contentType":"detail","category":"languages","title":{"ar":"كلمة ويلزية تعني الحضن والمكان الآمن","de":"Cwtch: Umarmung und sicherer Ort zugleich","en":"Cwtch: a hug that is also a safe place"},"deck":{"ar":"كلمة cwtch تجمع بين دفء الحضن وأمان المكان المغلق، ويستخدمها الويلزيون في حياتهم اليومية باللغتين.","de":"Das walisische Wort verbindet die Wärme einer Umarmung mit dem Schutz eines kleinen Raums und begleitet den Alltag in Wales.","en":"The Welsh word links the warmth of an embrace with the shelter of a small space, and it travels easily into English conversation."},"teaser":{"ar":"في ويلز كلمة واحدة تسمّي الحضن والمكان الذي نحفظ فيه شيئاً، وتربط بينهما بدل أن تفصلهما.","de":"In Wales benennt ein einziges Wort die Umarmung und den Ort, an dem etwas sicher aufbewahrt wird, und verknüpft beides.","en":"In Wales one word names both a cuddle and the place where something is kept safe, and the two meanings are joined."},"readingMinutes":1,"sections":{"ar":[{"heading":"حضن ومخبأ في كلمة واحدة","paragraphs":["تحمل كلمة cwtch معنيين متصلين لا منفصلين: الحضن الدافئ، والمكان الصغير الآمن كالخزانة أو الحجرة الضيقة. والفعل cwtchu يُستخدم لمواساة طفل، والاسم نفسه يسمّي الموضع الذي يُحفظ فيه شيء بأمان.","يقع النبر في المقطع الأول، وينطق الحرفان الأخيران ch كالصوت في كلمة loch الاسكتلندية. وتختلف طريقة استخدام الكلمة بين الأجيال والمناطق، إذ يتبنّاها الشباب في الحديث اليومي بسرعة أكبر."]},{"heading":"من كتب الأطفال إلى لافتات المقاهي","paragraphs":["تظهر الكلمة في كتب الأطفال بالويلزية، وفي إعلانات بالإنجليزية داخل ويلز كرمز للدفء الوطني. ومع ازدياد التعليم بالويلزية، صارت من الكلمات التي ينقلها الجيل الشاب إلى جملته الإنجليزية.","لا يتحدث كل الويلزيين الويلزية، فاستخدام cwtch في الإنجليزية اختيار يدل على الانتماء الويلزي أكثر من يدل على الطلاقة اللغوية."]}],"de":[{"heading":"Umarmung und Versteck in einem Wort","paragraphs":["Cwtch trägt zwei verbundene Bedeutungen: die warme Umarmung und den kleinen sicheren Raum, etwa einen Schrank. Das Verb cwtchu wird gebraucht, um ein Kind zu trösten, und das Substantiv benennt den Ort, an dem etwas sicher liegt.","Die Betonung liegt auf der ersten Silbe, und das abschließende ch klingt wie in schottisch loch. Je nach Region und Generation wird das Wort unterschiedlich häufig verwendet, junge Sprecher greifen schneller danach."]},{"heading":"Von Kinderbüchern bis zur Cafétür","paragraphs":["Das Wort erscheint in walisischsprachigen Kinderbüchern und in englischsprachiger Werbung in Wales als Zeichen nationaler Wärme. Mit dem wachsenden Unterricht auf Walisisch tragen junge Sprecher es in englische Gespräche.","Nicht alle Waliser sprechen Walisisch; wer cwtch im Englischen benutzt, zeigt damit eher Zugehörigkeit als Sprachkenntnis."]}],"en":[{"heading":"A cuddle and a hiding place","paragraphs":["Cwtch carries two linked meanings rather than separate ones: a cuddle, and a cupboard or small safe space. The verb cwtchu is used for comforting a child, and the noun can name the place where something is kept safe.","Stress falls on the first syllable, and the final ch sounds like the one in Scottish loch. Usage varies by region and generation, with younger speakers reaching for the word more readily."]},{"heading":"From children's books to cafe doors","paragraphs":["The word appears in Welsh-language children's books and in English-language marketing in Wales as a symbol of national warmth. Welsh-medium education has increased the number of young speakers, and cwtch is one of the words they carry into English.","Many Welsh people do not speak Welsh, so using cwtch in English signals Welshness rather than fluency."]}]},"context":{"countries":["GB"],"region":"Wales","community":"Welsh speakers","continent":"europe","languages":["cy","en"],"period":"contemporary"},"tags":["languages","Wales"],"sources":[{"organization":"Wikipedia","title":{"ar":"Cwtch","de":"Cwtch","en":"Cwtch"},"url":"https://en.wikipedia.org/wiki/Cwtch","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Welsh language","de":"Welsh language","en":"Welsh language"},"url":"https://en.wikipedia.org/wiki/Welsh_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"أم في كارديف تنادي ابنها الباكي طالبةً منه حضناً، والكلمة نفسها مرسومة على باب مقهى تعني الحجرة الخلفية المريحة التي يجلس فيها الزبائن المعتادون.","de":"Eine Mutter in Cardiff ruft ihren weinenden Sohn zu einem cwtch, und dasselbe Wort steht auf einer Cafétür für die gemütliche hintere Stube der Stammgäste.","en":"A Cardiff mother tells her crying son to come for a cwtch, and the same word is stencilled on a cafe door meaning the snug back room where regulars sit."},"misunderstanding":{"ar":"يظن بعض غير الويلزيين أن الكلمة تعني الحضن فقط، فيفوتهم معنى المكان الآمن المرتبط به.","de":"Viele Außenstehende halten cwtch nur für eine Umarmung und übersehen die Bedeutung des sicheren Ortes.","en":"Outsiders often hear only the cuddle and miss the second meaning, the small safe place the word also names."},"comparison":{"ar":"تشبه الكلمة مفردات مثل الكلمة الاسكتلندية loch في نطقها، لكنها تختلف عنها في أنها تحمل معنى عاطفياً ومكانياً معاً.","de":"Im Klang erinnert das ch an schottisch loch, doch cwtch trägt zusätzlich eine räumliche und emotionale Bedeutung.","en":"The final ch echoes Scottish loch, but cwtch adds an emotional and spatial sense that loch does not carry."},"expression":{"original":"Cwtch","language":"Cymraeg (Welsh)","gloss":{"ar":"حضن؛ مكان آمن","de":"Umarmung; sicherer Ort","en":"a cuddle; a safe place"},"usage":{"ar":"تُقال لطفل أو صديق عند الحاجة إلى مواساة، وتُكتب على أبواب المقاهي لتعني الحجرة الدافئة.","de":"Wird tröstend zu Kindern oder Freunden gesagt und auf Cafétüren für die gemütliche Stube verwendet.","en":"Said to comfort a child or a friend, and written on cafe doors for the snug back room."},"transliteration":"cwtch"}},{"id":"lng-052","version":2,"slug":"tu-and-usted-spanish-politeness-that-is-moving-down-the-age-scale","contentType":"note","category":"communication","title":{"ar":"تو وأوستد: التهذيب الإسباني يتغير مع الأجيال","de":"Tu und usted: Spanische Höflichkeit verändert sich","en":"Tu and usted: Spanish politeness moves down the age scale"},"deck":{"ar":"اختيار الضمير في الإسبانية ليس مجرد قاعدة، بل انعكاس للعلاقات والاحترام والتغير الاجتماعي.","de":"Die Wahl zwischen vertrautem 'tu' und formellem 'usted' spiegelt Beziehungen, Respekt und sozialen Wandel wider.","en":"Choosing between familiar 'tu' and formal 'usted' is not just grammar—it signals relationships, respect, and social change."},"teaser":{"ar":"في إسبانيا، يتراجع استخدام 'أوستد' بين الشباب، بينما يظل مهيمناً في أمريكا اللاتينية. كيف يعكس هذا التغيير تحولات المجتمع؟","de":"In Spanien verliert 'usted' bei jungen Menschen an Boden, während es in weiten Teilen Lateinamerikas Standard bleibt. Was verrät dieser Wandel über die Gesellschaft?","en":"In Spain, 'usted' is receding among young people, while much of Latin America holds on to it. What does this shift reveal about how people live?"},"readingMinutes":1,"sections":{"ar":[{"heading":"اختيار الضمير: أكثر من مجرد كلمة","paragraphs":["في الإسبانية، الاختيار بين 'تو' (غير الرسمي) و'أوستد' (الرسمي، صيغة الغائب) يحدد العلاقة بين المتحدثين. الفعل يتغير أيضاً: 'تو تيينيس' مقابل 'أوستد تييني'. هذا الاختيار ليس مجرد قاعدة نحوية، بل إشارة إلى المدى الذي تريد أن تضع به نفسك من الآخر.","يُستخدم 'أوستد' مع الغرباء وكبار السن وفي المواقف الخدمية. لكن الأطباء والمدرسين الإسبان يستخدمون 'تو' بشكل متزايد مع المرضى البالغين والطلاب. هذا التحول يعكس مجتمعاً أقل رسمية، حيث تُبنى العلاقات على القرب بدلاً من التسلسل الهرمي."]},{"heading":"تباين إقليمي وجيلي","paragraphs":["في إسبانيا، تراجع 'أوستد' بين الشباب، بينما لا يزال معياراً مع الغرباء في معظم أمريكا اللاتينية. الجمع يضيف طبقة أخرى: 'فوسوتروس' هو الجمع غير الرسمي في إسبانيا، بينما تستخدم أمريكا اللاتينية 'أوستديس' للرسمي وغير الرسمي. يختلف الاستخدام حسب البلد والمنطقة والطبقة والجيل، فلا قاعدة واحدة تنطبق على العالم الناطق بالإسبانية."]}],"de":[{"heading":"Die Wahl des Pronomens: mehr als ein Wort","paragraphs":["Im Spanischen bestimmt die Wahl zwischen 'tu' (vertraut) und 'usted' (formell, dritte Person) die Beziehung zwischen Sprechenden. Auch die Verbformen unterscheiden sich: 'tú tienes' gegenüber 'usted tiene'. Diese Wahl ist keine bloße Grammatikregel, sondern ein Signal dafür, wie nah man dem anderen stehen möchte.","'Usted' wird gegenüber Fremden, älteren Menschen und in Dienstleistungssituationen verwendet. Doch spanische Ärzte und Lehrer verwenden zunehmend 'tu' gegenüber erwachsenen Patienten und Studierenden. Dieser Wandel spiegelt eine weniger formelle Gesellschaft wider, in der Nähe statt Hierarchie zählt."]},{"heading":"Regionale und generationelle Unterschiede","paragraphs":["In Spanien ist 'usted' unter jungen Menschen rückläufig, während es in weiten Teilen Lateinamerikas gegenüber Fremden weiterhin Standard ist. Der Plural fügt eine weitere Ebene hinzu: 'vosotros' ist der vertraute Plural in Spanien, während Lateinamerika 'ustedes' für beide Formen verwendet. Der Gebrauch variiert nach Land, Region, Klasse und Generation – keine einzelne Regel deckt die spanischsprachige Welt ab."]}],"en":[{"heading":"Choosing a pronoun: more than a word","paragraphs":["In Spanish, the choice between 'tu' (familiar) and 'usted' (formal, grammatically third person) defines the relationship between speakers. The verb forms differ too: 'tú tienes' versus 'usted tiene'. This choice is not just a grammar rule—it signals how close you want to place yourself to the other person.","Usted is used with strangers, older people, and in service encounters. But Spanish doctors and teachers increasingly use 'tu' with adult patients and students. This shift reflects a less formal society, where closeness rather than hierarchy builds relationships."]},{"heading":"Regional and generational contrasts","paragraphs":["In Spain, 'usted' has receded among young people, while in much of Latin America it remains standard with strangers. The plural adds another layer: 'vosotros' is the familiar plural in Spain, while Latin America uses 'ustedes' for both familiar and formal address. Usage varies by country, region, class, and generation—no single rule covers the Spanish-speaking world."]}]},"context":{"countries":["ES"],"region":"Nationwide, with strong regional differences","continent":"europe","languages":["es"],"period":"contemporary"},"tags":["communication","Nationwide, with strong regional differences"],"sources":[{"organization":"Wikipedia","title":{"ar":"Spanish language","de":"Spanish language","en":"Spanish language"},"url":"https://en.wikipedia.org/wiki/Spanish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pronouns in Spanish","de":"Pronouns in Spanish","en":"Pronouns in Spanish"},"url":"https://en.wikipedia.org/wiki/Pronouns_in_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بائعة في متجر في مدريد في العشرينات من عمرها تنادي زبوناً في الأربعين بـ'تو' ووالده بـ'أوستد' في الدقيقة نفسها، وتعدل في منتصف الجملة دون أي فقدان للطلاقة.","de":"Eine Madrider Verkäuferin Mitte zwanzig nennt einen vierzigjährigen Kunden 'tu' und dessen Vater im selben Moment 'usted' – sie passt mitten im Satz an, ohne an Flüssigkeit zu verlieren.","en":"A Madrid shop assistant in her twenties calls a customer of forty 'tu' and the customer's father 'usted' in the same minute, adjusting mid-sentence without any loss of fluency."},"misunderstanding":{"ar":"اختيار 'تو' مبكراً قد يبدو وقحاً، بينما اختيار 'أوستد' مع نظير قد يبدو توبيخاً متعمداً.","de":"Zu frühes 'tu' kann anmaßend wirken; 'usted' gegenüber Gleichaltrigen kann wie eine bewusste Zurückweisung erscheinen.","en":"Choosing 'tu' too soon can feel presumptuous; choosing 'usted' with a peer can feel like a deliberate rebuke."},"comparison":{"ar":"في إسبانيا، 'أوستد' يتراجع بين الشباب، بينما في كولومبيا وكوستاريكا يُستخدم 'أوستد' على نطاق واسع حتى مع الأصدقاء. الأرجنتين تستخدم 'فوس' بدلاً من 'تو'، مما يضيف تنوعاً آخر.","de":"In Spanien verliert 'usted' bei Jungen an Boden, während es in Kolumbien und Costa Rica selbst unter Freunden weit verbreitet ist. Argentinien verwendet 'vos' statt 'tu' – eine weitere Facette.","en":"In Spain, 'usted' is receding among the young, while in Colombia and Costa Rica it is used very broadly, even among friends. Argentine Spanish uses 'vos' instead of 'tu', adding another layer."},"expression":{"original":"¿Usted qué opina?","language":"Español (Spanish)","gloss":{"ar":"ما رأيك، سيدي/سيدتي؟","de":"Was denken Sie, mein Herr/meine Dame?","en":"What do you think, sir/madam?"},"usage":{"ar":"تُستخدم لطلب رأي شخص ما باحترام، خاصة مع الغرباء أو كبار السن.","de":"Wird verwendet, um respektvoll nach der Meinung einer Person zu fragen, besonders bei Fremden oder Älteren.","en":"Used to ask for someone's opinion respectfully, especially with strangers or older people."},"transliteration":"usted que opina?"}},{"id":"lng-053","version":2,"slug":"sobremesa-the-part-of-the-meal-that-happens-after-the-food","contentType":"scene","category":"communication","title":{"ar":"السوبريميسا: حديث يطول بعد الطعام","de":"Sobremesa: das Gespräch nach dem Essen","en":"Sobremesa: the talk that outlasts the meal"},"deck":{"ar":"في إسبانيا لا تنتهي الوليمة بالأطباق، بل بالكلام؛ عادة اجتماعية تحوّل الطاولة إلى مجلس يومي.","de":"In Spanien endet ein Mittagessen nicht mit den Tellern, sondern mit Worten; eine Gewohnheit, die den Tisch zum täglichen Treffpunkt macht.","en":"In Spain lunch does not end with the plates but with conversation; a daily habit that turns the table into the social centre of the day."},"teaser":{"ar":"بعد الغداء تبقى العائلة حول الطاولة ساعتين؛ فالسوبريميسا ليست وقتاً ضائعاً بل جزء أساسي من الحياة الاجتماعية.","de":"Nach dem Essen bleibt die Familie zwei Stunden sitzen; die Sobremesa ist keine verlorene Zeit, sondern fester Teil des sozialen Lebens.","en":"After eating, a family may stay at the table for two hours; sobremesa is not lost time but a fixed part of social life."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما يحدث بعد آخر لقمة","paragraphs":["تعني كلمة «سوبريميسا» حرفياً «فوق الطاولة»، وهي الحديث الذي يستمر بعد انتهاء الأكل مع القهوة أو الحلوى أو دون شيء إطلاقاً.","المطاعم تتحمّل هذا البقاء؛ ففي جنوب إسبانيا قد يمتد الغداء حتى منتصف العصر دون أن تُرفع الأطباق عن الطاولة."]},{"heading":"طاولة تُدار حولها الحياة","paragraphs":["ترتبط العادة بمواعيد الأكل المتأخرة وبكون الحياة الاجتماعية تُنظَّم حول الطاولة لا بعدها. وكثيراً ما يجري الحديث عن العمل أثناء السوبريميسا، ولهذا قد يبدأ الاجتماع الإسباني بغداء وينتهي باتفاق.","يختلف طول السوبريميسا بحسب المنطقة والعمر وجدول العمل؛ ففي مدريد وبرشلونة تكون غداءات أيام العمل قصيرة غالباً، ويذكر شباب المدن أن سوبريميساهم صارت أقصر بسبب مواعيد العمل، كما يغيّر ثقافة الوجبات الجاهزة هذا النمط."]}],"de":[{"heading":"Was nach dem letzten Bissen geschieht","paragraphs":["Sobremesa bedeutet wörtlich „über dem Tisch“: das Gespräch, das nach dem Essen weiterläuft, mit Kaffee, Nachtisch oder ganz ohne.","Restaurants dulden das; in Südspanien kann ein Mittagessen bis in den Nachmittag dauern, ohne dass abgeräumt wird."]},{"heading":"Ein Tisch, um den sich das Leben dreht","paragraphs":["Die Sitte hängt mit späten Essenszeiten zusammen und damit, dass das soziale Leben um den Tisch herum geplant wird statt danach. Geschäftliches wird oft während der Sobremesa besprochen, weshalb spanische Treffen mit einem Mittagessen beginnen und mit einer Einigung enden können.","Die Länge der Sobremesa variiert je nach Region, Alter und Arbeitszeit; in Madrid und Barcelona sind Mittagspausen unter der Woche oft kurz, und jüngere Städter berichten von kürzeren Sobremesas wegen der Arbeitszeiten, während Takeaway-Kultur das Muster verändert."]}],"en":[{"heading":"What happens after the last bite","paragraphs":["Sobremesa means literally “over the table”: the conversation that continues after eating, with coffee, dessert or nothing at all.","Restaurants tolerate it, and in southern Spain a lunch can run until mid-afternoon without the table being cleared."]},{"heading":"A table that life is scheduled around","paragraphs":["The custom is tied to late eating hours and to social life being scheduled around the table rather than after it. Business talk often happens during sobremesa, which is why Spanish meetings may begin with lunch and end with an agreement.","Sobremesa length varies by region, age and work schedule; in Madrid and Barcelona weekday lunches are often short, and younger urban Spaniards report shorter sobremesas because of work schedules, while takeaway culture is changing the pattern."]}]},"context":{"countries":["ES"],"region":"Nationwide, especially in the south","continent":"europe","languages":["es"],"period":"contemporary"},"tags":["communication","Nationwide, especially in the south"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sobremesa","de":"Sobremesa","en":"Sobremesa"},"url":"https://en.wikipedia.org/wiki/Sobremesa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Spanish cuisine","de":"Spanish cuisine","en":"Spanish cuisine"},"url":"https://en.wikipedia.org/wiki/Spanish_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في إشبيلية تنهي الغداء في الثالثة وتغادر الطاولة في الخامسة، والأطباق مدفوعة جانباً والحديث ينتقل بين كرة القدم وعملية جراحية لابن عمّ وشراء منزل.","de":"Eine Familie in Sevilla beendet das Mittagessen um drei und verlässt den Tisch um fünf; die Teller sind beiseitegeschoben, das Gespräch wandert von Fußball über eine Operation des Cousins bis zum Hauskauf.","en":"A Seville family finishes lunch at three and leaves the table at five, with the plates pushed aside and the conversation moving through football, a cousin's operation and a house purchase."},"misunderstanding":{"ar":"يظنّ بعض الزوار أن الجلوس الطويل بعد الأكل علامة على التباطؤ أو عدم الاحترام للوقت، لكنه في الواقع دعوة للانتماء وفرصة للتفاهم.","de":"Manche Besucher halten langes Sitzen nach dem Essen für Trägheit oder Zeitverschwendung, doch es ist eine Einladung zur Zugehörigkeit und eine Gelegenheit zum Verständnis.","en":"Visitors sometimes read the long sit after eating as idleness or disregard for time, but it is an invitation to belong and a chance to reach understanding."},"comparison":{"ar":"في ثقافات كثيرة تُنهى الوجبة وتُغسل الأطباق فوراً، بينما في إسبانيا تُترك الطاولة كما هي ويُمنح الكلام وقته.","de":"In vielen Kulturen wird nach dem Essen sofort abgeräumt und gespült; in Spanien bleibt der Tisch, wie er ist, und das Gespräch bekommt seine Zeit.","en":"In many cultures the meal ends and the plates are washed at once; in Spain the table is left as it is and the talking is given its time."},"expression":{"original":"La sobremesa","language":"Español (Spanish)","gloss":{"ar":"الحديث حول الطاولة بعد الطعام","de":"das Gespräch am Tisch nach dem Essen","en":"the talk at the table after the meal"},"usage":{"ar":"تُقال للدلالة على الوقت الممتد بعد الوجبة حين يبقى الناس يتحدثون.","de":"Bezeichnet die Zeit nach der Mahlzeit, in der man sitzen bleibt und sich unterhält.","en":"Used for the time after eating when people stay seated and keep talking."},"transliteration":"la sobremesa"}},{"id":"lng-054","version":2,"slug":"saudade-the-portuguese-word-for-missing-something-that-may-not-come-back","contentType":"detail","category":"languages","title":{"ar":"سودادي: شوقٌ لما قد لا يعود","de":"Saudade: Sehnsucht nach etwas, das vielleicht nicht wiederkommt","en":"Saudade: longing for what may not return"},"deck":{"ar":"كلمة برتغالية تصف حنينًا لشخص أو مكان أو زمن غائب، وقد يكون حلوًا ومؤلمًا في آن واحد.","de":"Ein portugiesisches Wort für die Sehnsucht nach einem abwesenden Menschen, Ort oder Zeitraum – süß und schmerzhaft zugleich.","en":"A Portuguese word for missing someone or something absent, sweet and painful at once rather than simply sad."},"teaser":{"ar":"في البرتغال كلمة واحدة تحمل الشوق للماضي والغائبين، ويستخدمها الناس يوميًا دون أن يشرحوها للزوار.","de":"In Portugal trägt ein einziges Wort die Sehnsucht nach Vergangenem und Abwesenden, und die Menschen benutzen es täglich, ohne es Fremden zu erklären.","en":"In Portugal one word carries longing for people, places and past times, and people use it daily without explaining it to visitors."},"readingMinutes":1,"sections":{"ar":[{"heading":"شعور علائقي لا حزن عام","paragraphs":["تصف كلمة «سودادي» شوقًا لشخص أو شيء غائب، وهي قد تكون حلوة ومؤلمة معًا لا مجرد حزن.","تُستخدم للأماكن والناس وفترات الماضي، ولشعور لا يستطيع المتحدث تسميته، ولهذا تجد القواميس صعوبة في تعريفها.","القواعد البرتغالية تجعل الشعور علائقيًا: «تير سودادي دي ألغيم» أي أن تحمل شوقًا لشخص، لا أن تكون حزينًا عمومًا."]},{"heading":"في الغناء والحياة اليومية","paragraphs":["الكلمة محورية في كلمات الفادو، حيث تُؤدّى ولا تُشرح، ونادرًا ما يفسّرها المغنون للأجانب.","يستخدمها البرازيليون مثل البرتغاليين على الأقل، ويتحول معناها من الحنين إلى الوطن إلى نوستالجيا حنونة.","يختلف استعمالها بين الأجيال والمناطق، فالشباب في المدن الكبرى يستخدمونها بخفة أكثر من كبار السن في الأرياف."]}],"de":[{"heading":"Ein relationales Gefühl, keine allgemeine Traurigkeit","paragraphs":["Saudade bezeichnet die Sehnsucht nach jemandem oder etwas Abwesendem, und sie kann süß wie schmerzhaft sein, nicht bloß traurig.","Man verwendet sie für Orte, Menschen, vergangene Zeiten und sogar für ein Gefühl, das Sprecher nicht benennen können – deshalb tun sich Wörterbücher schwer.","Die portugiesische Grammatik macht das Gefühl relational: ter saudade de alguém heißt, Sehnsucht nach jemandem zu haben, nicht allgemein traurig zu sein."]},{"heading":"Im Fado und im Alltag","paragraphs":["Das Wort ist zentral in Fado-Texten, wo es aufgeführt statt erklärt wird, und Sänger glossieren es für Ausländer selten.","Brasilianisches Portugiesisch nutzt es mindestens so viel wie europäisches, und die Bedeutung verschiebt sich von Heimweh zu zärtlicher Nostalgie.","Je nach Region und Generation ändert sich der Ton: Jüngere in Großstädten verwenden es leichter als Ältere auf dem Land."]}],"en":[{"heading":"A relational feeling, not general sadness","paragraphs":["Saudade names a longing for someone or something absent, and it can be sweet as well as painful rather than purely sad.","It is used for places, people, past periods and even for a feeling the speaker cannot name, which is why dictionaries struggle with it.","Portuguese grammar makes the feeling relational: ter saudade de alguém is to have longing of someone, not to be sad in general."]},{"heading":"Performed in fado, lived in daily talk","paragraphs":["The word is central to fado lyrics, where it is performed rather than explained, and singers rarely gloss it for foreigners.","Brazilian Portuguese uses it at least as much as European Portuguese, and the meaning shifts from homesickness to affectionate nostalgia.","Usage varies by region and generation, with younger city dwellers often reaching for it more lightly than older people in the countryside."]}]},"context":{"countries":["PT"],"region":"Nationwide","continent":"europe","languages":["pt"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Saudade","de":"Saudade","en":"Saudade"},"url":"https://en.wikipedia.org/wiki/Saudade","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Portuguese language","de":"Portuguese language","en":"Portuguese language"},"url":"https://en.wikipedia.org/wiki/Portuguese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق تاكسي في لشبونة يضع الفادو يقول إن لديه «سودادي» للحي الذي نشأ فيه، رغم أنه يبعد عشرين دقيقة وما زال يزور والدته هناك كل أحد.","de":"Ein Taxifahrer in Lissabon, der Fado spielt, sagt, er habe Saudade nach dem Viertel seiner Kindheit, obwohl es zwanzig Minuten entfernt liegt und er dort jeden Sonntag seine Mutter besucht.","en":"A Lisbon taxi driver playing fado says he has saudade of the neighbourhood he grew up in, although it is twenty minutes away and he still visits his mother there every Sunday."},"misunderstanding":{"ar":"«سودادي» كليشيه وطني وكلمة في آن، والبرتغاليون يستخدمونها بعفوية دون الثقل الأدبي الذي يضفيه عليها الأجانب.","de":"Saudade ist Nationalklischee und Wort zugleich, und Portugiesen gebrauchen es beiläufig, ohne das literarische Gewicht, das Ausländer ihm geben.","en":"Saudade is a national cliche as well as a word, and Portuguese speakers use it casually without the literary weight foreigners attach to it."},"comparison":{"ar":"تختلف نبرتها بين البرتغال والبرازيل: هناك تميل إلى الحنين للوطن، وهنا إلى نوستالجيا دافئة للماضي.","de":"Der Ton unterscheidet sich zwischen Portugal und Brasilien: dort Heimweh, hier eher warme Nostalgie.","en":"The tone differs between Portugal and Brazil: homesickness there, affectionate nostalgia here."},"expression":{"original":"Saudade","language":"Português (Portuguese)","gloss":{"ar":"شوق لشيء غائب","de":"Sehnsucht nach etwas Abwesendem","en":"longing for something absent"},"usage":{"ar":"تُقال عند افتقاد شخص أو مكان أو زمن ماضٍ، وغالبًا مع الفعل «تير» أي «أحمل شوقًا لـ».","de":"Verwendet beim Vermissen von Personen, Orten oder vergangenen Zeiten, meist mit dem Verb ter, also »Sehnsucht nach jemandem haben«.","en":"Said when missing a person, place or past time, usually with the verb ter, meaning to have longing for someone."},"transliteration":"saudade"}},{"id":"lng-055","version":2,"slug":"ciao-the-italian-goodbye-that-started-as-a-servant-s-bow","contentType":"detail","category":"languages","title":{"ar":"تشاو: تحية إيطالية غير رسمية","de":"Ciao: Italiens informeller Gruß","en":"Ciao: Italy's informal all-purpose greeting"},"deck":{"ar":"كلمة تحية تبدأ كخادم وتصبح ودية.","de":"Ein Gruß, der als Dienerfloskel begann und zum Freundschaftswort wurde.","en":"A word that began as a servant's bow and became a friendly hello and goodbye."},"teaser":{"ar":"تشاو تعني مرحباً ووداعاً، لكنها غير رسمية. أصلها من البندقية حيث كانت تعني 'أنا خادمك'.","de":"Ciao bedeutet Hallo und Tschüss, ist aber nur informell. Ursprünglich aus Venedig, wo es 'Ich bin dein Diener' bedeutete.","en":"Ciao means both hello and goodbye, but only informally. It comes from Venetian for 'I am your servant'."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الخدمة إلى التحية","paragraphs":["كلمة تشاو تأتي من العبارة البندقية 's-ciao vostro' التي تعني 'أنا خادمك'، ودخلت الإيطالية العامة من منطقة فينيتو في القرن التاسع عشر. كانت في الأصل تعبيراً عن التواضع، لكنها أصبحت تحية ودية.","تستخدم تشاو للترحيب والوداع معاً، لكن فقط في المواقف غير الرسمية. الرد على تحية رسمية بتشاو يمكن أن يكون خطوة مقصودة للتقارب."]},{"heading":"اختلافات إقليمية","paragraphs":["يستخدم سكان شمال إيطاليا تشاو على نطاق أوسع من سكان الجنوب، حيث لا تزال تبدو إقليمية أو وقحة قليلاً في بعض المناطق. يختلف الاستخدام أيضاً بين الأجيال، فالشباب يستخدمونها أكثر في السياقات الرسمية."]}],"de":[{"heading":"Vom Dienen zum Grüßen","paragraphs":["Ciao stammt von der venezianischen Wendung 's-ciao vostro' ab, was 'Ich bin Euer Diener' bedeutet, und gelangte im 19. Jahrhundert aus dem Veneto in die allgemeine italienische Sprache. Ursprünglich ein Ausdruck der Unterwürfigkeit, wurde es zu einem freundlichen Gruß.","Ciao dient sowohl als Begrüßung als auch als Abschied, aber nur im informellen Kontext. Auf eine formelle Begrüßung mit ciao zu antworten, kann eine bewusste Geste der Vertrautheit sein."]},{"heading":"Regionale Unterschiede","paragraphs":["Norditaliener verwenden ciao großzügiger als Süditaliener, wo es in einigen Regionen noch regional oder leicht frech klingt. Auch zwischen den Generationen gibt es Unterschiede: Jüngere nutzen es häufiger auch in halbformellen Situationen."]}],"en":[{"heading":"From deference to friendliness","paragraphs":["Ciao comes from the Venetian phrase 's-ciao vostro', meaning 'I am your servant', and entered general Italian from the Veneto in the nineteenth century. Originally a gesture of deference, it softened into a casual greeting.","It works for both hello and goodbye, but only informally; answering a formal greeting with ciao can be a deliberate intimacy move."]},{"heading":"Regional and generational shades","paragraphs":["Northern Italians use ciao more broadly than southern Italians, and in some southern regions it still sounds regional or slightly cheeky. Younger speakers also tend to use it in more contexts than older ones."]}]},"context":{"countries":["IT"],"region":"Nationwide","continent":"europe","languages":["it"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ciao","de":"Ciao","en":"Ciao"},"url":"https://en.wikipedia.org/wiki/Ciao","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Italian language","de":"Italian language","en":"Italian language"},"url":"https://en.wikipedia.org/wiki/Italian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يقول بائع في ميلانو 'تشاو' لزبونة يعرفها منذ سنوات، و'بونجورنو' للزبون التالي، والتحيتان تفرقان بين علاقة شخصية ومعاملة تجارية.","de":"Eine Mailänder Ladenbesitzerin sagt ciao zu einer langjährigen Kundin und buongiorno zur nächsten – die beiden Grüße markieren den Unterschied zwischen Beziehung und Geschäft.","en":"A Milanese shopkeeper says ciao to a customer she has known for years and buongiorno to the next one, and the two greetings mark the difference between a relationship and a transaction."},"misunderstanding":{"ar":"تشاو غير رسمية ولا ينبغي استخدامها مع المسؤولين أو الغرباء المسنين أو في الكتابة إلى رئيس. يجهل كثيرون أصلها البندقي.","de":"Ciao ist informell und sollte nicht gegenüber Beamten, älteren Fremden oder in der schriftlichen Kommunikation mit Vorgesetzten verwendet werden. Die venezianische Herkunft ist vielen Sprechern unbekannt.","en":"Ciao is informal and should not be used with officials, elderly strangers or in writing to a superior; regional usage differs, and the word's Venetian origin is often unknown to speakers."},"comparison":{"ar":"على عكس التحيات الأوروبية الأخرى، تشاو لا ترتبط بوقت اليوم بل بإيماءة التواضع، وتعمل كتحية ووداع في آن واحد.","de":"Anders als andere europäische Grußformeln ist ciao nicht an die Tageszeit gebunden, sondern an eine Geste der Ehrerbietung, und funktioniert als Gruß und Abschied zugleich.","en":"Unlike many European greetings, ciao is not tied to a time of day but to a gesture of deference, and it serves as both greeting and farewell."},"expression":{"original":"Ciao","language":"Italiano (Italian)","gloss":{"ar":"مرحباً / وداعاً (غير رسمي)","de":"Hallo / Tschüss (informell)","en":"hi / bye (informal)"},"usage":{"ar":"تحية غير رسمية تستخدم عند اللقاء والوداع مع الأصدقاء والمعارف.","de":"Informeller Gruß beim Kommen und Gehen unter Freunden und Bekannten.","en":"Informal greeting used when meeting and parting with friends and acquaintances."},"transliteration":"ciao"}},{"id":"lng-056","version":2,"slug":"filotimo-the-greek-word-for-doing-the-right-thing-when-nobody-is-watching","contentType":"detail","category":"languages","title":{"ar":"الفيلوتيمو: فعل الصواب حين لا يراك أحد","de":"Filotimo: das Richtige tun, wenn niemand zusieht","en":"Filotimo: doing right when nobody watches"},"deck":{"ar":"كلمة يونانية تجمع الصداقة والشرف، وتصف شخصًا لا فعلًا، وتُستخدم للمدح وللتندّر معًا.","de":"Ein griechisches Wort, das Freundschaft und Ehre verbindet, einen Menschen statt einer Tat beschreibt und zugleich Lob und Spott trägt.","en":"A Greek word joining friend and honour, describing a person rather than an action, used both as praise and as gentle mockery."},"teaser":{"ar":"في اليونان كلمة واحدة تكفي لتشرح لماذا يرفض رجلٌ مالًا، أو يساعد غريبًا، أو يتمسّك برأيه حتى النهاية.","de":"In Griechenland genügt ein Wort, um zu erklären, warum jemand kein Geld annimmt, einem Fremden hilft oder stur bleibt.","en":"In Greece one word explains why a man refuses money, helps a stranger, or digs in his heels until the argument ends."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه الكلمة فعلًا","paragraphs":["تجمع كلمة فيلوتيمو بين philos أي الصديق وtimi أي الشرف، وتسمّي ميلًا إلى التصرف بسخاء ونبل دون أن يُطلب من المرء ذلك.","تُستخدم لمدح من يرفض أجرًا أو يساعد غريبًا أو يحمي اسم عائلته، وقد تبرّر أيضًا العناد حين يتمسّك المرء برأيه.","تظهر الكلمة في حملات السياحة اليونانية وفي كلام القرى، حيث تصف إنسانًا لا عملًا، ويصفها كثيرون بأنها غير قابلة للترجمة."]},{"heading":"مدح وحدّة في الوقت نفسه","paragraphs":["يتقاطع معناها مع الكرامة واحترام الذات والواجب الاجتماعي في آن واحد، وهي مثالية وطنية أكثر منها وصفًا للسلوك اليومي.","يستخدمها اليونانيون بسخرية أيضًا تجاه من يصرّون على فعل الأشياء بطريقتهم، ويبسّطها المغتربون غالبًا إلى مجرد كرم ضيافة.","تنتشر الكلمة في العالم الناطق باليونانية بما فيه قبرص، وتختلف حدّتها بين الأجيال وبين المدن والجزر."]}],"de":[{"heading":"Was das Wort wirklich meint","paragraphs":["Filotimo verbindet philos, den Freund, mit timi, der Ehre, und benennt eine Haltung, großzügig und anständig zu handeln, ohne dass jemand darum bittet.","Man lobt damit jemanden, der eine Bezahlung ablehnt, einem Fremden hilft oder den Namen der Familie schützt; es kann aber auch Eigensinn rechtfertigen.","Das Wort erscheint in griechischen Tourismuskampagnen und in der Dorfsprache, wo es einen Menschen beschreibt und keine Handlung, und gilt vielen als unübersetzbar."]},{"heading":"Lob und Empfindlichkeit zugleich","paragraphs":["Sein Inhalt überschneidet sich mit Würde, Selbstachtung und sozialer Verpflichtung auf einmal, doch es ist eher ein nationales Ideal als eine Beschreibung des Alltags.","Griechen verwenden es auch ironisch für Menschen, die unbedingt alles auf ihre Weise tun, und in der Diaspora schrumpft es oft auf Gastfreundschaft.","Verbreitet ist das Wort in der gesamten griechischsprachigen Welt einschließlich Zypern, wobei Ton und Schärfe je nach Region und Generation variieren."]}],"en":[{"heading":"What the word actually means","paragraphs":["Filotimo combines philos, friend, and timi, honour, naming a disposition to act generously and honourably without being asked.","It praises someone who refuses payment, helps a stranger or protects a family's name, and it can also justify plain stubbornness.","The word appears in Greek tourism campaigns and in village speech, where it describes a person rather than an action, and many call it untranslatable."]},{"heading":"Praise with a sharp edge","paragraphs":["Its content overlaps with dignity, self-respect and social obligation at once, yet it works as a national ideal rather than a description of everyday behaviour.","Greeks also use it ironically about people who insist on doing things their own way, and diaspora usage often flattens it into hospitality.","It is used across the Greek-speaking world including Cyprus, and its tone shifts between generations and between islands and mainland towns."]}]},"context":{"countries":["GR"],"region":"Nationwide, stronger in Crete and the islands","continent":"europe","languages":["el"],"period":"contemporary"},"tags":["languages","Nationwide, stronger in Crete and the islands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Philotimo","de":"Philotimo","en":"Philotimo"},"url":"https://en.wikipedia.org/wiki/Philotimo","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Greek language","de":"Greek language","en":"Greek language"},"url":"https://en.wikipedia.org/wiki/Greek_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يرفض صاحب حانة في كريت مالًا من طاولة غرباء ساعدوا في تنظيف طريق بعد عاصفة، ويقول فقط إنه فيلوتيمو، فينتهي النقاش عند هذا الحد.","de":"Ein Tavernenwirt auf Kreta lehnt Geld von fremden Gästen ab, die nach einem Sturm eine Straße geräumt haben, sagt nur, das sei filotimo, und damit ist das Gespräch beendet.","en":"A Cretan tavern owner refuses money from a table of strangers who helped clear a road after a storm, saying only that it was filotimo, and the refusal ends the discussion."},"misunderstanding":{"ar":"يظنّ البعض أن الكلمة تعني الكرم فقط، لكنها تحمل أيضًا شرفًا وحدّة وتصلّبًا في الرأي.","de":"Viele halten das Wort für bloße Gastfreundschaft, doch es enthält auch Ehrgefühl, Empfindlichkeit und Starrsinn.","en":"Outsiders often hear only hospitality, but the word also carries honour, touchiness and a stubborn refusal to bend."},"comparison":{"ar":"تشبه كلمات الشرف في ثقافات أخرى، لكنها في اليونان تصف الشخص نفسه لا الفعل وحده.","de":"Es ähnelt Ehrbegriffen anderer Kulturen, beschreibt in Griechenland aber den Menschen selbst und nicht nur eine Handlung.","en":"It resembles honour words in other cultures, but in Greece it labels the person, not just the deed."},"expression":{"original":"Φιλότιμο","language":"Ελληνικά (Greek)","gloss":{"ar":"إحساس بالشرف والكرم","de":"Gefühl von Ehre und Großzügigkeit","en":"sense of honour and generosity"},"usage":{"ar":"تُقال لمدح من يتصرف بنبل دون طلب، أو بسخرية لمن يصرّ على رأيه.","de":"Als Lob für selbstloses Handeln oder ironisch für Menschen, die auf ihrer Art bestehen.","en":"Said to praise selfless behaviour, or ironically about someone who insists on their own way."},"transliteration":"filotimo"}},{"id":"lng-057","version":2,"slug":"da-net-the-russian-answer-that-says-no-and-implies-yes","contentType":"detail","category":"communication","title":{"ar":"دا نت: الرفض الروسي الذي يبدأ بالموافقة","de":"Da net: die russische Antwort, die Ja sagt und Nein meint","en":"Da net: the Russian answer that says no and implies yes"},"deck":{"ar":"في المحادثة الروسية، كلمتان قصيرتان تحملان مفاوضات كاملة، وتعتمد على النبرة.","de":"Zwei kurze Wörter können im Russischen eine ganze Verhandlung tragen – alles hängt von der Intonation ab.","en":"Two short words can carry a whole negotiation in Russian conversation, and it all depends on intonation."},"teaser":{"ar":"دا نت (نعم لا) رد شائع يبدأ بالموافقة وينتهي بالرفض، ومعناه يعتمد كليًا على النبرة.","de":"Da net (ja, nein) ist eine häufige Antwort, die mit Zustimmung beginnt und mit Ablehnung endet; die Bedeutung hängt ganz von der Intonation ab.","en":"Da net (yes, no) is a common reply that begins with agreement and ends with refusal, and its meaning depends entirely on intonation."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يعمل الرفض المزدوج","paragraphs":["دا نت (نعم لا) هو رد شائع يبدأ بالموافقة وينتهي بالرفض. بنبرة هابطة قد يعني لا، بحزم. بنبرة صاعدة قد يعني نعم، لكن، وهكذا يقدم المتحدثون استدراكًا.","يستخدم الروس أيضًا دا نت، navernoye (نعم لا، ربما) لتخفيف رفض ليسوا متأكدين منه. الأداة -to وكلمة konechno (بالطبع) تضيف طبقات أخرى، لذا يمكن لرد من كلمتين أن يحمل مفاوضة كاملة."]},{"heading":"التسامح مع الخلاف","paragraphs":["المحادثة الروسية تتسامح مع الخلاف بشكل أكثر علنية من许多 السجلات الأوروبية الشمالية، والرفض المسطح ليس بالضرورة وقحًا. تختلف أنماط النبرة حسب المنطقة والجيل، ودا نت المكتوبة تفقد النبرة التي تجعلها مفهومة؛ الشباب الروس على الإنترنت يستبدلونها غالبًا برموز تعبيرية أو شرطة."]}],"de":[{"heading":"Wie die doppelte Verneinung funktioniert","paragraphs":["Da net (ja, nein) ist eine häufige Antwort, die mit Zustimmung beginnt und mit Ablehnung endet. Mit fallender Tonhöhe kann es ein festes Nein bedeuten; mit steigender Fortsetzung kann es Ja, aber heißen, womit Sprecher eine Einschränkung einführen.","Russen verwenden auch da net, navernoye (ja nein, wahrscheinlich), um eine Ablehnung abzuschwächen, bei der sie unsicher sind. Die Partikel -to und das Wort konechno (natürlich) fügen weitere Ebenen hinzu, sodass eine Zwei-Wort-Antwort eine ganze Verhandlung transportieren kann."]},{"heading":"Toleranz gegenüber Widerspruch","paragraphs":["Die russische Konversation toleriert Widerspruch offener als viele nordeuropäische Register, und ein flaches Nein ist nicht unbedingt unhöflich. Intonationsmuster variieren je nach Region und Generation, und geschriebenes da net verliert den Ton, der es verständlich macht; jüngere Russen ersetzen es online oft durch Emojis oder einen Gedankenstrich."]}],"en":[{"heading":"How the double answer works","paragraphs":["Da net (yes, no) is a common reply that begins with agreement and ends with refusal. With a falling tone it can mean no, firmly; with a rising continuation it can mean yes, but, which is how speakers introduce a qualification.","Russians also use da net, navernoye (yes no, probably) to soften a refusal that the speaker is not certain about. The particle -to and the word konechno (of course) add further layers, so a two-word answer can carry a whole negotiation."]},{"heading":"Tolerance for disagreement","paragraphs":["Russian conversation tolerates disagreement more openly than many northern European registers, and a flat no is not necessarily rude. Intonation patterns vary by region and generation, and written da net loses the tone that makes it intelligible; younger Russians online often replace it with emoji or a dash."]}]},"context":{"countries":["RU"],"region":"Nationwide","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Russian language","de":"Russian language","en":"Russian language"},"url":"https://en.wikipedia.org/wiki/Russian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Yes and no","de":"Yes and no","en":"Yes and no"},"url":"https://en.wikipedia.org/wiki/Yes_and_no","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميل في موسكو سُئل إن كان الموعد النهائي واقعيًا فأجاب دا نت، ومدير المشروع يسمع أن الموعد مستحيل لكن الفريق سيحاول، وهذا بالضبط ما كانت تفعله الكلمتان.","de":"Ein Moskauer Kollege antwortet auf die Frage, ob eine Frist realistisch sei, mit da net, und der Projektmanager hört, dass die Frist unmöglich ist, das Team es aber versuchen wird – genau das leisteten die zwei Wörter.","en":"A Moscow colleague asked whether a deadline is realistic answers da net, and the project manager hears that the deadline is impossible but the team will try, which is exactly what the two words were doing."},"misunderstanding":{"ar":"غالبًا ما يُفسر غير الناطقين بالروسية دا نت على أنها موافقة، لأنها تبدأ بنعم، لكنها في الواقع رفض مع استدراك.","de":"Nicht-Muttersprachler deuten da net oft als Zustimmung, weil es mit Ja beginnt, aber es ist tatsächlich eine Ablehnung mit Einschränkung.","en":"Non-native speakers often interpret da net as agreement because it starts with yes, but it is actually a refusal with a qualification."},"comparison":{"ar":"في حين أن الرفض في العديد من الثقافات الشمالية الأوروبية قد يكون مباشرًا، فإن الروس يستخدمون دا نت لتخفيف الرفض مع الحفاظ على نية واضحة.","de":"Während Ablehnung in vielen nordeuropäischen Kulturen direkt sein kann, verwenden Russen da net, um eine Ablehnung abzuschwächen und dennoch klare Absicht zu bewahren.","en":"While refusal in many northern European cultures may be direct, Russians use da net to soften a refusal while maintaining clear intent."},"expression":{"original":"Да нет, наверное","language":"Русский (Russian)","gloss":{"ar":"حسنًا، لا، ربما","de":"na ja, nein, wahrscheinlich","en":"well, no, probably"},"usage":{"ar":"تستخدم لتخفيف رفض غير مؤكد، وغالبًا ما تسبق تفسيرًا أو اعتذارًا.","de":"Wird verwendet, um eine unsichere Ablehnung abzuschwächen, oft gefolgt von einer Erklärung oder Entschuldigung.","en":"Used to soften an uncertain refusal, often followed by an explanation or apology."},"transliteration":"da net, navernoye"}}];

